import React, { Suspense } from 'react';
// BrowserRouter removed - now in RootRouter.jsx
import { Navigate, Route, Routes } from 'react-router-dom';
import { authorizeWorkspace, updateCurrentSession } from '@/_helpers/authorizeWorkspace';
import { authenticationService, tooljetService, licenseService } from '@/_services';
import { withRouter } from '@/_hoc/withRouter';
import { PrivateRoute, AppsRoute, SwitchWorkspaceRoute, MarketplaceRoute, SuperAdminRoute } from '@/Routes';
import { DesktopOnlyPrivateRoute, DesktopOnlyAdminRoute } from '@/Routes/ComposedGuards';
import { HomePage } from '@/HomePage';
import './lazyPageStyles';
import { Authorize } from '@/Oauth2';
import { Authorize as Oauth } from '@/Oauth';
// Viewer import removed - now handled by ViewerApp.jsx
// import { Viewer } from '@/AppBuilder/Viewer/Viewer.jsx';

const TooljetDatabase = React.lazy(() => import('@/TooljetDatabase'));

const ProfileSettingsPage = React.lazy(() => import('@/SettingsPage'));

const MarketplacePage = React.lazy(() => import(/* webpackChunkName: "marketplace" */ '@/MarketplacePage'));
const InstalledPlugins = React.lazy(
  () => import(/* webpackChunkName: "marketplace" */ '@/MarketplacePage/InstalledPlugins')
);
const MarketplacePlugins = React.lazy(
  () => import(/* webpackChunkName: "marketplace" */ '@/MarketplacePage/MarketplacePlugins')
);

const WorkspaceSettings = React.lazy(() => import('@/modules/WorkspaceSettings'));

const WorkspaceConstants = React.lazy(() => import('@/WorkspaceConstants'));

import LayoutRouteWrapper from '@/_ui/Layout/LayoutRouteWrapper';
import SwitchWorkspacePage from '@/HomePage/SwitchWorkspacePage';
import { lt } from 'semver';
import Toast from '@/_ui/Toast';
import { toast } from 'react-hot-toast';
import '@/_styles/theme.scss';
import AppLoader from '@/AppLoader';
import { BreadCrumbContext } from './BreadCrumbContext';

export { BreadCrumbContext };
import 'react-tooltip/dist/react-tooltip.css';
import { getWorkspaceIdOrSlugFromURL } from '@/_helpers/routes';
import ErrorPage from '@/_components/ErrorComponents/ErrorPage';
import { useAppDataStore } from '@/_stores/appDataStore';
import cx from 'classnames';
import useAppDarkMode from '@/_hooks/useAppDarkMode';
import { setFaviconAndTitle } from '@white-label/whiteLabelling';
import {
  onboarding,
  auth,
  InstanceSettings,
  Settings,
  Workflows,
  getDataSourcesRoutes,
  getAuditLogsRoutes,
} from '@/modules';
import './workspaceSettingsStyles';
import { isWorkflowsFeatureEnabled, fetchEdition } from '@/modules/common/helpers/utils';
import { shallow } from 'zustand/shallow';
import useStore from '@/AppBuilder/_stores/store';
import { checkIfToolJetCloud } from '@/_helpers/utils';
import { BasicPlanMigrationBanner } from '@/HomePage/BasicPlanMigrationBanner/BasicPlanMigrationBanner';
import BlankHomePage from '@/HomePage/BlankHomePage.jsx';
import { MigrationBanner } from '@/_components/MigrationBanner';
import { UpgradeInProgress } from '@/_components/UpgradeInProgress';
import { MigrationsPage } from '@/MigrationsPage';
// EmbedApp import removed - now handled by ViewerApp.jsx
// import EmbedApp from '@/AppBuilder/EmbedApp';
import withAdminOrBuilderOnly from '@/GetStarted/withAdminOrBuilderOnly';
import posthogHelper from '@/modules/common/helpers/posthogHelper';
import DesktopOnlyRoute from '@/Routes/DesktopOnlyRoute';
import UpgradePlanModal from '@/modules/common/components/UpgradePlanModal';

const GuardedHomePage = withAdminOrBuilderOnly(BlankHomePage);

const AppWrapper = (props) => {
  const { isAppDarkMode } = useAppDarkMode();
  const { updateIsTJDarkMode, isTJDarkMode } = useStore(
    (state) => ({
      updateIsTJDarkMode: state.updateIsTJDarkMode,
      isTJDarkMode: state.isTJDarkMode,
    }),
    shallow
  );
  // NOTE: BrowserRouter removed - now handled by RootRouter.jsx
  // App.jsx is now wrapped by RootRouter which provides the router context
  return (
    <Suspense fallback={null}>
      <AppWithRouter
        props={props}
        isAppDarkMode={isAppDarkMode} // This is the dark mode only for appbuilder's canvas + viewer
        darkMode={isTJDarkMode} // This is the dark mode of entire platform
        updateIsTJDarkMode={updateIsTJDarkMode}
      />
    </Suspense>
  );
};

class AppComponent extends React.Component {
  constructor(props) {
    super(props);

    this.state = {
      currentUser: null,
      fetchedMetadata: false,
      darkMode: localStorage.getItem('darkMode') === 'true',
      showBanner: false, //Show banner
      // isEditorOrViewer: '',
    };
  }
  updateSidebarNAV = (val) => {
    this.setState({ sidebarNav: val });
  };
  updateMargin() {
    const isAdmin = authenticationService?.currentSessionValue?.admin;
    const isBuilder = authenticationService?.currentSessionValue?.role?.name === 'builder';
    const migrationBannerOnTop = this.state.showMigrationBanner && !this.isEditorOrViewerFromPath();
    const showBannerCondition = ((isAdmin || isBuilder) && this.state.showBanner) || migrationBannerOnTop;
    const marginValue = showBannerCondition ? '25' : '0';
    const marginValueLayout = showBannerCondition ? '35' : '0';
    document.documentElement.style.setProperty('--dynamic-margin', `${marginValue}px`);
    document.documentElement.style.setProperty('--dynamic-margin-2', `${marginValueLayout}px`);
  }

  fetchMetadata = () => {
    tooljetService.fetchMetaData().then((data) => {
      updateCurrentSession({
        instance_id: data?.instance_id,
      });
      useAppDataStore.getState().actions.setMetadata(data);
      localStorage.setItem('currentVersion', data.installed_version);
      this.setState({ tooljetVersion: data.installed_version });
      if (data.latest_version && lt(data.installed_version, data.latest_version) && data.version_ignored === false) {
        this.setState({ updateAvailable: true });
      }
    });
  };

  initTelemetryAndSupport(currentUser) {
    posthogHelper.initPosthog(currentUser);
  }

  async componentDidMount() {
    // Set before a window.location.reload() (e.g. after resolving git sync conflicts) —
    // a toast fired right before a full reload gets torn down with the DOM before it's
    // ever visible, so the message is persisted and shown here once the fresh page mounts.
    const pendingSyncToast = sessionStorage.getItem('sync_success_toast');
    if (pendingSyncToast) {
      sessionStorage.removeItem('sync_success_toast');
      setTimeout(() => toast.success(pendingSyncToast), 500);
    }

    setFaviconAndTitle();
    authorizeWorkspace();
    this.fetchMetadata();
    // check if version is cloud or ee
    const data = localStorage.getItem('currentVersion');
    if (data && data.includes('cloud')) {
      this.setState({
        showBanner: false, // show banner when required for ee or cloud
      });
    }
    setInterval(this.fetchMetadata, 1000 * 60 * 60 * 1);
    this.updateMargin(); // Set initial margin
    let counter = 0;
    let interval;

    interval = setInterval(async () => {
      ++counter;
      const current_user = authenticationService.currentSessionValue?.current_user;
      if (current_user?.id) {
        this.initTelemetryAndSupport(current_user); //Call when currentuser is available
        clearInterval(interval);
      } else if (counter > 10) {
        clearInterval(interval);
      }
    }, 1000);
  }
  // check if its getting routed from editor
  checkPreviousRoute = (route) => {
    if (route.includes('/apps')) {
      return true;
    }
    return false;
  };

  componentDidUpdate(prevProps, prevState) {
    // Check if the current location is the dashboard (homepage)
    if (
      this.props.location.pathname === `/${getWorkspaceIdOrSlugFromURL()}` &&
      prevProps.location.pathname !== `/${getWorkspaceIdOrSlugFromURL()}` &&
      this.checkPreviousRoute(prevProps.location.pathname) &&
      prevProps.location.pathname !== `/:workspaceId`
    ) {
      // Reload the page for clearing already set intervals
      window.location.reload();
    }
    // Update margin when showBanner changes
    this.updateMargin();
    // Update color scheme if darkMode changed
  }

  switchDarkMode = (newMode) => {
    this.props.updateIsTJDarkMode(newMode);
    localStorage.setItem('darkMode', newMode);
  };

  isEditorOrViewerFromPath = () => {
    const pathname = this.props.location.pathname;
    if (pathname.includes('/apps/')) {
      return 'editor';
    }
    if (pathname.includes('/applications/') || pathname.includes('/embed-apps/')) {
      return 'viewer';
    }
    return '';
  };
  setMigrationBannerVisible = (visible) => {
    if (this.state.showMigrationBanner !== visible) this.setState({ showMigrationBanner: visible });
  };
  closeBasicPlanMigrationBanner = () => {
    this.setState({ showBanner: false });
  };
  render() {
    const { updateAvailable, isEditorOrViewer, showBanner, showMigrationBanner } = this.state;
    const { darkMode } = this.props;
    const mergedProps = {
      ...this.props,
      switchDarkMode: this.switchDarkMode,
      darkMode: darkMode,
    };
    let toastOptions = {
      style: {
        maxWidth: '400px',
        overflowWrap: 'anywhere',
      },
    };

    if (isEditorOrViewer === 'viewer' ? this.props.isAppDarkMode : darkMode) {
      toastOptions = {
        className: 'toast-dark-mode',
        style: {
          borderRadius: '10px',
          background: '#333',
          color: '#fff',
          maxWidth: '400px',
          overflowWrap: 'anywhere',
        },
      };
    }
    const { sidebarNav } = this.state;
    const { updateSidebarNAV } = this;
    const isApplicationsPath = window.location.pathname.includes('/applications/');
    const isAdmin = authenticationService?.currentSessionValue?.admin;
    const isBuilder = authenticationService?.currentSessionValue?.role?.name === 'builder';
    return (
      <>
        <div
          className={
            !isApplicationsPath && (isAdmin || isBuilder || (showMigrationBanner && !this.isEditorOrViewerFromPath()))
              ? 'banner-layout-wrapper'
              : ''
          }
        >
          <MigrationBanner
            darkMode={darkMode}
            onVisibilityChange={this.setMigrationBannerVisible}
            floating={!!this.isEditorOrViewerFromPath()}
          />
          {!isApplicationsPath && !this.isEditorOrViewerFromPath() && (isAdmin || isBuilder) && showBanner && (
            <BasicPlanMigrationBanner darkMode={darkMode} closeBanner={this.closeBasicPlanMigrationBanner} />
          )}
          <div
            className={cx('main-wrapper', {
              'theme-dark dark-theme': !this.isEditorOrViewerFromPath() && darkMode,
            })}
            data-cy="main-wrapper"
          >
            {updateAvailable && (
              <div className="alert alert-info alert-dismissible" role="alert">
                <h3 className="mb-1">Update available</h3>
                <p>A new version of ToolJet has been released.</p>
                <div className="btn-list">
                  <a
                    href="https://docs.tooljet.com/docs/setup/upgrade-to-lts"
                    target="_blank"
                    className="btn btn-info"
                    rel="noreferrer"
                  >
                    Read release notes & update
                  </a>
                  <a
                    onClick={() => {
                      tooljetService.skipVersion();
                      this.setState({ updateAvailable: false });
                    }}
                    className="btn"
                  >
                    Skip this version
                  </a>
                </div>
              </div>
            )}
            <BreadCrumbContext.Provider value={{ sidebarNav, updateSidebarNAV }}>
              <Routes>
                {onboarding({ ...this.props, darkMode })}
                {auth({ ...this.props, darkMode })}
                <Route path="/sso/:origin/:configId" exact element={<Oauth {...this.props} />} />
                <Route path="/sso/:origin" exact element={<Oauth {...this.props} />} />
                <Route
                  exact
                  path="/:workspaceId/apps/:slug/:pageHandle?/*"
                  element={
                    <AppsRoute componentType="editor" darkMode={darkMode}>
                      <AppLoader switchDarkMode={this.switchDarkMode} darkMode={darkMode} />
                    </AppsRoute>
                  }
                />

                {/* Layout routes, grouped by the guard each page needs */}
                <Route
                  element={
                    <LayoutRouteWrapper
                      guard={DesktopOnlyPrivateRoute}
                      darkMode={darkMode}
                      switchDarkMode={this.switchDarkMode}
                    />
                  }
                >
                  <Route
                    exact
                    path="/:workspaceId/workspace-constants"
                    element={<WorkspaceConstants darkMode={darkMode} />}
                  />

                  <Route path="/:workspaceId/workspace-settings/*" element={<WorkspaceSettings {...mergedProps} />} />

                  <Route
                    path="settings/*"
                    element={
                      <InstanceSettings switchDarkMode={this.switchDarkMode} darkMode={darkMode} {...this.props} />
                    }
                  />
                  <Route
                    path="/:workspaceId/settings/*"
                    element={
                      <InstanceSettings {...this.props} darkMode={darkMode} switchDarkMode={this.switchDarkMode} />
                    }
                  />

                  <Route
                    exact
                    path="/:workspaceId/profile-settings"
                    element={<ProfileSettingsPage darkMode={darkMode} />}
                  />

                  <Route exact path="/:workspaceId/database" element={<TooljetDatabase />} />
                </Route>

                <Route
                  element={
                    <LayoutRouteWrapper
                      guard={DesktopOnlyAdminRoute}
                      darkMode={darkMode}
                      switchDarkMode={this.switchDarkMode}
                    />
                  }
                >
                  {getAuditLogsRoutes({ ...mergedProps, darkMode })}
                </Route>

                {this.state.tooljetVersion && !checkIfToolJetCloud(this.state.tooljetVersion) && (
                  <Route
                    element={
                      <LayoutRouteWrapper
                        guard={MarketplaceRoute}
                        darkMode={darkMode}
                        switchDarkMode={this.switchDarkMode}
                      />
                    }
                  >
                    <Route exact path="/integrations" element={<MarketplacePage />}>
                      <Route path="installed" element={<InstalledPlugins />} />
                      <Route
                        path="marketplace"
                        element={<DesktopOnlyRoute>{<MarketplacePlugins />}</DesktopOnlyRoute>}
                      />
                    </Route>
                  </Route>
                )}
                {/* VIEWER ROUTES REMOVED - Now handled by ViewerApp.jsx via RootRouter.jsx */}
                {/* These routes are now in ViewerApp.jsx for bundle isolation: */}
                {/* - /applications/:slug/:pageHandle? */}
                {/* - /applications/:slug/versions/:versionId/environments/:environmentId/:pageHandle? */}
                <Route
                  exact
                  path="/oauth2/authorize"
                  element={
                    <PrivateRoute darkMode={darkMode}>
                      <Authorize switchDarkMode={this.switchDarkMode} darkMode={darkMode} />
                    </PrivateRoute>
                  }
                />
                {isWorkflowsFeatureEnabled() && (
                  <Route
                    exact
                    path="/:workspaceId/workflows/*"
                    element={
                      <DesktopOnlyRoute darkMode={darkMode}>
                        <PrivateRoute darkMode={darkMode}>
                          <Workflows switchDarkMode={this.switchDarkMode} darkMode={darkMode} />
                        </PrivateRoute>
                      </DesktopOnlyRoute>
                    }
                  />
                )}
                {/* EE renders migrations inside its instance settings shell (settings/*). */}
                {fetchEdition() === 'ce' && (
                  <Route
                    path="settings/migrations"
                    element={
                      <DesktopOnlyPrivateRoute darkMode={darkMode}>
                        <SuperAdminRoute navigate={this.props.navigate}>
                          <MigrationsPage switchDarkMode={this.switchDarkMode} darkMode={darkMode} />
                        </SuperAdminRoute>
                      </DesktopOnlyPrivateRoute>
                    }
                  />
                )}
                <Route
                  exact
                  path="/:workspaceId/modules"
                  element={
                    <DesktopOnlyRoute darkMode={darkMode}>
                      <PrivateRoute darkMode={darkMode}>
                        <HomePage switchDarkMode={this.switchDarkMode} darkMode={darkMode} appType={'module'} />
                      </PrivateRoute>
                    </DesktopOnlyRoute>
                  }
                />

                {getDataSourcesRoutes({ ...mergedProps, darkMode })}
                {/* DUPLICATE VIEWER ROUTES REMOVED - handled by ViewerApp.jsx */}
                <Route
                  exact
                  path="/:workspaceId/home"
                  element={
                    <DesktopOnlyRoute>
                      <PrivateRoute>
                        <GuardedHomePage
                          switchDarkMode={this.switchDarkMode}
                          darkMode={darkMode}
                          version={this.state.tooljetVersion}
                        />
                      </PrivateRoute>
                    </DesktopOnlyRoute>
                  }
                />

                <Route
                  exact
                  path="/"
                  element={
                    <PrivateRoute darkMode={darkMode}>
                      <Navigate to="/:workspaceId" />
                    </PrivateRoute>
                  }
                />
                <Route
                  exact
                  path="/error/:errorType"
                  element={
                    <UpgradeInProgress>
                      <ErrorPage switchDarkMode={this.switchDarkMode} darkMode={darkMode} />
                    </UpgradeInProgress>
                  }
                />
                <Route
                  exact
                  path="/app-url-archived"
                  element={
                    <SwitchWorkspacePage
                      switchDarkMode={this.switchDarkMode}
                      darkMode={darkMode}
                      archived={true}
                      isAppUrl={true}
                    />
                  }
                />
                <Route
                  exact
                  path="/switch-workspace"
                  element={
                    <SwitchWorkspaceRoute darkMode={darkMode}>
                      <SwitchWorkspacePage switchDarkMode={this.switchDarkMode} darkMode={darkMode} />
                    </SwitchWorkspaceRoute>
                  }
                />
                <Route
                  exact
                  path="/switch-workspace-archived"
                  element={
                    <SwitchWorkspaceRoute darkMode={darkMode}>
                      <SwitchWorkspacePage switchDarkMode={this.switchDarkMode} darkMode={darkMode} archived={true} />
                    </SwitchWorkspaceRoute>
                  }
                />
                <Route
                  exact
                  path="/:workspaceId"
                  element={
                    <PrivateRoute darkMode={darkMode}>
                      <HomePage switchDarkMode={this.switchDarkMode} darkMode={darkMode} appType={'front-end'} />
                    </PrivateRoute>
                  }
                />
                <Route
                  exact
                  path="/:workspaceId/home"
                  element={
                    <DesktopOnlyRoute>
                      <PrivateRoute>
                        <GuardedHomePage
                          switchDarkMode={this.switchDarkMode}
                          darkMode={darkMode}
                          version={this.state.tooljetVersion}
                        />
                      </PrivateRoute>
                    </DesktopOnlyRoute>
                  }
                />
                {/* EMBED APPS ROUTE REMOVED - handled by ViewerApp.jsx */}
                <Route
                  path="*"
                  render={() => {
                    if (authenticationService?.currentSessionValue?.current_organization_id) {
                      return <Navigate to="/:workspaceId" />;
                    }
                    return <Navigate to="/login" />;
                  }}
                />
              </Routes>
            </BreadCrumbContext.Provider>
            <div id="modal-div" />
            <UpgradePlanModal />
          </div>

          <Toast toastOptions={toastOptions} groupErrors={!!this.isEditorOrViewerFromPath()} />
        </div>
      </>
    );
  }
}

export const App = AppWrapper;
const AppWithRouter = withRouter(AppComponent);
