// TODO: split Loader into separate component and remove editor loading state from Editor
export const Editor = ({ id: appId, darkMode, moduleId = 'canvas', switchDarkMode, appType = 'front-end' }) => {
  const isModuleEditor = appType === 'module';
  // Module read-only (Build-with vs Edit) is resolved inside useAppData from the session.
  useAppData(appId, moduleId, darkMode, 'edit', {}, isModuleEditor, isModuleEditor);
  const isEditorLoading = useStore((state) => state.loaderStore.modules[moduleId].isEditorLoading, shallow);
  const currentMode = useStore((state) => state.modeStore.modules[moduleId].currentMode, shallow);
  const hasModuleAccess = useStore((state) => state.license.featureAccess?.modulesEnabled);

  const updateIsTJDarkMode = useStore((state) => state.updateIsTJDarkMode, shallow);
  const setCurrentLayout = useStore((state) => state.setCurrentLayout, shallow);
  const navigate = useNavigate();
  const featureAccess = useStore((state) => state?.license?.featureAccess, shallow);
  const multiPlayerEditEnabled = featureAccess?.multiPlayerEdit ?? false;

  const changeToDarkMode = (newMode) => {
    updateIsTJDarkMode(newMode);
    switchDarkMode(newMode);
  };

  useEffect(() => {
    if (hasModuleAccess === false && isModuleEditor) {
      navigate('/error/restricted');
    }
  }, [hasModuleAccess, isModuleEditor]);

  // Store survives navigation between apps. Keyed on appId so page switches keep the current layout.
  useEffect(() => {
    setCurrentLayout('desktop');
  }, [appId, setCurrentLayout]);
  const currentVersionId = useStore((state) => state.currentVersionId, shallow);

  // Tag every Sentry event raised while the editor is open — including handler/async
  // errors that bypass the FallbackBoundaries — with the AppBuilder context.
  useEffect(() => {
    if (isEditorLoading) return;
    const ctx = getErrorContext();
    const scope = Sentry.getCurrentScope();
    scope.setTags({
      source: 'AppBuilder',
      appId: ctx.appId || 'n/a',
      versionId: ctx.versionId || 'n/a',
      organizationId: ctx.organizationId || 'n/a',
    });
    return () => {
      // Leaving the editor — drop the tags so other pages aren't mislabelled.
      scope.setTags({
        source: undefined,
        appId: undefined,
        versionId: undefined,
        organizationId: undefined,
      });
    };
  }, [isEditorLoading, appId, currentVersionId]);

  useCustomComponentDevPreviewSync(appId);

  //TODO: This can be added to the mode slice and set based on the mode
  if (isEditorLoading) {
    return (
      <div className={cx('apploader', { 'dark-theme theme-dark': darkMode })}>
        <TJLoader />
      </div>
    );
  }
  return (
    <div className={cx('wrapper', { editor: currentMode === 'edit' })}>
      {/* Last-resort boundary — catches anything the panel-level boundaries miss. */}
      <FallbackBoundary label="App builder" location="Editor" darkMode={darkMode}>
        <ModuleProvider moduleId={moduleId} appType={appType} isModuleMode={false} isModuleEditor={isModuleEditor}>
          <Suspense fallback={<div>Loading...</div>}>
            <EditorHeader darkMode={darkMode} appType={appType} />

            <LeftSidebar switchDarkMode={changeToDarkMode} darkMode={darkMode} />
          </Suspense>

          {window?.public_config?.ENABLE_MULTIPLAYER_EDITING === 'true' && multiPlayerEditEnabled && (
            <RealtimeCursors />
          )}
          <DndProvider backend={HTML5Backend}>
            <AppCanvas moduleId={moduleId} appId={appId} switchDarkMode={switchDarkMode} darkMode={darkMode} />
            <QueryPanel darkMode={darkMode} />
            <RightSidebarToggle darkMode={darkMode} />
            <RightSideBar darkMode={darkMode} />
          </DndProvider>
          <Popups darkMode={darkMode} />
        </ModuleProvider>
      </FallbackBoundary>
    </div>
  );
};
