export const Cursor = React.memo(({ x, y, color, name }) => {
  const rCursor = React.useRef(null);

  // Update the point whenever the component updates
  if (rCursor.current) {
    rCursor.current.style.setProperty('transform', `translate(${x}px, ${y}px)`);
