    }));

  const workspaceActions = useWorkspaceBranchesStore((state) => state.actions);
  const workspaceBranches = useWorkspaceBranchesStore((state) => state.branches);

  // Fetch app-specific tags using existing checkForUpdates API
  useEffect(() => {
    if (!appId) {
      setIsLoadingTags(false);
      return;
    }
    setIsLoadingTags(true);
    gitSyncService
      .checkForUpdates(appId)
      .then((data) => {
        const appTags = data?.meta_data?.tags || [];
        setTags(
          appTags.map((tag) => {
            const version = tag.name.split('/').slice(1).join('/');
            return {
              label: version || tag.name,
              commitSha: tag.commit?.sha,
            };
          })
        );
      })
      .catch((err) => {
        console.error('Failed to fetch tags:', err);
        setTags([]);
      })
      .finally(() => setIsLoadingTags(false));
  }, [appId]);

  // Fetch local (non-branch) app versions to list alongside main and git tags
  useEffect(() => {
    if (!appId || !fetchDevelopmentVersions) {
      setIsLoadingVersions(false);
      return;
    }
    setIsLoadingVersions(true);
    fetchDevelopmentVersions(appId)
      .catch((err) => console.error('Failed to fetch versions:', err))
      .finally(() => setIsLoadingVersions(false));
  }, [appId, fetchDevelopmentVersions]);

  // Close dropdown when clicking outside
  useEffect(() => {
    const handleClickOutside = (event) => {
      if (dropdownRef.current && !dropdownRef.current.contains(event.target)) {
        setIsDropdownOpen(false);
      }
    };
    document.addEventListener('mousedown', handleClickOutside);
    return () => document.removeEventListener('mousedown', handleClickOutside);
  }, []);

  // A version "saved" from a feature branch (see createPublishedVersionFromBranchDraft
  // in versions/util.service.ts) is versionType: 'version', but its parent is the
  // BRANCH-type draft it was cloned from. Exclude those here — branching off a
  // branch-sourced snapshot isn't a supported starting point yet.
  const isSourcedFromBranch = (version) => {
    const parentId = version.parentVersionId || version.parent_version_id;
    if (!parentId) return false;
    const parent = developmentVersions.find((v) => v.id === parentId);
    return (parent?.versionType || parent?.version_type) === 'branch';
  };

  const localVersionOptions = developmentVersions
    .filter((version) => (version.versionType || version.version_type) === 'version')
    .filter((version) => !isSourcedFromBranch(version))
    .filter((version) => version.status !== 'DRAFT')
    .map((version) => ({
      label: version.name,
      commitSha: null,
      versionId: version.id,
      isLocalVersion: true,
      status: version.status,
      // AppVersion.status never actually holds 'RELEASED' — the released version is
      // tracked separately via apps.current_version_id (releasedVersionId in the store),
      // same signal VersionDropdownItem.jsx uses.
      isReleased: version.id === releasedVersionId,
    }));

  // Git tags that share a label with a local released version are redundant — the local
  // version entry is richer (it carries a versionId for DB-level branching). Drop the
  // duplicate tag so each version name appears exactly once in the dropdown.
  const localVersionLabels = new Set(localVersionOptions.map((v) => v.label));
  const uniqueTags = tags.filter((t) => !localVersionLabels.has(t.label));
  const dropdownOptions = [LATEST_MAIN_OPTION, ...localVersionOptions, ...uniqueTags];
  const isLoadingOptions = isLoadingTags || isLoadingVersions;

  const validateBranchName = (name) => {
    if (!name || name.trim().length === 0) return 'Branch name is required';
    if (/\s/.test(name)) return 'Branch name cannot contain spaces';
    if (!/^[a-zA-Z0-9_-]+$/.test(name))
      return 'Branch name can only contain letters, numbers, hyphens, and underscores';

    const existsInWorkspace = workspaceBranches.some((b) => b.name?.toLowerCase() === name.toLowerCase());
    const existsInApp = allBranches.some((b) => b.name?.toLowerCase() === name.toLowerCase());
    if (existsInWorkspace || existsInApp) return 'A branch with this name already exists';

    const reservedNames = ['main', 'master', 'head', 'origin'];
    if (reservedNames.includes(name.toLowerCase())) return 'This branch name is reserved';
    return '';
  };

  const handleBranchNameChange = (e) => {
    setBranchName(e.target.value);
    if (validationError) setValidationError('');
  };

  const handleCreateBranch = async () => {
    const error = validateBranchName(branchName);
    if (error) {
      setValidationError(error);
      return;
    }

    setIsCreating(true);
    try {
      const defaultBranch = workspaceBranches.find((b) => b.is_default || b.isDefault);
      const sourceBranchId = defaultBranch?.id || null;

      await workspaceActions.createBranch(
        branchName.trim(),
        sourceBranchId,
        selectedOption.commitSha || undefined,
        selectedOption.isLocalVersion ? appId : undefined,
        selectedOption.isLocalVersion ? selectedOption.versionId : undefined
      );

      toast.success('Creating branch. It will show up in the list once ready.', { style: { maxWidth: '640px' } });
      onClose();
    } catch (error) {
      console.error('Error creating branch:', error);
      if (error?.statusCode === 409) {
        try {
          const parsed = JSON.parse(error?.data?.message || error?.error || '{}');
          if (parsed?.conflictGroups?.length) {
            setConflictGroups(parsed.conflictGroups);
            return;
          }
        } catch {
          /* fall through */
        }
      }
      const msg = error?.data?.message || error?.message || 'Failed to create branch';
      setValidationError(msg);
      toast.error(msg);
    } finally {
      setIsCreating(false);
    }
  };

  const handleKeyDown = (e) => {
    if (e.key === 'Enter' && !isCreating && !isDropdownOpen) {
      handleCreateBranch();
    } else if (e.key === 'Escape' && isDropdownOpen) {
      setIsDropdownOpen(false);
    }
  };

  return (
    <>
      <AlertDialog
        show={true}
        closeModal={onClose}
        title="Create branch"
        checkForBackground={true}
        customClassName="create-branch-modal"
      >
        <div className="create-branch-modal-body">
          {/* Draft warning message */}
          {isDraftVersionActive && (
            <div className="draft-warning-message">
              <SolidIcon name="information" width="16" />
              <span>A draft version exists. Commit or discard it before creating a new branch.</span>
            </div>
          )}

          {/* Create from dropdown — shows "Latest (main)" + local app versions + app-specific git tags */}
          <div className="form-group">
            <label htmlFor="create-from-select" className="form-label">
              Create from
            </label>
            <div className="custom-dropdown" ref={dropdownRef}>
              <button
                type="button"
                className={cx('custom-dropdown-trigger', { 'is-open': isDropdownOpen })}
                onClick={() => setIsDropdownOpen(!isDropdownOpen)}
                disabled={isCreating || isLoadingOptions}
              >
                <div className="custom-dropdown-value">
                  <span className="version-name">{isLoadingOptions ? 'Loading...' : selectedOption.label}</span>
                  {!isLoadingOptions && selectedOption.isDefault && (
                    <span className={cx('status-badge', 'status-badge-draft')}>Default</span>
                  )}
                  {!isLoadingOptions && selectedOption.isLocalVersion && selectedOption.isReleased && (
                    <span className={cx('status-badge', 'status-badge-released')}>Released</span>
                  )}
                </div>
                <SolidIcon name="cheverondown" width="16" />
              </button>
              {isDropdownOpen && (
                <div className="custom-dropdown-menu">
                  {dropdownOptions.map((option, idx) => {
                    const isSelected = option.label === selectedOption.label;
                    return (
                      <div
                        key={idx}
                        className={cx('dropdown-item', { 'is-selected': isSelected })}
                        onClick={() => {
                          setSelectedOption(option);
                          setIsDropdownOpen(false);
                        }}
                      >
                        {isSelected && (
                          <div className="check-icon">
                            <SolidIcon name="tick" width="16" />
                          </div>
                        )}
                        {!isSelected && <div className="check-icon-placeholder" />}
                        <div className="item-content">
                          <div className="item-header">
                            <span className="item-name">{option.label}</span>
                            {option.isDefault && (
                              <span className={cx('status-badge', 'status-badge-draft')}>Default</span>
                            )}
                            {option.isLocalVersion && option.isReleased && (
                              <span className={cx('status-badge', 'status-badge-released')}>Released</span>
                            )}
                          </div>
                        </div>
                      </div>
                    );
                  })}
                </div>
              )}
            </div>
          </div>

          {/* Branch name input */}
          <div className="form-group">
            <label htmlFor="branch-name-input" className="form-label">
              Branch name
            </label>
            <input
              id="branch-name-input"
              type="text"
              className={`branch-modal-form-input ${validationError ? 'form-input-error' : ''}`}
              placeholder="Enter branch name"
              value={branchName}
              onChange={handleBranchNameChange}
              onKeyDown={handleKeyDown}
              disabled={isCreating}
              autoFocus
              data-cy="branch-name-input"
            />
            {validationError && <div className="form-error-message">{validationError}</div>}
            <div className="form-helper-text">Branch name must be unique and max 50 characters</div>
          </div>

          {/* Auto-commit checkbox */}
          <div className="form-group">
            <label className="checkbox-label">
              <input type="checkbox" className="form-checkbox" checked={true} disabled={true} />
              <span className="checkbox-text">
                Commit changes
                <span className="checkbox-helper">
                  Branch will always be created in git to ensure sync with ToolJet
                </span>
              </span>
            </label>
          </div>

          {/* Info message */}
          <Alert placeSvgTop={true} svg="warning-icon" cls="create-branch-info">
            Branch can only be created from {defaultGitBranch}
          </Alert>

          {/* Footer buttons */}
          <div className="col d-flex justify-content-end gap-2 mt-3">
            <ButtonSolid variant="tertiary" onClick={onClose} disabled={isCreating} size="md" data-cy="cancel-button">
              Cancel
            </ButtonSolid>
            <ButtonSolid
              variant="primary"
              onClick={handleCreateBranch}
              disabled={isCreating || isDraftVersionActive || !branchName.trim() || isLoadingOptions}
              isLoading={isCreating}
              size="md"
              data-cy="create-branch-button"
            >
              Create branch
            </ButtonSolid>
          </div>
        </div>
      </AlertDialog>

      <PullConflictModal
        show={!!conflictGroups}
        conflictGroups={conflictGroups || []}
        onClose={() => setConflictGroups(null)}
        context="branch-creation"
      />
    </>
  );
}
import React, { useState } from 'react';
import { ToolTip } from '@/_components';
import { appsService } from '@/_services';
import { toast } from 'react-hot-toast';
import useStore from '@/AppBuilder/_stores/store';
import { shallow } from 'zustand/shallow';
import { useModuleContext } from '@/AppBuilder/_contexts/ModuleContext';
import { AppModal } from '@/_components/AppModal';
import { PenLine, TriangleAlert } from 'lucide-react';
import { useWorkspaceBranchesStore } from '@/_stores/workspaceBranchesStore';

function EditAppName() {
  const { moduleId, appType } = useModuleContext();
  const [appId, appName, setAppName, appCreationMode, selectedVersion, orgGit] = useStore(
    (state) => [
      state.appStore.modules[moduleId].app.appId,
      state.appStore.modules[moduleId].app.appName,
      state.setAppName,
      state.appStore.modules[moduleId].app.creationMode,
      state.selectedVersion,
      state.orgGit,
    ],
    shallow
  );

  const workspaceActiveBranch = useWorkspaceBranchesStore((state) => state.currentBranch);
  const isMultiBranchingEnabled = useWorkspaceBranchesStore((state) => state.isMultiBranchingEnabled);
  const defaultBranchName = orgGit?.git_https?.github_branch || 'main';

  const isDraftVersion = selectedVersion?.status === 'DRAFT';
  const isGitSyncEnabled = orgGit?.git_https?.is_enabled || orgGit?.git_lab?.is_enabled;
  const isOnDefaultBranch = workspaceActiveBranch
    ? workspaceActiveBranch.is_default ||
      workspaceActiveBranch.isDefault ||
      workspaceActiveBranch.name === defaultBranchName
    : selectedVersion?.versionType !== 'branch';
  const isVersionUnsynced = selectedVersion?.isSynced === false;
  // Workspace-level git sync: every app in a git-enabled org participates in git. Rename requires a
  // draft version regardless of git state. The default branch is read-only ONLY in MULTI-branch mode
  // (rename must happen on a feature branch); in single-branch the default branch is the working
  // branch and rename is allowed (mirrors the dashboard app card — AppMenu isWorkspaceBranchLocked).
  // Exception: unsynced apps (pre-git / never pushed) may be renamed even on the default branch.
  const isRenameDisabled = !isGitSyncEnabled
    ? false
    : !isDraftVersion || (isMultiBranchingEnabled && isOnDefaultBranch && !isVersionUnsynced);

  const getDisabledTooltipMessage = () => {
    if (isGitSyncEnabled && isMultiBranchingEnabled && isOnDefaultBranch && !isVersionUnsynced) {
      return "Renaming isn't allowed on default branch. Switch branch to update name.";
    }
    if (!isDraftVersion && isGitSyncEnabled) {
      return 'Renaming of app is only allowed on draft versions';
    }
    return appName;
  };

  const [showRenameModal, setShowRenameModal] = useState(false);

  const handleRenameApp = async (newAppName, appId) => {
    const sanitizedName = newAppName?.trim().replace(/\s+/g, ' ');

    // Prevent unnecessary API call if the name effectively hasn't changed
    if (sanitizedName === appName) {
      setShowRenameModal(false);
      return true;
    }
    try {
      await appsService.saveApp(appId, { name: sanitizedName, editingVersionId: selectedVersion?.id });
      setAppName(sanitizedName);
      toast.success(`${appType === 'module' ? 'Module' : 'App'} name has been updated!`);
      return true;
    } catch (errorResponse) {
      if (errorResponse.statusCode === 409) {
        return false;
      }
      if (errorResponse.statusCode !== 451) {
        throw errorResponse;
      }
    }
  };

  return (
    <>
      <div className="tw-h-full tw-flex tw-items-start tw-justify-start">
        <ToolTip
          message={getDisabledTooltipMessage()}
          placement="bottom"
          maxWidth="210px"
          isVisible={appCreationMode !== 'GIT' || isRenameDisabled}
        >
          <button
            className="edit-app-name-button tw-h-8 tw-min-w-[100px] tw-max-w-[240px] tw-rounded-lg tw-pr-1 tw-w-auto tw-font-medium tw-outline-none tw-bg-transparent tw-border tw-border-transparent tw-shadow-none tw-group tw-transition-all tw-duration-300 tw-flex tw-items-center tw-relative tw-justify-start"
            style={{
              cursor: isRenameDisabled ? 'not-allowed' : 'pointer',
              opacity: isRenameDisabled ? 0.6 : 1,
            }}
            type="button"
            data-cy="edit-app-name-button"
            onClick={() => !isRenameDisabled && setShowRenameModal(true)}
            disabled={isRenameDisabled}
          >
            <span
              className="tw-font-title-large tw-truncate tw-w-full tw-block tw-text-start group-hover:tw-w-[calc(100%-24px)] tw-text-[var(--slate12)]"
              data-cy="editor-app-name-input"
            >
              {appName}
            </span>
            {!isRenameDisabled && (
              <span className="tw-absolute tw-right-0.5 tw-top-1 tw-text-icon-default tw-hidden group-hover:tw-block tw-w-7 tw-h-7 tw-items-center tw-justify-center">
                <PenLine width="16" height="16" name="pencil" />
              </span>
            )}
          </button>
        </ToolTip>
      </div>

      {showRenameModal && (
        <AppModal
          show={showRenameModal}
          closeModal={() => setShowRenameModal(false)}
          processApp={handleRenameApp}
          selectedAppId={appId}
          selectedAppName={appName}
          title={appType === 'module' ? 'Rename module' : 'Rename app'}
          titleAdornment={(() => {
            const { currentBranch } = useWorkspaceBranchesStore.getState();
            const isOnFeatureBranch = currentBranch && !currentBranch.is_default && !currentBranch.isDefault;
            if (!isOnFeatureBranch) return null;
            return (
              <ToolTip
                message="This is a global setting which follows the same PR flow but are not version controlled, they apply across all versions once merged."
                placement="top"
                width="272px"
              >
                <span className="tw-inline-flex tw-items-center tw-ml-2">
                  <TriangleAlert size={18} className="tw-text-[var(--icon-warning)]" />
                </span>
              </ToolTip>
            );
          })()}
          actionButton={appType === 'module' ? 'Rename module' : 'Rename app'}
          actionLoadingButton={'Renaming'}
          appType={appType}
        />
      )}
    </>
  );
}

