import React, { useState } from 'react';
import AlertDialog from '@/_ui/AlertDialog';
import { toast } from 'react-hot-toast';
import { useTranslation } from 'react-i18next';
import { shallow } from 'zustand/shallow';
import useStore from '@/AppBuilder/_stores/store';
import { useModuleContext } from '@/AppBuilder/_contexts/ModuleContext';
import { ButtonSolid } from '@/_ui/AppButton/AppButton';

const EditVersionModal = ({ showEditAppVersion, setShowEditAppVersion, versionToEdit }) => {
  const { moduleId } = useModuleContext();
  const [isEditingVersion, setIsEditingVersion] = useState(false);
  const { updateVersionNameAction, selectedVersion, appId } = useStore(
    (state) => ({
      updateVersionNameAction: state.updateVersionNameAction,
      selectedVersion: state.selectedVersion,
      appId: state.appId ?? state.appStore.modules[moduleId]?.app?.appId,
    }),
    shallow
  );

  // Use versionToEdit if provided, otherwise fall back to selectedVersion
  const editingVersion = versionToEdit || selectedVersion;

  const [versionName, setVersionName] = useState(editingVersion?.name || '');
  const [versionDescription, setVersionDescription] = useState(editingVersion?.description || '');
  const [nameError, setNameError] = useState('');
  const [descriptionError, setDescriptionError] = useState('');
  const { t } = useTranslation();

  const validateVersionName = (value) => {
    if (value.trim() === '') {
      return t('editor.appVersionManager.emptyNameError', 'Version name should not be empty');
    } else if (value.length > 25) {
      return t('editor.appVersionManager.maxLengthError', 'Version name cannot exceed 25 characters');
    } else if (/[\s~^:?*[\]\\@{]/.test(value.trim())) {
      return 'Version name cannot contain spaces or special characters (~ ^ : ? * [ \\ @ {).';
    }
    return '';
  };

  const validateVersionDescription = (value) => {
    if (value.length > 500) {
      return t('editor.appVersionManager.maxDescriptionLengthError', 'Description cannot exceed 500 characters');
    }
    return '';
  };

  React.useEffect(() => {
    // Update form when modal opens or when the version to edit changes
    if (showEditAppVersion && editingVersion) {
      setVersionName(editingVersion?.name || '');
      setVersionDescription(editingVersion?.description || '');
      setNameError('');
      setDescriptionError('');
    }
  }, [editingVersion?.id, editingVersion?.name, editingVersion?.description, showEditAppVersion, editingVersion]);

  const editVersion = () => {
    setNameError('');
    setDescriptionError('');

    let hasError = false;
    const hasNameError = validateVersionName(versionName);
    const hasDescriptionError = validateVersionDescription(versionDescription);

    if (hasDescriptionError) {
      setDescriptionError(hasDescriptionError);
      toast.error(hasDescriptionError);
      hasError = true;
    }
    if (hasNameError) {
      setNameError(hasNameError);
      toast.error(hasNameError);
      hasError = true;
    }

    if (hasError) return;

    setIsEditingVersion(true);
    updateVersionNameAction(
      appId,
      editingVersion?.id,
      versionName,
      versionDescription,
      () => {
        toast.success('Version details updated successfully!');
        setIsEditingVersion(false);
        setShowEditAppVersion(false);
      },
      (error) => {
        setIsEditingVersion(false);
        const errorMessage =
          error?.error === 'Already exists!'
            ? 'Version already exists!'
            : t('editor.appVersionManager.updateFailed', 'Failed to update version');
        setNameError(errorMessage);
        toast.error(errorMessage);
      }
    );
  };

  return (
    <AlertDialog
      show={showEditAppVersion}
      closeModal={() => {
        setVersionName(editingVersion?.name || '');
        setVersionDescription(editingVersion?.description || '');
        setNameError('');
        setDescriptionError('');
        setShowEditAppVersion(false);
      }}
      checkForBackground={true}
      title={t('editor.appVersionManager.editVersion', 'Edit Version')}
      customClassName="edit-version-modal"
    >
      <form
        onSubmit={(e) => {
          e.preventDefault();
          editVersion();
        }}
      >
        <div className="row mb-3">
          <div className="col modal-main tj-app-input version-name">
            <label className="form-label" data-cy="version-name-label">
              {t('editor.appVersionManager.versionName', 'Version Name')}
            </label>
            <input
              type="text"
              onChange={(e) => {
                const value = e.target.value;
                setVersionName(value);
                setNameError(validateVersionName(value));
              }}
              className="form-control"
              data-cy="edit-version-name-input-field"
              placeholder={t('editor.appVersionManager.enterVersionName', 'Enter version name')}
              disabled={isEditingVersion}
              value={versionName}
              maxLength={25}
            />
            <small
              className={`version-description-helper-text ${nameError ? 'text-danger' : ''}`}
              data-cy="version-name-helper-text"
            >
              {nameError
                ? nameError
                : t('editor.appVersionManager.versionNameHelper', 'Version name must be unique and max 25 characters')}
            </small>
          </div>
        </div>
        <div className="row mb-3">
          <div className="col modal-main tj-app-input version-description">
            <label className="form-label" data-cy="version-description-label">
              {t('editor.appVersionManager.versionDescription', 'Version description')}
            </label>
            <textarea
              type="text"
              onChange={(e) => {
                setVersionDescription(e.target.value);
                setDescriptionError(validateVersionDescription(e.target.value));
              }}
              className="form-control edit-version-description"
              data-cy="edit-version-description-input-field"
              placeholder={t('editor.appVersionManager.enterVersionDescription', 'Enter version description')}
              disabled={isEditingVersion}
              value={versionDescription}
              maxLength={500}
            />
            <small
              className={`version-description-helper-text ${descriptionError ? 'text-danger' : ''}`}
              data-cy="version-description-helper-text"
            >
              {descriptionError
                ? descriptionError
                : t('editor.appVersionManager.versionDescriptionHelper', 'Description must be max 500 characters')}
            </small>
          </div>
        </div>

        <div className="edit-version-footer">
          <hr className="section-divider" style={{ marginLeft: '-1.5rem', marginRight: '-1.5rem' }} />

          <div className="col d-flex justify-content-end">
            <ButtonSolid
              size="lg"
              data-cy="cancel-button"
              type="button"
              variant="tertiary"
              className="mx-2"
              onClick={() => {
                setVersionName(editingVersion?.name || '');
                setVersionDescription(editingVersion?.description || '');
                setNameError('');
                setDescriptionError('');
                setShowEditAppVersion(false);
              }}
            >
              {t('globals.cancel', 'Cancel')}{' '}
            </ButtonSolid>

            <ButtonSolid size="lg" data-cy="save-button" type="submit" variant="primary">
              {t('editor.update', 'Update')}
            </ButtonSolid>
          </div>
        </div>
      </form>
    </AlertDialog>
  );
};
export default EditVersionModal;
import React, { useRef, useState, useEffect, useMemo } from 'react';
import cx from 'classnames';
import { OverlayTrigger, Popover } from 'react-bootstrap';
import SolidIcon from '@/_ui/Icon/SolidIcons';
import {
  PromoteVersionButton,
  ReleaseVersionButton,
} from '@/modules/common/components/BasePromoteReleaseButton/components';
import useStore from '@/AppBuilder/_stores/store';
import { useVersionManagerStore } from '@/_stores/versionManagerStore';
import { useWorkspaceBranchesStore } from '@/_stores/workspaceBranchesStore';
import { useGitSyncConfig } from '@/AppBuilder/_hooks/useGitSyncConfig';
import { normalizePin } from '@/AppBuilder/Widgets/libraryComponentRevision';
import { ToolTip } from '@/_components/ToolTip';
import { Button } from '@/components/ui/Button/Button';
import { IconArrowBarToDown } from '@tabler/icons-react';
import { useModuleContext } from '@/AppBuilder/_contexts/ModuleContext';

const VersionDropdownItem = ({
  version,
  isSelected,
  isViewingCurrentEnvironment = true, // Default to true for backward compatibility
  onSelect,
  onRelease,
  onDelete,
  onEdit,
  onCreateVersion,
  currentEnvironment,
  environments = [],
  showActions = true,
  darkMode = false,
  openMenuVersionId,
  setOpenMenuVersionId,
  gitStatus,
  onPull,
  isPulling = false,
}) => {
  const releasedVersionId = useStore((state) => state.releasedVersionId);
  const versions = useVersionManagerStore((state) => state.versions);
  const developmentVersions = useStore((state) => state.developmentVersions);
  const featureAccess = useStore((state) => state.license.featureAccess);
  const isEditorReadOnly = useStore((state) => state.isEditorReadOnly);
  const { appType } = useModuleContext();
  const { isGitSyncEnabled, defaultBranch } = useGitSyncConfig();
  const customComponentLibraries = useStore((state) => state.globalSettings?.customComponentLibraries);

  const isDraft = version.status === 'DRAFT';
  const isPublished = version.status === 'PUBLISHED';
  // Unsynced apps (never pushed to git) behave like a non-git workspace — show the real
  // version name instead of the default-branch label. isSynced propagates from the source
  // version at creation time (see `createVersion` in versions/util.service.ts).
  const isGitSyncDraft = isDraft && isGitSyncEnabled && version.isSynced !== false;
  // True when any default-branch version has been pushed to git. Feature-branch
  // versions have isSynced=false by default, so scoping to versionType='version'
  // avoids false negatives on apps that only have branch versions locally.
  const isAppSyncedToGit = developmentVersions?.some(
    (v) =>
      (v.isSynced === true || v.is_synced === true) && (v.versionType === 'version' || v.version_type === 'version')
  );
  const displayName = isGitSyncDraft ? defaultBranch : version.name;
  const effectiveDescription = isGitSyncDraft ? 'Latest commit to main will appear here' : version.description;
  // A version is released when it matches the releasedVersionId
  const isReleased = version.id === releasedVersionId;
  const isEditDisabled = appType === 'module' && !isDraft;

  // Get parent version name - search in both current environment versions and development versions
  // This ensures we can find the parent even if it's in a different environment
  const parentVersion = version.parentVersionId
    ? versions.find((v) => v.id === version.parentVersionId) ||
      developmentVersions.find((v) => v.id === version.parentVersionId)
    : null;
  const createdFromVersionName = parentVersion?.name || version.createdFromVersion;

  // Versions saved from a feature branch (see createPublishedVersionFromBranchDraft in
  // versions/util.service.ts) have a BRANCH-type parent whose own `name` is a random
  // UUID, not a human name — the real branch name lives on WorkspaceBranch. Surface
  // that as a tag instead of the generic "created from <uuid>" line.
  const parentIsBranchVersion = parentVersion?.versionType === 'branch' || parentVersion?.version_type === 'branch';
  const workspaceBranches = useWorkspaceBranchesStore((state) => state.branches);
  const sourceBranchId = parentVersion?.branchId || parentVersion?.branch_id;
  const sourceBranchName = parentIsBranchVersion
    ? (workspaceBranches.find((b) => b.id === sourceBranchId)?.name ?? 'feature-branch')
    : null;

  const metadataRef = useRef(null);
  const [showMetadataTooltip, setShowMetadataTooltip] = useState(false);
  const [isHoveringActionButtons, setIsHoveringActionButtons] = useState(false);
  const [isMoreMenuOpen, setIsMoreMenuOpen] = useState(false);
  const [isHoveringItem, setIsHoveringItem] = useState(false);

  // Close menu when scrolling
  useEffect(() => {
    if (openMenuVersionId === version.id) {
      const handleScroll = () => {
        setOpenMenuVersionId?.(null);
      };

      // Find the scrollable versions list container
      const scrollContainer = document.querySelector('.versions-list');
      if (scrollContainer) {
        scrollContainer.addEventListener('scroll', handleScroll);
        return () => scrollContainer.removeEventListener('scroll', handleScroll);
      }
    }
  }, [openMenuVersionId, version.id, setOpenMenuVersionId]);

  // Check if metadata text is overflowing
  useEffect(() => {
    const checkOverflow = () => {
      if (metadataRef.current) {
        const isOverflowing = metadataRef.current.scrollWidth > metadataRef.current.clientWidth;
        setShowMetadataTooltip(isOverflowing);
      }
    };

    checkOverflow();
    window.addEventListener('resize', checkOverflow);
    return () => window.removeEventListener('resize', checkOverflow);
  }, [version.description, createdFromVersionName]);

  // Determine if we should show promote button based on environment logic
  const currentEnvData = environments.find((env) => env.id === currentEnvironment?.id);
  const currentPriority = currentEnvData?.priority || 1;
  const isInProduction = currentPriority === 3; // Production has priority 3

  const isVersionInCurrentEnv = version.currentEnvironmentId === currentEnvironment?.id;
  const shouldShowActionButtons = isViewingCurrentEnvironment && isSelected && isVersionInCurrentEnv;

  // In CE edition: show Release button for PUBLISHED versions that are not yet released
  // In EE edition: show Promote button for non-released versions in non-production environments
  const canPromote =
    shouldShowActionButtons && featureAccess?.multiEnvironment && !isDraft && !isReleased && !isInProduction;
  const canRelease =
    shouldShowActionButtons &&
    !isDraft &&
    !isReleased &&
    (featureAccess?.multiEnvironment ? isInProduction : isPublished);
  const canCreateVersion = isDraft; // Show create version button for drafts
  const canOpenMoreMenu = !isEditorReadOnly; // Build-with: no-op edit/delete actions, hide entirely

  const devPinnedLibrariesCount = useMemo(() => {
    const pins = customComponentLibraries ?? {};
    // normalizePin handles legacy pins stored as { revisionId: 'dev:...' } — without it,
    // an imported/older object-shaped dev pin slips past this check and can be saved
    // into an app version, defeating the dev-build guard below.
    return Object.values(pins).filter((value) => {
      const pin = normalizePin(value);
      return typeof pin === 'string' && pin.startsWith('dev:');
    }).length;
  }, [customComponentLibraries]);

  const isSaveVersionBlockedByDevPin = canCreateVersion && devPinnedLibrariesCount > 0;

  const renderMenu = (
    <Popover
      id={cx(`popover-positioned-bottom-end`, { 'dark-theme theme-dark': darkMode })}
      className={cx({ 'dark-theme theme-dark': darkMode })}
      style={{ minWidth: '160px', zIndex: 1065 }}
    >
      <Popover.Body className={cx('d-flex flex-column p-0', { 'dark-theme theme-dark': darkMode })}>
        {!isGitSyncDraft && isDraft && (
          <ToolTip message="Saved versions cannot be edited" placement="left" show={isEditDisabled}>
            <div
              className={cx('dropdown-item tj-text-xsm', {
                'cursor-pointer': !isEditDisabled,
                'cursor-not-allowed': isEditDisabled,
                'dark-theme theme-dark': darkMode,
