              aria-disabled={isEditDisabled}
              data-cy={`${version.name.toLowerCase().replace(/\s+/g, '-')}-edit-version-button`}
            >
              Edit details
            </div>
          </ToolTip>
        )}
        {!isReleased && (
          <div
            className={cx('dropdown-item cursor-pointer tj-text-xsm text-danger', {
