          fontWeight: 500,
          fontSize: '12px',
          lineHeight: '18px',
          color: 'var(--text-default)',
        }}
      >
        {version.name}
      </div>
      <div style={{ padding: '12px 12px 8px' }}>
        {sourceBranchName ? (
          <div
            style={{
              fontSize: '12px',
              lineHeight: '18px',
              color: 'var(--text-default)',
              marginBottom: '4px',
              fontWeight: 400,
            }}
          >
            Version created from {sourceBranchName}
          </div>
        ) : (
          createdFromVersionName && (
            <div
              style={{
                fontSize: '12px',
                lineHeight: '18px',
                color: 'var(--text-default)',
                marginBottom: '4px',
                fontWeight: 400,
              }}
            >
              created from {createdFromVersionName}
            </div>
          )
        )}
        {version.description && (
          <div
            style={{
              fontSize: '12px',
              lineHeight: '18px',
              color: 'var(--text-placeholder)',
              whiteSpace: 'pre-wrap',
              wordBreak: 'break-word',
            }}
          >
            {version.description}
          </div>
        )}
      </div>
    </div>
  );

  const versionItem = (
    <div
      className={cx('version-dropdown-item', {
        'cursor-pointer': !isDisabled,
        'cursor-default': isDisabled,
        'git-only': isDisabled,
      })}
      onClick={() => !isDisabled && onSelect(version)}
      onMouseEnter={() => setIsHoveringItem(true)}
