                  whiteSpace: 'nowrap',
                }}
                data-cy={`${version.name.toLowerCase().replace(/\s+/g, '-')}-version-name`}
              >
                {displayName}
              </div>

              {/* Source branch tag — this version was saved from a feature branch draft */}
              {sourceBranchName && (
