                  cyLabel={`canvas-bg-colour`}
                  initialValue={backgroundFxQuery ? backgroundFxQuery : canvasBackgroundColor}
                  lang="javascript"
                  className="canvas-hinter-wrap"
                  lineNumbers={false}
                  onChange={(color) => {
                    const options = {
