import React, { useEffect, useState } from 'react';
import { Form, Popover, Col, OverlayTrigger, Tooltip } from 'react-bootstrap';
import Information from '@/_ui/Icon/solidIcons/Information';
import CodeHinter from '@/AppBuilder/CodeEditor';

const isValidVariableName = (str) => /^[a-zA-Z_$][a-zA-Z0-9_$]*$/.test(str);

const ParameterForm = ({
  darkMode,
  isEdit,
  name: _name,
  defaultValue: _defaultValue,
  onSubmit,
  showModal,
  otherParams = [],
}) => {
  const [name, setName] = useState();
  const [defaultValue, setDefaultValue] = useState();
  const [error, setError] = useState();

  useEffect(() => {
    setName(_name);
    setDefaultValue(_defaultValue);
  }, [_name, _defaultValue, showModal]);

  useEffect(() => {
    if (!showModal && !error) {
      onSubmit && onSubmit({ name, defaultValue });
    }
    // eslint-disable-next-line react-hooks/exhaustive-deps
  }, [showModal]);

  const handleSubmit = (event) => {
    event.preventDefault();
    if (!error) {
      onSubmit && onSubmit({ name, defaultValue });
    }
  };

  useEffect(() => {
    if (!isValidVariableName(name)) {
      setError('Variable name invalid');
    } else if (name && otherParams.some((param) => param.name === name.trim())) {
      setError('Variable name exists');
    } else {
      setError();
    }
    // eslint-disable-next-line react-hooks/exhaustive-deps
  }, [name]);

  return (
    <>
      <Popover.Header className={`${darkMode && 'dark-theme'}`}>
        <p className="tj-text-xsm " style={{ fontWeight: '600' }}>
          {isEdit ? 'UPDATE PARAMETER' : 'ADD PARAMETER'}
        </p>
      </Popover.Header>
      <Popover.Body
        className={darkMode && 'dark-theme dark-theme'}
        key={'1'}
        bsPrefix="popover-body"
        style={{ padding: '16px 16px 32px 16px', overflowY: 'auto' }}
      >
        <Form
          className="container p-0 tj-app-input"
          onSubmit={handleSubmit}
          style={{ paddingRight: '25px !important' }}
        >
          <Form.Group as={Col} style={{ display: 'flex' }} className="mb-2 pr-1">
            <Form.Label column htmlFor="paramName" data-cy="parameter-name-label">
              Name
            </Form.Label>
            <Col>
              <Form.Control
                style={{ height: '32px', width: '177px' }}
                type="text"
                aria-describedby="paramName"
                onChange={(event) => setName(event.target.value)}
                value={name}
                data-cy="parameter-name-input"
              />
              {name && error && <div className="invalid-feedback d-block">{error}</div>}
            </Col>
          </Form.Group>
          <Form.Group as={Col} style={{ display: 'flex' }}>
            <Form.Label column htmlFor="defaultValue" style={{ marginRight: '0px' }} data-cy="parameter-value-label">
              Value
              <span className="ms-1">
                <OverlayTrigger
                  placement="bottom"
                  overlay={
                    <Tooltip id="tooltip">
                      Exposed values such as components, queries, globals etc are not supported in this field.Please use
                      constant strings, numbers or objects.
                    </Tooltip>
                  }
                >
                  <span>
                    <Information width="15" fill="var(--indigo9)" />
                  </span>
                </OverlayTrigger>
              </span>
            </Form.Label>
            <Col style={{ padding: '0px', width: '177px' }}>
              <div className="d-flex">
                <div className="" style={{ height: '32px', width: '177px' }}>
                  <CodeHinter
                    onChange={(value) => setDefaultValue(value)}
                    theme={darkMode ? 'monokai' : 'default'}
                    usePortalEditor={false}
                    style={{ height: '32px', width: '177px', marginBotto: '16px' }}
                    initialValue={defaultValue}
                    delayOnChange={false}
                    cyLabel="parameter-value"
                  />
                </div>
              </div>
            </Col>
          </Form.Group>
        </Form>
      </Popover.Body>
    </>
  );
};

export default ParameterForm;
import React, { useEffect, useRef, useState } from 'react';
import ParameterDetails, { PillButton } from './ParameterDetails';
import { OverlayTrigger, Popover } from 'react-bootstrap';
import ParameterForm from './ParameterForm';
import Warning from '@/_ui/Icon/solidIcons/Warning';
import { generateCypressDataCy } from '../../../modules/common/helpers/cypressHelpers.js';

const ParameterList = ({
  parameters = [],
  handleAddParameter,
  handleParameterChange,
  handleParameterRemove,
  darkMode,
  containerRef,
}) => {
  const [showMore, setShowMore] = useState(false);
  const [selectedParameter, setSelectedParameter] = useState();
  const [formattedParameters, setFormattedParameters] = useState([]);
  const containerWidth = containerRef.current?.offsetWidth || 0.8 * document.body.clientWidth - 635;

  useEffect(() => {
    let totalWidth = 0;
    const formattedParams = containerWidth
      ? parameters.map((param, index) => {
          const boxWidth = Math.min((param?.name || '').length * 6 + 63 + 8, 178);
          totalWidth = Math.min(totalWidth + boxWidth, containerWidth);
          return {
            ...param,
            isVisible: totalWidth < containerWidth - 178,
            index,
          };
        })
      : [];
    setFormattedParameters(formattedParams);
    if (formattedParams.every((param) => param.isVisible)) {
      setShowMore(false);
    }
  }, [JSON.stringify(parameters), containerWidth]);

  const handleClickOutside = (event) => {
    if (showMore && event.target.closest('#parameter-more-popover') === null) {
      setShowMore(false);
    }
  };

  useEffect(() => {
    if (showMore) {
      document.addEventListener('mousedown', handleClickOutside);
    } else {
      document.removeEventListener('mousedown', handleClickOutside);
    }
    return () => {
      document.removeEventListener('mousedown', handleClickOutside);
    };
  }, [showMore]);

  return (
    <div className="d-flex">
      <p
        className="text-placeholder font-weight-medium"
        style={{ marginRight: '16px', marginBottom: '0px', width: '100px' }}
        data-cy="query-parameter-label"
      >
        Parameters
      </p>
      {formattedParameters
        .filter((param) => param.isVisible)
        .map((parameter) => {
          return (
            <ParameterDetails
              isEdit
              key={parameter.name}
              onSubmit={(param) => handleParameterChange(parameter.index, param)}
              onRemove={() => handleParameterRemove(parameter.index)}
              name={parameter.name}
              otherParams={formattedParameters.filter((p) => p.name !== parameter.name)}
              defaultValue={parameter.defaultValue}
              // currentState={currentState}
              darkMode={darkMode}
              dataCy={generateCypressDataCy(parameter.name)}
            />
          );
        })}
      {/* {formattedParameters.length === 0 && (
        <div className="empty-paramlist" style={{ background: darkMode && 'var(--interactive-default)' }}>
          <span style={{ marginBottom: '3px' }}>
            <Warning width={'14px'} />
          </span>
          <span style={{ fontSize: '12px' }}>No params added</span>
        </div>
      )} */}
      <OverlayTrigger
        trigger={'click'}
        placement={'bottom-end'}
        rootClose={true}
        show={showMore}
        overlay={
          <Popover
            id="parameter-more-popover"
            className={`query-manager-sort-filter-popup  ${darkMode && 'popover-dark-themed theme-dark dark-theme'}`}
            style={{ minWidth: '270px', maxWidth: 'fit-content' }}
          >
            {selectedParameter ? (
              <ParameterForm
                darkMode={darkMode}
                isEdit={true}
                name={selectedParameter.name}
                defaultValue={selectedParameter.defaultValue}
                onSubmit={(param) => {
                  if (!param?.name) {
                    return;
                  }
                  handleParameterChange(selectedParameter.index, param);
                  setSelectedParameter();
                }}
                showModal={showMore}
              />
            ) : (
              <Popover.Body
                key={'1'}
                bsPrefix="popover-body"
                className={`ps-1 pe-1  py-2 query-manager`}
                style={{ maxWidth: '500px' }}
              >
                {formattedParameters
                  .filter((param) => !param.isVisible)
                  .map((parameter) => {
                    return (
                      <span key={parameter.name} data-list-item-id={parameter.name}>
                        <PillButton
                          name={parameter.name}
                          onRemove={() => handleParameterRemove(parameter.index)}
                          marginBottom
                          onClick={() => setSelectedParameter(parameter)}
                        />
                      </span>
                    );
                  })}
              </Popover.Body>
            )}
          </Popover>
        }
      >
        <span>
          {formattedParameters.some((param) => !param.isVisible) && (
            <PillButton
              name={`+${formattedParameters.reduce((count, param) => count + (!param.isVisible ? 1 : 0), 0)}`}
              onClick={() => setShowMore(true)}
              className="more-parameters-button"
            />
          )}
        </span>
      </OverlayTrigger>
      <ParameterDetails onSubmit={handleAddParameter} darkMode={darkMode} otherParams={formattedParameters} />
    </div>
  );
};

export default ParameterList;
import React, { useEffect, useLayoutEffect, useRef, useState, useMemo } from 'react';
import { JSONTree } from 'react-json-tree';
import { Tab, ListGroup, Row, Col } from 'react-bootstrap';
import { getTheme, tabs } from '../constants';
import ArrowDownTriangle from '@/_ui/Icon/solidIcons/ArrowDownTriangle';
import { useEventListener } from '@/_hooks/use-event-listener';
import { reservedKeywordReplacer } from '@/_lib/reserved-keyword-replacer';
import useStore from '@/AppBuilder/_stores/store';
import { generateCypressDataCy } from '@/modules/common/helpers/cypressHelpers';

const Preview = ({ darkMode, calculatePreviewHeight }) => {
  const [key, setKey] = useState('raw');
  const [isJson, setIsJson] = useState(false);
  const [isDragging, setDragging] = useState(false);
  const [isTopOfPreviewPanel, setIsTopOfPreviewPanel] = useState(false);

  const storedHeight = useStore((state) => state.queryPanel.previewPanelHeight);
  // initialize height with stored height if present in state
  const heightSetOnce = useRef(!!storedHeight);
  const previewPanelExpanded = useStore((state) => state.queryPanel.previewPanelExpanded);
  const setPreviewPanelExpanded = useStore((state) => state.queryPanel.setPreviewPanelExpanded);
  const [height, setHeight] = useState(storedHeight);
  const [theme, setTheme] = useState(() => getTheme(darkMode));
  const queryPreviewData = useStore((state) => state.queryPanel.queryPreviewData);
  const previewLoading = useStore((state) => state.queryPanel.previewLoading);
  const previewPanelRef = useRef();
  const queryPanelHeight = useStore((state) => state.queryPanel.queryPanelHeight);

  useEffect(() => {
    calculatePreviewHeight(height, previewPanelExpanded);
    // eslint-disable-next-line react-hooks/exhaustive-deps
  }, []);

  useEffect(() => {
    setTheme(() => getTheme(darkMode));
  }, [darkMode]);

  useLayoutEffect(() => {
    if (queryPreviewData || previewLoading) {
      previewPanelRef.current.scrollIntoView({
        behavior: 'smooth',
        block: 'start',
        inline: 'nearest',
      });
    }
  }, [queryPreviewData, previewLoading]);

  useEffect(() => {
    if (queryPreviewData !== null && typeof queryPreviewData === 'object') {
      setKey('json');
    } else {
      setKey('raw');
    }
    setIsJson(queryPreviewData !== null && typeof queryPreviewData === 'object');
  }, [queryPreviewData]);

  const renderRawData = () => {
    if (!queryPreviewData) {
      return queryPreviewData === null ? '' : `${queryPreviewData}`;
    } else {
      return isJson
        ? JSON.stringify(queryPreviewData, reservedKeywordReplacer).toString()
        : queryPreviewData.toString();
    }
  };

  useEffect(() => {
    // query panel collapse scenario
    if (queryPanelHeight === 95 || queryPanelHeight === 0) {
      return;
    }
    if (queryPanelHeight - 85 < 40) {
      setHeight(40);
      return;
    }
    if (queryPanelHeight - 85 < height) {
      setHeight((queryPanelHeight - 85) * 0.7);
    } else if (!heightSetOnce.current) {
      setHeight((queryPanelHeight - 85) * 0.7);
      heightSetOnce.current = true;
    }
  }, [queryPanelHeight]);

  const onMouseMove = (e) => {
    if (previewPanelRef.current) {
      const componentTop = Math.round(previewPanelRef.current.getBoundingClientRect().top);
      const clientY = e.clientY;
      if ((clientY >= componentTop - 12) & (clientY <= componentTop + 1)) {
        setIsTopOfPreviewPanel(true);
      } else if (isTopOfPreviewPanel) {
        setIsTopOfPreviewPanel(false);
      }

      if (isDragging) {
        const parentHeight = queryPanelHeight;
        const shift = componentTop - clientY;
        const currentHeight = previewPanelRef.current.offsetHeight;
        const newHeight = currentHeight + shift;
        if (newHeight < 50) {
          setPreviewPanelExpanded(false);

          setHeight((queryPanelHeight - 85) * 0.7);
          return;
        }
        if (newHeight > parentHeight - 95) {
          return;
        }
        setHeight(newHeight);
      }
    }
  };

  const onMouseUp = () => {
    setDragging(false);
    calculatePreviewHeight(height, previewPanelExpanded);
  };

  const onMouseDown = () => {
    isTopOfPreviewPanel && setDragging(true);
  };

  useEventListener('mousemove', onMouseMove);
  useEventListener('mouseup', onMouseUp);
  const queryPreviewDataWithCircularDependenciesRemoved = useMemo(() => {
    const stringifiedValue = JSON.stringify(queryPreviewData, reservedKeywordReplacer);

    return stringifiedValue ? JSON.parse(stringifiedValue) : undefined;
  }, [queryPreviewData]);

  return (
    <div
      className={`
        preview-header preview-section d-flex flex-column  align-items-baseline font-weight-500 ${
          previewPanelExpanded ? 'expanded' : ''
        }`}
      ref={previewPanelRef}
      onMouseDown={onMouseDown}
      style={{
        cursor: previewPanelExpanded && (isDragging || isTopOfPreviewPanel) ? 'row-resize' : 'default',
        height: `${height}px`,
        ...(!previewPanelExpanded && { height: '29px' }),
        ...(isDragging && {
          transition: 'none',
        }),
      }}
    >
      <div className="preview-toggle">
        <div
          onClick={() => {
            setPreviewPanelExpanded(!previewPanelExpanded);
            calculatePreviewHeight(height, !previewPanelExpanded);
          }}
          className="left"
          data-cy="preview-toggle-button"
        >
          <ArrowDownTriangle
            width={15}
            style={{
              transform: !previewPanelExpanded ? 'rotate(180deg)' : '',
              transition: 'transform 0.2s ease-in-out',
              marginRight: '4px',
            }}
          />
          <span data-cy="preview-section-label">Preview</span>
        </div>
        {previewPanelExpanded && (
          <div className="right" data-cy="preview-tabs-container">
            <Tab.Container activeKey={key} onSelect={(k) => setKey(k)} defaultActiveKey="raw">
              <Row className="m-0">
                <Col className="keys text-center d-flex align-items-center">
                  <ListGroup
                    className={`query-preview-list-group rounded ${darkMode ? 'dark' : ''}`}
                    variant="flush"
                    style={{ backgroundColor: '#ECEEF0', padding: '2px' }}
                    data-cy="preview-tabs-list"
                  >
                    {tabs.map((tab) => (
                      <ListGroup.Item
                        key={tab}
                        eventKey={tab.toLowerCase()}
                        disabled={!queryPreviewData || (tab == 'JSON' && !isJson)}
                        style={{ minWidth: '74px', textAlign: 'center' }}
                        className="rounded"
                        data-cy={`preview-tab-${generateCypressDataCy(tab)}-item`}
                      >
                        <span
                          data-cy={`preview-tab-${generateCypressDataCy(tab)}`}
                          style={{ width: '100%' }}
                          className="rounded"
                        >
                          {tab}
                        </span>
                      </ListGroup.Item>
                    ))}
                  </ListGroup>
                </Col>
              </Row>
            </Tab.Container>
          </div>
        )}
      </div>
      <div className="preview-content" data-cy="preview-content">
        <Tab.Container activeKey={key} onSelect={(k) => setKey(k)} defaultActiveKey="raw">
          <div className="position-relative h-100">
            {previewLoading && (
              <center
                style={{ display: 'grid', placeItems: 'center' }}
                className="position-absolute w-100 h-100"
                data-cy="preview-loading-container"
              >
                <div className="spinner-border text-azure" role="status" data-cy="preview-loading-spinner"></div>
              </center>
            )}
            <Tab.Content
              style={{
                overflowWrap: 'anywhere',
                padding: 0,
                border: '1px solid var(--slate5)',
                height: '100%',
              }}
              data-cy="preview-tab-content"
            >
              <Tab.Pane eventKey="json" transition={false} data-cy="preview-json-pane">
                <div className="w-100 preview-data-container" data-cy="preview-json-data-container">
                  <JSONTree
                    theme={theme}
                    data={queryPreviewDataWithCircularDependenciesRemoved}
                    invertTheme={!darkMode}
                    collectionLimit={100}
                    hideRoot={true}
                  />
                </div>
              </Tab.Pane>
              <Tab.Pane eventKey="raw" transition={false} data-cy="preview-raw-pane">
                <div
                  style={{ padding: '1rem' }}
                  className={`raw-container preview-data-container`}
                  data-cy="preview-raw-data-container"
                >
                  {renderRawData()}
                </div>
              </Tab.Pane>
            </Tab.Content>
          </div>
        </Tab.Container>
      </div>
    </div>
  );
};

export default Preview;
import React, { useEffect, useState, useRef, useMemo } from 'react';
import { useTranslation } from 'react-i18next';
import cx from 'classnames';
import { isEmpty } from 'lodash';
// eslint-disable-next-line import/no-unresolved
import { diff } from 'deep-object-diff';
import { allSources, source } from '../QueryEditors';
import { resolveQueryEditor } from '../utils';
import DataSourcePicker from './DataSourcePicker';
import { Transformation } from './Transformation';
import Preview from './Preview';
import { ChangeDataSource } from './ChangeDataSource';
import { CustomToggleSwitch } from './CustomToggleSwitch';
import { customToggles, mockDataQueryAsComponent, RestAPIToggles } from '../constants';
import { DataSourceTypes } from '@/modules/common/components/DataSourceComponents';
import SuccessNotificationInputs from './SuccessNotificationInputs';
import ConfirmationInputs from './ConfirmationInputs';
import FxButton from '@/AppBuilder/CodeBuilder/Elements/FxButton';
import { useModuleContext } from '@/AppBuilder/_contexts/ModuleContext';
import ParameterList from './ParameterList';
import { deepClone } from '@/_helpers/utilities/utils.helpers';
import { DATA_SOURCE_TYPE } from '@/_helpers/constants';
import { canDeleteDataSource, canReadDataSource, canUpdateDataSource } from '@/_helpers';
import { getWorkspaceId } from '@/_helpers/utils';
import { getSubpath } from '@/_helpers/routes';
import { appendBranchName } from '@/_helpers/active-branch';
import { SquarePen } from 'lucide-react';
import useStore from '@/AppBuilder/_stores/store';
import { EventManager } from '@/AppBuilder/RightSideBar/Inspector/EventManager';
import NotificationBanner from '@/_components/NotificationBanner';
import { withEditionSpecificComponent } from '@/modules/common/helpers/withEditionSpecificComponent';
import CodeHinter from '@/AppBuilder/CodeEditor';

export const BaseQueryManagerBody = ({ darkMode, activeTab, renderCopilot = null }) => {
  const { t } = useTranslation();
  const { moduleId } = useModuleContext();
  const getResolvedValue = useStore((state) => state.getResolvedValue);
  const { isModuleEditor } = useModuleContext();
  const dataSources = useStore((state) => state.dataSources);
  const globalDataSources = useStore((state) => state.globalDataSources);
  const sampleDataSource = useStore((state) => state.sampleDataSource);
  const currentEnvironment = useStore((state) => state.selectedEnvironment);
  const paramListContainerRef = useRef(null);
  const selectedQuery = useStore((state) => state.queryPanel.selectedQuery);
  const selectedDataSource = useStore((state) => state.queryPanel.selectedDataSource);
  const changeDataQuery = useStore((state) => state.dataQuery.changeDataQuery);
  const updateDataQuery = useStore((state) => state.dataQuery.updateDataQuery);
  const [showLocalDataSourceDeprecationBanner, setshowLocalDataSourceDeprecationBanner] = useState(false);
  const options = useMemo(() => selectedQuery?.options, [selectedQuery]);
  const [dataSourceMeta, setDataSourceMeta] = useState(null);
  /* - Added the below line to cause re-rendering when the query is switched
       - QueryEditors are not updating when the query is switched
       - TODO: Remove the below line and make query editors update when the query is switched
       - Ref PR #6763
    */
  const [selectedQueryId, setSelectedQueryId] = useState(selectedQuery?.id);
  const queryName = selectedQuery?.name ?? '';

  const editor = resolveQueryEditor({ selectedDataSource, selectedQuery });
  const ElementToRender =
    editor.type === 'none' ? null : editor.type === 'plugin' ? source : allSources[editor.componentName];

  const defaultOptions = useRef({});

  const isFreezed = useStore((state) => state.getShouldFreeze(false, isModuleEditor));

  useEffect(() => {
    setDataSourceMeta(
      selectedQuery?.plugin_id
        ? selectedQuery?.manifest_file?.data?.source
        : DataSourceTypes.find((source) => source.kind === selectedQuery?.kind)
    );
    setSelectedQueryId(selectedQuery?.id);
    defaultOptions.current = selectedQuery?.options && JSON.parse(JSON.stringify(selectedQuery?.options));
    // eslint-disable-next-line react-hooks/exhaustive-deps
  }, [selectedQuery]);

  // Clear the focus field value from options
  const cleanFocusedFields = (newOptions) => {
    if (!defaultOptions.current) return newOptions;
    const diffFields = diff(newOptions, defaultOptions.current);
    const updatedOptions = { ...newOptions };
    Object.keys(diffFields).forEach((key) => {
      if (newOptions[key] === '' && defaultOptions.current[key] === undefined) {
        delete updatedOptions[key];
      }
    });
    return updatedOptions;
  };

  const validateNewOptions = (newOptions) => {
    // Guard against stale writes: when queries are switched rapidly, child components (e.g. DynamicSelector)
    // calls optionsChanged after the user has already moved to a different query.
    // Without this check, the old query's options would be written onto the newly selected query.
    const currentStoreQueryId = useStore.getState().queryPanel.selectedQuery?.id;
    if (currentStoreQueryId !== selectedQuery?.id) return;
    const updatedOptions = cleanFocusedFields(newOptions);
    updateDataQuery(deepClone({ ...options, ...updatedOptions }));
  };

  const optionchanged = (option, value) => {
    const newOptions = { ...options, [option]: value };
    validateNewOptions(newOptions);
  };

  const optionsChanged = (newOptions) => {
    validateNewOptions(newOptions);
  };

  const toggleOption = (option) => {
    const currentValue = selectedQuery?.options?.[option] ?? false;
    optionchanged(option, !currentValue);
  };
  const optionsChangedforParams = (newOptions) => {
    updateDataQuery(deepClone(newOptions));
  };

  const handleAddParameter = (newParameter) => {
    const prevOptions = { ...options };
    //check if paramname already used
    if (!prevOptions?.parameters?.some((param) => param.name === newParameter.name)) {
      const newOptions = {
        ...prevOptions,
        parameters: [...(prevOptions?.parameters ?? []), newParameter],
      };
      optionsChangedforParams(newOptions);
    }
  };

  const handleParameterChange = (index, updatedParameter) => {
    const prevOptions = { ...options };
    //check if paramname already used
    if (!prevOptions?.parameters?.some((param, idx) => param.name === updatedParameter.name && index !== idx)) {
      const updatedParameters = [...prevOptions.parameters];
      updatedParameters[index] = updatedParameter;
      optionsChangedforParams({ ...prevOptions, parameters: updatedParameters });
    }
  };

  const handleParameterRemove = (index) => {
    const prevOptions = { ...options };
    const updatedParameters = prevOptions.parameters.filter((param, i) => index !== i);
    optionsChangedforParams({ ...prevOptions, parameters: updatedParameters });
  };
  const [previewHeight, setPreviewHeight] = useState(40);

  const calculatePreviewHeight = (height, previewPanelExpanded) => {
    setPreviewHeight(previewPanelExpanded ? height : 40);
  };
  const renderDataSourcesList = () => {
    return (
      <div
        className={cx(`datasource-picker p-0`, {
          'disabled ': isFreezed,
        })}
      >
        <DataSourcePicker darkMode={darkMode} />
        <div className="pb-5" />
      </div>
    );
  };

  const renderTransformation = () => {
    if (
      dataSourceMeta?.disableTransformations ||
      selectedDataSource?.kind === 'runjs' ||
      selectedDataSource?.kind === 'runpy'
    )
      return;
    return (
      <div className={cx({ 'disabled ': isFreezed })}>
        <Transformation
          renderCopilot={(props) => renderCopilot?.({ ...props, selectedDataSource })}
          changeOption={optionchanged}
          options={options ?? {}}
          darkMode={darkMode}
          queryId={selectedQuery?.id}
        />
      </div>
    );
  };

  const handleBlur = () => {
    updateDataQuery(options);
  };

  let docLinkStatic = '';
  switch (selectedDataSource?.kind) {
    case 'restapi':
      docLinkStatic = `https://docs.tooljet.com/docs/data-sources/restapi/querying-rest-api`;
      break;
    case 'tooljetdb':
      docLinkStatic = `https://docs.tooljet.com/docs/tooljet-db/querying-tooljet-db`;
      break;
    case 'runjs':
      docLinkStatic = `https://docs.tooljet.com/docs/data-sources/run-js`;
      break;
    case 'runpy':
      docLinkStatic = `https://docs.tooljet.com/docs/data-sources/run-py`;
      break;
  }

  const renderQueryElement = () => {
    return (
      <div
        className={cx({
          'disabled ': isFreezed,
        })}
      >
        <div ref={paramListContainerRef} style={{ marginBottom: '16px' }}>
          {selectedQuery &&
            (selectedDataSource?.kind === 'runjs' ||
              selectedDataSource?.kind === 'runpy' ||
              selectedDataSource?.kind === 'tooljetdb' ||
              (selectedDataSource?.kind === 'restapi' && selectedDataSource?.type !== 'default')) && (
              <>
                <div style={{ marginBottom: '2px' }}>
                  {`To know more about querying ${selectedDataSource?.kind} data,`}
                  &nbsp;
                  <a
                    href={docLinkStatic}
                    target="_blank"
                    style={{
                      marginLeft: '0px !important',
                      color: 'hsl(226, 70.0%, 55.5%)',
                      textDecoration: 'underline',
                    }}
                    rel="noreferrer"
                  >
                    {t('globals.readDocumentation', 'read documentation').toLowerCase()}
                  </a>
                </div>
                <ParameterList
                  parameters={options.parameters}
                  handleAddParameter={handleAddParameter}
                  handleParameterChange={handleParameterChange}
                  handleParameterRemove={handleParameterRemove}
                  darkMode={darkMode}
                  containerRef={paramListContainerRef}
                />
              </>
            )}
        </div>
        {ElementToRender && (
          <ElementToRender
            renderCopilot={(props) => renderCopilot?.({ ...props, selectedDataSource })}
            key={selectedQuery?.id}
            pluginSchema={selectedDataSource?.plugin?.operations_file?.data}
            selectedDataSource={selectedDataSource}
            options={selectedQuery?.options}
            optionsChanged={optionsChanged}
            optionchanged={optionchanged}
            darkMode={darkMode}
            isEditMode={true} // Made TRUE always to avoid setting default options again
            queryName={queryName}
            currentEnvironment={currentEnvironment}
            currentAppEnvironmentId={currentEnvironment?.id}
            onBlur={handleBlur} // Applies only to textarea, text box, etc. where `optionchanged` is triggered for every character change.
          />
        )}
      </div>
    );
  };

  const renderEventManager = () => {
    const queryComponent = mockDataQueryAsComponent(options?.events || []);
    return (
      <div
        className={cx('d-flex', {
          'disabled ': isFreezed,
        })}
        data-cy="query-events-section"
      >
        <div className={`form-label`} data-cy="query-manager-events-label">
          {t('editor.queryManager.eventsHandler', 'Events')}
        </div>
        <div className="query-manager-events pb-4">
          <EventManager
            sourceId={selectedQuery?.id}
            eventSourceType="data_query" //check
            eventMetaDefinition={queryComponent.componentMeta}
            callerQueryId={selectedQueryId}
            popoverPlacement="auto"
            callerQueryName={selectedQuery?.name}
          />
        </div>
      </div>
    );
  };

  const renderTimeout = () => {
    return (
      <div
        className={cx('d-flex', { 'disabled ': isFreezed })}
        data-param="query_timeout"
        data-cy="query-timeout-section"
        style={{ marginBottom: '16px' }}
      >
        <div className="form-label mt-2" data-cy="query-manager-timeout-label">
          {t('editor.queryManager.timeout', 'Timeout ( ms )')}
        </div>
        <div className="query-manager-query-timeout">
          <CodeHinter
            theme={darkMode ? 'monokai' : 'base16-light'}
            initialValue={selectedQuery?.options?.query_timeout ?? ''}
            onChange={(value) => optionchanged('query_timeout', value)}
            cyLabel="query-timeout-input"
          />
        </div>
      </div>
    );
  };

  const renderDisableQuery = () => {
    return (
      <div
        className={cx('d-flex tw-mb-4', { 'disabled ': isFreezed })}
        data-param="disableQuery"
        data-cy="query-disable-section"
      >
        <div className="form-label mt-2" data-cy="query-manager-disable-label">
          {t('editor.queryManager.disableQuery', 'Disable query')}
        </div>
        <div className="flex-grow-1 tw-max-w-[460px]">
          <CodeHinter
            type="basic"
            initialValue={selectedQuery?.options?.disableQuery ?? ''}
            onChange={(value) => optionchanged('disableQuery', value)}
            placeholder="{{components.toggleswitch1.value}}"
            cyLabel="query-disable-expression"
          />
        </div>
      </div>
    );
  };

  const renderDisabledMessage = () => {
    const hasDisableExpression = !!selectedQuery?.options?.disableQuery?.trim();
    return (
      <div
        className={cx('d-flex tw-mb-4', { 'disabled ': isFreezed })}
        data-param="disabledMessage"
        data-cy="query-disabled-message-section"
      >
        <div className="form-label mt-2" data-cy="query-manager-disabled-message-label">
          {t('editor.queryManager.disabledMessageLabel', 'Disable message')}
        </div>
        <div
          className={cx(
            'flex-grow-1 tw-max-w-[460px]',
            hasDisableExpression ? 'tw-opacity-100' : 'tw-opacity-30 tw-pointer-events-none'
          )}
        >
          <CodeHinter
            type="basic"
            initialValue={selectedQuery?.options?.disabledMessage ?? ''}
            onChange={(value) => optionchanged('disabledMessage', value)}
            placeholder={t('editor.queryManager.queryDisabledDefault', 'This query is disabled')}
            cyLabel="query-disabled-message"
            disabled={!hasDisableExpression}
          />
        </div>
      </div>
    );
  };

  const renderQueryOptions = () => {
    return (
      <div className={cx({ 'disabled ': isFreezed })}>
        <div
          className={cx(`d-flex pb-1`, {
            'disabled ': isFreezed,
          })}
          data-cy="query-triggers-section"
        >
          <div className="form-label mt-2" data-cy="query-manager-triggers-label">
            {t('editor.queryManager.settings', 'Triggers')}
          </div>
          <div className="flex-grow-1">
            {Object.keys(customToggles).map((toggle, index) => {
              const config = customToggles[toggle];
              const fxMode = config.fx ? !!selectedQuery?.options?.[config.fxKey] : false;
              const handleFxToggle = config.fx
                ? () => {
                    if (fxMode) {
                      const currentExpression = selectedQuery?.options?.[config.action];
                      let evaluated = false;
                      try {
                        evaluated = !!getResolvedValue(currentExpression, {}, moduleId);
                      } catch (e) {
                        evaluated = false;
                      }
                      optionsChanged({
                        ...options,
                        [config.action]: evaluated,
                        [config.fxKey]: false,
                      });
                    } else {
                      const currentBool = !!selectedQuery?.options?.[config.action];
                      optionsChanged({
                        ...options,
                        [config.action]: currentBool ? '{{true}}' : '{{false}}',
                        [config.fxKey]: true,
                      });
                    }
                  }
                : undefined;
              const toggleValue = fxMode ? false : !!selectedQuery?.options?.[config?.action];
              return (
                <React.Fragment key={toggle}>
                  <CustomToggleFlag
                    {...config}
                    toggleOption={toggleOption}
                    value={toggleValue}
                    index={index}
                    darkMode={darkMode}
                    queryKind={selectedQuery?.kind}
                    fxMode={fxMode}
                    onFxToggle={handleFxToggle}
                  />
                  {config.action === 'requestConfirmation' && (
                    <ConfirmationInputs
                      options={options}
                      darkMode={darkMode}
                      optionchanged={optionchanged}
                      queryName={queryName}
                    />
                  )}
                </React.Fragment>
              );
            })}
            {selectedQuery?.kind === 'restapi' &&
              Object.keys(RestAPIToggles).map((toggle, index) => (
                <CustomToggleFlag
                  {...RestAPIToggles[toggle]}
                  toggleOption={toggleOption}
                  value={selectedQuery?.options?.[RestAPIToggles[toggle]?.action]}
                  index={index}
                  key={toggle}
                  darkMode={darkMode}
                />
              ))}
          </div>
        </div>
        <div className="d-flex">
          <div className="form-label">{}</div>
          <SuccessNotificationInputs
            // currentState={currentState}
            options={options}
            darkMode={darkMode}
            optionchanged={optionchanged}
          />
        </div>
        {renderTimeout()}
        {renderDisableQuery()}
        {renderDisabledMessage()}
        {renderEventManager()}
      </div>
    );
  };

  const handleEditDatasource = () => {
    const url = appendBranchName(`${getSubpath() ?? ''}/${getWorkspaceId()}/data-sources/${selectedDataSource.id}`);
    window.open(url, '_blank', 'noopener,noreferrer');
  };

  const renderChangeDataSource = () => {
    const selectableDataSources = [...dataSources, ...globalDataSources, !!sampleDataSource && sampleDataSource]
      .filter(Boolean)
      .filter((ds) => ds.kind === selectedQuery?.kind && ds.type !== DATA_SOURCE_TYPE.STATIC)
      // Hide dummy DSes from the picker — they aren't valid switch targets.
      // Keep the currently bound dummy in the list so the dropdown can render its label.
      .filter((ds) => !ds.is_dummy || ds.id === selectedDataSource?.id);
    const showEditDatasourceButton =
      selectedDataSource?.scope === 'global' &&
      selectedDataSource?.type !== DATA_SOURCE_TYPE.SAMPLE &&
      canUpdateDataSource(selectedQuery?.data_source_id);
    if (isEmpty(selectableDataSources)) {
      return '';
    }
    const isSampleDb = selectedDataSource?.type === DATA_SOURCE_TYPE.SAMPLE;
    const docLink = isSampleDb
      ? 'https://docs.tooljet.com/docs/data-sources/sample-data-sources'
      : selectedDataSource?.plugin_id && selectedDataSource.plugin_id.trim() !== ''
        ? `https://docs.tooljet.com/docs/marketplace/plugins/marketplace-plugin-${selectedDataSource?.kind}/`
        : `https://docs.tooljet.com/docs/data-sources/${selectedDataSource?.kind}`;
    return (
      <>
        <div className={cx({ 'disabled ': isFreezed })} ref={paramListContainerRef}>
          {selectedQuery && !showLocalDataSourceDeprecationBanner && (
            <ParameterList
              parameters={options.parameters}
              handleAddParameter={handleAddParameter}
              handleParameterChange={handleParameterChange}
              handleParameterRemove={handleParameterRemove}
              darkMode={darkMode}
              containerRef={paramListContainerRef}
            />
          )}
        </div>
        <div className="d-flex" style={{ marginBottom: '16px', marginTop: '12px' }}>
          <div
            className={cx(
              'd-flex query-manager-border-color hr-text-left py-2 form-label font-weight-500 change-data-source',
              { 'disabled ': isFreezed }
            )}
            data-cy="query-manager-source-label"
          >
            Source
          </div>
          <div
            className="d-flex flex-column align-items-start"
            style={{ width: '500px' }}
            data-cy="query-manager-change-data-source"
          >
            <div className="d-flex align-items-center" style={{ gap: '8px', width: '100%' }}>
              <div className={cx('flex-grow-1', { 'disabled ': isFreezed })}>
                <ChangeDataSource
                  dataSources={selectableDataSources}
                  value={selectedDataSource}
                  onChange={(newDataSource) => {
                    changeDataQuery(newDataSource);
                  }}
                />
              </div>
              {showEditDatasourceButton && (
                <button
                  type="button"
                  onClick={handleEditDatasource}
                  data-cy="edit-datasource-button"
                  className="d-flex align-items-center justify-content-center flex-shrink-0 edit-datasource-btn"
                >
                  <SquarePen width={14} height={14} color="var(--icon-default)" />
                  Edit datasource
                </button>
              )}
            </div>
            {selectedDataSource?.is_dummy && (
              <div
                className="tw-text-text-danger tw-mt-1 tw-font-body-small tw-pointer-events-auto tw-select-text tw-cursor-text"
                data-cy="query-manager-source-missing-warning"
              >
                {t(
                  'editor.queryManager.datasourceMissingPullFromGit',
                  'Data source #{{id}} is missing, pull from git to resolve this',
                  { id: selectedDataSource?.co_relation_id }
                )}
              </div>
            )}
            <div
              className={cx({ 'disabled ': isFreezed })}
              style={{ marginBottom: '2px' }}
              data-cy="query-manager-source-doc-link"
            >
              {`To know more about querying ${selectedDataSource?.kind} data,`}
              &nbsp;
              <a
                href={docLink}
                target="_blank"
                style={{ marginLeft: '0px !important', color: 'hsl(226, 70.0%, 55.5%)', textDecoration: 'underline' }}
                rel="noreferrer"
              >
                {t('globals.readDocumentation', 'read documentation').toLowerCase()}
              </a>
            </div>
          </div>
        </div>
      </>
    );
  };
  useEffect(() => {
    const staticDataSources = ['runjs', 'runpy', 'tooljetdb'];
    // added specific check for rest api - as it is a part of both : default and global data sources
    const showDeprecationBanner =
      selectedDataSource == null &&
      selectedQuery &&
      !staticDataSources.includes(selectedDataSource?.kind) &&
      (selectedDataSource?.kind !== 'restapi' || selectedDataSource?.type !== 'default');

    if (showDeprecationBanner) {
      setshowLocalDataSourceDeprecationBanner(true);
    } else {
      setshowLocalDataSourceDeprecationBanner(false);
    }
  }, [selectedDataSource, selectedQuery]);
  // if (selectedQueryId !== selectedQuery?.id) return;
  const hasPermissions =
    selectedDataSource?.scope === 'global' && selectedDataSource?.type !== DATA_SOURCE_TYPE.SAMPLE
      ? canUpdateDataSource(selectedQuery?.data_source_id) ||
        canReadDataSource(selectedQuery?.data_source_id) ||
        canDeleteDataSource()
      : true;

  return (
    <div
      className={`query-details ${selectedDataSource?.kind === 'tooljetdb' ? 'tooljetdb-query-details' : ''} ${
        !hasPermissions ? 'disabled' : ''
      }`}
      style={{
        height: `calc(100% - ${selectedQuery ? previewHeight + 40 : 0}px)`,
        overflowY: 'auto',
        scrollbarWidth: 'none',
      }} // 40px for preview header height
    >
      {selectedDataSource === null || !selectedQuery ? (
        showLocalDataSourceDeprecationBanner ? (
          <>
            <NotificationBanner enhanceDisabledVisibility={!hasPermissions || isFreezed} darkMode={darkMode} />
            {renderChangeDataSource()}
          </>
        ) : (
          renderDataSourcesList()
        )
      ) : (
        <>
          {selectedQuery?.data_source_id &&
            selectedDataSource?.type !== DATA_SOURCE_TYPE.STATIC &&
            activeTab === 1 &&
            renderChangeDataSource()}
          {activeTab === 1 && renderQueryElement()}
          {activeTab === 2 && renderTransformation()}
          {activeTab === 3 && renderQueryOptions()}
          <Preview darkMode={darkMode} calculatePreviewHeight={calculatePreviewHeight} />
        </>
      )}
    </div>
  );
};

const UNSUPPORTED_DEPENDENCY_CHANGE_KINDS = new Set(['runjs', 'runpy']);

const CustomToggleFlag = ({
  dataCy,
  action,
  translatedLabel,
  label,
  subLabel,
  value,
  toggleOption,
  darkMode,
  queryKind,
  fx,
  fxMode,
  onFxToggle,
}) => {
  const [flag, setFlag] = useState(false);
  const { t } = useTranslation();

  const isHidden = action === 'runOnDependencyChange' && UNSUPPORTED_DEPENDENCY_CHANGE_KINDS.has(queryKind);

  useEffect(() => {
    setFlag(value);
  }, [value]);

  if (isHidden) return null;

  return (
    <div data-param={action} className="query-manager-settings-toggles">
      <div className={cx({ 'toggle-fx-row': fx && onFxToggle, 'fx-active': fxMode })}>
        <CustomToggleSwitch
          dataCy={dataCy}
          isChecked={flag}
          toggleSwitchFunction={(flag) => {
            if (fxMode) return;
            setFlag((state) => !state);
            toggleOption(flag);
          }}
          action={action}
          darkMode={darkMode}
          label={t(translatedLabel, label)}
          subLabel={subLabel}
          disabled={fxMode}
        />
        {fx && onFxToggle && <FxButton active={!!fxMode} onPress={onFxToggle} dataCy={dataCy} />}
      </div>
    </div>
  );
};

