import Tick from '@/_ui/Icon/solidIcons/Tick';
import useShowPopover from '@/_hooks/useShowPopover';
import DataSourceIcon from '../QueryManager/Components/DataSourceIcon';
import { staticDataSources } from '../QueryManager/constants';
import { ToolTip } from '@/_components';
import { PillButton } from '../QueryManager/Components/ParameterDetails';
import useStore from '@/AppBuilder/_stores/store';

const FilterandSortPopup = ({ darkMode, selectedDataSources, onFilterDatasourcesChange, clearSelectedDataSources }) => {
  const [showMenu, setShowMenu] = useShowPopover(false, '#query-sort-filter-popover', '#query-sort-filter-popover-btn');
  const closeMenu = () => setShowMenu(false);
  const [action, setAction] = useState();
  const [search, setSearch] = useState('');
  const sortDataQueries = useStore((state) => state.dataQuery.sortDataQueries);
  const dataSources = useStore((state) => state.dataSources);
  const sortBy = useStore((state) => state.dataQuery.sortBy);
  const sortOrder = useStore((state) => state.dataQuery.sortOrder);
  const dataQueries = useStore((state) => state.dataQuery.queries.modules.canvas);
  const globalDataSources = useStore((state) => state.globalDataSources);
  const sampleDataSources = useStore((state) => state.sampleDataSources);
  const [sources, setSources] = useState();
  const searchBoxRef = useRef(null);

  useState(() => {
    if (action === 'filter-by-datasource' && searchBoxRef.current) {
      searchBoxRef.current.focus();
    }
  }, [action]);

  useEffect(() => {
    if (showMenu) {
      const seen = new Set();
      const createdSources = dataQueries.map((query) => {
        const globalDS = [...dataSources, ...globalDataSources, ...(sampleDataSources ? [sampleDataSources] : [])].find(
          (source) => source.id === query.data_source_id
        );
        if (globalDS) {
          return globalDS;
        }
        return {
          ...staticDataSources.find((source) => source.kind === query.kind),
          id: null,
        };
      });
      setSearch('');
      setSources(
        createdSources
          .filter((source) => {
            if (!source.kind && !source.id) return false;
            const key = source.kind + '-' + source.id;
            if (seen.has(key)) {
              return false;
            }
            seen.add(key);
            return true;
          })
          .sort((a, b) => {
            const aChecked = selectedDataSources.some((item) => item.id === a.id && item.kind === a.kind);
            const bChecked = selectedDataSources.some((item) => item.id === b.id && item.kind === b.kind);
            if (aChecked && !bChecked) {
              return -1;
            }
            if (!aChecked && bChecked) {
              return 1;
            }
            return 0;
          })
      );
    } else {
      setAction();
    }
  }, [dataQueries, dataSources, globalDataSources, showMenu, sampleDataSources]);

  const handlePageCallback = (action) => {
    setAction(action);
  };

  const handleSort = (sortBy, sortOrder) => {
    sortDataQueries(sortBy, sortOrder);
    closeMenu();
  };

  const renderPopupComponent = (action) => {
    switch (action) {
      case 'filter-by-datasource':
        return (
          <DataSourceSelector
            search={search}
            setSearch={setSearch}
            sources={sources}
            onFilterDatasourcesChange={onFilterDatasourcesChange}
            onBackBtnClick={() => setAction()}
            selectedDataSources={selectedDataSources}
          />
        );

      default:
        return (
          <div className="card-body p-0 tj-scrollbar query-editor-sort-filter-popup query-editor-sort-filter-body">
            <div className="color-slate9 px-3 pb-2 w-100">
              <small data-cy="label-filter-by">Filter By</small>
            </div>
            <div className={`tj-list-btn mx-1 ${selectedDataSources.length ? 'd-flex' : ''}`}>
              <MenuButton
                id="filter-by-datasource"
                text="Data Source"
                callback={handlePageCallback}
                disabled={dataQueries.length === 0}
                noMargin
              />
              {selectedDataSources.length ? (
                <PillButton
                  name={selectedDataSources.length}
                  onRemove={clearSelectedDataSources}
                  onClick={() => handlePageCallback('filter-by-datasource')}
                  className="m-1 bg-slate6"
                  size="sm"
                />
              ) : (
                ''
              )}
            </div>
            <div className="border-bottom mt-1"></div>
            <div className="color-slate9 px-3 pb-2 pt-1 w-100">
              <small data-cy="label-sort-by">Sort By</small>
            </div>
            <MenuButton id="custom" text="Custom order" callback={handleSort} active={sortBy === 'custom'} />
            <MenuButton
              id="name"
              order="asc"
              text="Name: A-Z"
              callback={handleSort}
              active={sortBy === 'name' && sortOrder === 'asc'}
            />
            <MenuButton
              id="name"
              order="desc"
              text="Name: Z-A"
              callback={handleSort}
              active={sortBy === 'name' && sortOrder === 'desc'}
            />
            <MenuButton
              id="kind"
              order="asc"
              text="Type: A-Z"
              callback={handleSort}
              active={sortBy === 'kind' && sortOrder === 'asc'}
            />
            <MenuButton
              id="kind"
              order="desc"
              text="Type: Z-A"
              callback={handleSort}
              active={sortBy === 'kind' && sortOrder === 'desc'}
            />
            <MenuButton
              id="updated_at"
              order="asc"
              text="Last modified: oldest first"
              callback={handleSort}
              active={sortBy === 'updated_at' && sortOrder === 'asc'}
            />
            <MenuButton
              id="updated_at"
              order="desc"
              text="Last modified: newest first"
              callback={handleSort}
              active={sortBy === 'updated_at' && sortOrder === 'desc'}
            />
          </div>
        );
    }
  };

  return (
    <OverlayTrigger
      placement="right-end"
      // rootClose={true}
      show={showMenu}
      overlay={
        <Popover
          key={'page.i'}
          id="query-sort-filter-popover"
          className={`query-manager-sort-filter-popup ${darkMode && 'popover-dark-themed dark-theme tj-dark-mode'}`}
        >
          <Popover.Body key={'1'} bsPrefix="popover-body" className="pt-1 p-0">
            {renderPopupComponent(action)}
          </Popover.Body>
        </Popover>
      }
    >
      <span>
        <ToolTip message="Show sort/filter" placement="bottom">
          <button
            id="query-sort-filter-popover-btn"
            onClick={(e) => {
              e.stopPropagation();
              setShowMenu((showMenu) => !showMenu);
            }}
            className={cx('position-relative  btn-query-panel-header', {
              active: showMenu,
            })}
            data-cy={`query-filter-button`}
          >
            <ListFilter color="var(--icons-strong)" size={14} />
            {selectedDataSources.length > 0 && <div className="notification-dot"></div>}
          </button>
        </ToolTip>
      </span>
    </OverlayTrigger>
  );
};

const DataSourceSelector = ({
  sources: _sources,
  search,
  setSearch,
  onFilterDatasourcesChange,
  onBackBtnClick,
  selectedDataSources,
}) => {
  const searchBoxRef = useRef(null);
  const [sources, setSources] = useState([]);

  useEffect(() => {
    searchBoxRef.current.focus();
  }, []);

  useEffect(() => {
    setSources(
      _sources.filter((source) => {
        if (!search || !source?.name) {
          return true;
        }
        return source?.name?.toLowerCase().includes(search?.toLowerCase());
      })
    );
  }, [_sources, search]);

  return (
    <div className="card-body p-0 mt-1">
      <div className="border-bottom d-flex px-2">
        <div className="d-flex align-items-center mb-1">
          <button className="border-0 bg-transparent rounded-0 p-0" onClick={onBackBtnClick}>
            <Arrowleft fill="#3E63DD" tailOpacity={1} />
          </button>
        </div>
        <div>
          <input
            className="bg-transparent border-0 form-control form-control-sm"
            placeholder="Select data source"
            onChange={(e) => setSearch(e.target.value)}
            ref={searchBoxRef}
            value={search}
            data-cy="input-query-ds-filter"
          />
        </div>
      </div>
      <div className="tj-scrollbar py-2 query-ds-filter-list">
        {sources.map((source) => (
          <label
            className={cx('px-2 py-2 tj-list-btn d-block mx-1')}
            key={source.id || source.kind}
            role="button"
            for={`default-${source.id || source.kind}`}
          >
            <Form.Check // prettier-ignore
              type={'checkbox'}
              id={`default-${source.id || source.kind}`}
              onChange={(e) => onFilterDatasourcesChange(source, e.target.value)}
              className="m-0"
              checked={selectedDataSources.some((item) => item.id === source.id && item.kind === source.kind)}
              label={
                <div className="d-flex align-items-center">
                  <DataSourceIcon source={source} height={12} styles={{ minWidth: 12 }} />
                  &nbsp;
                  <span className="ms-1 text-truncate" data-cy={`ds-filter-${source?.name?.toLowerCase()}`}>
                    {source.name}
                  </span>
                </div>
              }
            />
          </label>
        ))}
      </div>
    </div>
  );
};

const MenuButton = ({
  id,
  order,
  text,
  iconSrc,
  disabled = false,
  callback = () => null,
  active,
  noMargin = false,
}) => {
  const handleOnClick = (e) => {
    e.stopPropagation();
    callback(id, order);
  };

  return (
    <div className={`field p-2 ${noMargin ? '' : 'mx-1'} tj-list-btn`}>
      <Button.UnstyledButton onClick={handleOnClick} disabled={disabled} classNames="d-flex justify-content-between">
        <Button.Content title={text} iconSrc={iconSrc} direction="left" />
        {active && <Tick width="20" height="20" viewBox="0 0 22 22" fill="var(--indigo9)" />}
      </Button.UnstyledButton>
    </div>
  );
};

export default FilterandSortPopup;
import React, { useRef } from 'react';
import { Tooltip } from 'react-tooltip';
import { ToolTip } from '@/_components/ToolTip';
import { toast } from 'react-hot-toast';
import { shallow } from 'zustand/shallow';
import DataSourceIcon from '../QueryManager/Components/DataSourceIcon';
import { isQueryRunnable, decodeEntities } from '@/_helpers/utils';
import { canDeleteDataSource, canReadDataSource, canUpdateDataSource } from '@/_helpers';
import useStore from '@/AppBuilder/_stores/store';
import { useModuleContext } from '@/AppBuilder/_contexts/ModuleContext';
import { Button as ButtonComponent } from '@/components/ui/Button/Button.jsx';
import SolidIcon from '@/_ui/Icon/SolidIcons';
import { QueryRenameInput } from './QueryRenameInput';
import { EllipsisVerticalIcon } from 'lucide-react';

export const QueryCard = ({ dataQuery, darkMode = false, localDs }) => {
  const { isModuleEditor } = useModuleContext();
  const queryNameEleRef = useRef(null);

  const isQuerySelected = useStore((state) => state.queryPanel.isQuerySelected(dataQuery.id), shallow);
  const setSelectedQuery = useStore((state) => state.queryPanel.setSelectedQuery);
  const checkExistingQueryName = useStore((state) => state.dataQuery.checkExistingQueryName);
  const selectedDataSourceScope = useStore((state) => state.queryPanel.selectedDataSource?.scope);
  const hasQueryFolders = useStore((state) => Boolean(state.queryFolders));
  const renameQuery = useStore((state) => state.dataQuery.renameQuery);
  const setPreviewData = useStore((state) => state.queryPanel.setPreviewData);
  const shouldFreeze = useStore((state) => state.getShouldFreeze(false, isModuleEditor));

  const renamingQueryId = useStore((state) => state.queryPanel.renamingQueryId);
  const setRenamingQuery = useStore((state) => state.queryPanel.setRenamingQuery);
  const isRenaming = renamingQueryId === dataQuery.id;

  const hasPermissions =
    selectedDataSourceScope === 'global'
      ? canUpdateDataSource(dataQuery?.data_source_id) ||
        canReadDataSource(dataQuery?.data_source_id) ||
        canDeleteDataSource()
      : true;

  const updateQuerySuggestions = useStore((state) => state.queryPanel.updateQuerySuggestions);

  const toggleQueryHandlerMenu = useStore((state) => state.queryPanel.toggleQueryHandlerMenu);
  const featureAccess = useStore((state) => state?.license?.featureAccess, shallow);
  const licenseValid = !featureAccess?.licenseStatus?.isExpired && featureAccess?.licenseStatus?.isLicenseValid;
  const isRestricted = dataQuery.permissions && dataQuery.permissions.length !== 0;

  const updateQueryName = (dataQuery, newName) => {
    const { name } = dataQuery;
    if (name === newName) {
      return setRenamingQuery(null);
    }
    const isNewQueryNameAlreadyExists = checkExistingQueryName(newName);
    if (newName && !isNewQueryNameAlreadyExists) {
      renameQuery(dataQuery?.id, newName);
      setRenamingQuery(null);
      updateQuerySuggestions(name, newName);
    } else {
      if (isNewQueryNameAlreadyExists) {
        toast.error('Query name already exists');
      }
      setRenamingQuery(null);
    }
  };

  const getTooltip = () => {
    const permission = dataQuery.permissions?.[0];
    if (!permission) return 'Access restricted';

    const users = permission.groups || permission.users || [];
    if (users.length === 0) return 'Access restricted';

    const isSingle = permission.type === 'SINGLE';
    const isGroup = permission.type === 'GROUP';

    if (isSingle) {
      return users.length === 1
        ? `Access restricted to ${users[0].user.email}`
        : `Access restricted to ${users.length} users`;
    }

    if (isGroup) {
      return users.length === 1
        ? `Access restricted to ${users[0].permission_group?.name || users[0].permissionGroup?.name} group`
        : `Access restricted to ${users.length} user groups`;
    }

    return 'Access restricted';
  };

  return (
    <>
      <div
        className={
          `query-row pe-2 ${hasQueryFolders ? 'mb-0' : 'mb-1'} ${darkMode && 'dark-theme'}` +
          (isQuerySelected ? ' query-row-selected' : '')
        }
        key={dataQuery.id}
        onClick={(e) => {
          if (isQuerySelected) return;
          if (!shouldFreeze) {
            const menuBtn = document.getElementById(`query-handler-menu-${dataQuery?.id}`);
            if (menuBtn && menuBtn.contains(e.target)) {
              e.stopPropagation();
            } else {
              toggleQueryHandlerMenu(false);
            }
          }
          setTimeout(() => {
            setSelectedQuery(dataQuery?.id);
            setPreviewData(null);
          }, 0);
        }}
        role="button"
      >
        <div className="query-card-leading">
          <div className="query-icon d-flex">
            <DataSourceIcon source={dataQuery} height={16} />
          </div>
          <div className="query-row-query-name">
            {isRenaming ? (
              <QueryRenameInput dataQuery={dataQuery} darkMode={darkMode} onUpdate={updateQueryName} />
            ) : (
              <div className="query-name" data-cy={`list-query-${dataQuery.name.toLowerCase()}`}>
                <ToolTip
                  message={decodeEntities(dataQuery.name)}
                  show={queryNameEleRef.current?.offsetWidth > 150}
                  tooltipClassName="[&_.tooltip-inner]:tw-max-w-3xl"
                >
                  <span
                    ref={queryNameEleRef}
                    className="text-truncate"
                    onDoubleClick={(e) => {
                      e.stopPropagation();
                      if (!shouldFreeze) setRenamingQuery(dataQuery.id);
                    }}
                  >
                    {decodeEntities(dataQuery.name)}
                  </span>
                </ToolTip>
                <ToolTip message={getTooltip()} show={licenseValid && isRestricted}>
                  <div className="d-flex align-items-center query-card-lock-wrapper">
                    {licenseValid && isRestricted && <SolidIcon width="16" name="lock" fill="var(--icon-strong)" />}
                  </div>
                </ToolTip>{' '}
                {!isQueryRunnable(dataQuery) && <small className="mx-2 text-secondary">Draft</small>}
                {localDs && (
                  <>
                    <a
                      className="text-truncate"
                      data-tooltip-id="query-card-local-ds-info"
                      href="https://docs.tooljet.com/docs/setup/upgrade-to-v3#local-data-sources"
                      target="_blank"
                      rel="noreferrer"
                    >
                      <img src={`assets/images/icons/warning.svg`} className="query-card-local-ds-icon" alt="Warning" />
                    </a>{' '}
                    <Tooltip id="query-card-local-ds-info" className="tooltip" place="right" style={{ width: '200px' }}>
                      Important <br />
                      Local Data sources will be deprecated soon. Switch to Global Data sources for continued support
                    </Tooltip>
                  </>
                )}
              </div>
            )}
          </div>
        </div>
        {!shouldFreeze && hasPermissions && (
          <div
            className={`col-auto query-rename-delete-btn ${isQuerySelected ? 'd-flex' : 'd-none'}`}
            onClick={(e) => e.stopPropagation()}
          >
            <ButtonComponent
              iconOnly
              onClick={(e) => {
                if (!isQuerySelected) {
                  setSelectedQuery(dataQuery?.id);
                  setPreviewData(null);
                }
                toggleQueryHandlerMenu(true, `query-handler-menu-${dataQuery?.id}`);
              }}
              size="small"
              variant="outline"
              className=""
              id={`query-handler-menu-${dataQuery?.id}`}
              data-cy={`query-handler-menu-${dataQuery.name.toLowerCase()}`}
            >
              <EllipsisVerticalIcon color="var(--icon-strong)" size={12} />
            </ButtonComponent>
          </div>
        )}
      </div>
    </>
  );
};
import React, { useCallback } from 'react';
import { Overlay, Popover } from 'react-bootstrap';
import useStore from '@/AppBuilder/_stores/store';
import classNames from 'classnames';
import Edit from '@/_ui/Icon/bulkIcons/Edit';
import Trash from '@/_ui/Icon/solidIcons/Trash';
import Copy from '@/_ui/Icon/solidIcons/Copy';
import SolidIcon from '@/_ui/Icon/SolidIcons';
import { ToolTip } from '@/_components/ToolTip';
import { debounce } from 'lodash';
import { Waypoints } from 'lucide-react';
import usePopoverObserver from '@/AppBuilder/_hooks/usePopoverObserver';
import { useModuleContext } from '@/AppBuilder/_contexts/ModuleContext';

const QueryCardMenu = ({ darkMode }) => {
  const { moduleId } = useModuleContext();
  const appId = useStore((state) => state.appStore.modules[moduleId].app.appId);
  const selectedQuery = useStore((state) => state.queryPanel.selectedQuery);
  const toggleQueryPermissionModal = useStore((state) => state.queryPanel.toggleQueryPermissionModal);
  const hasAppPermissionQuery = useStore((state) => state?.license?.featureAccess?.appPermissionQuery ?? false);
  const targetBtnForMenu = useStore((state) => state.queryPanel.targetBtnForMenu);
  const targetElement = document.getElementById(targetBtnForMenu);
  const showQueryHandlerMenu = useStore((state) => state.queryPanel.showQueryHandlerMenu);
  const toggleQueryHandlerMenu = useStore((state) => state.queryPanel.toggleQueryHandlerMenu);
  const duplicateQuery = useStore((state) => state.dataQuery.duplicateQuery);
  const setPreviewData = useStore((state) => state.queryPanel.setPreviewData);
  const setRenamingQuery = useStore((state) => state.queryPanel.setRenamingQuery);
  const deleteDataQuery = useStore((state) => state.queryPanel.deleteDataQuery);
  const setEntityToViewDependencies = useStore((state) => state.setEntityToViewDependencies);

  const QUERY_MENU_OPTIONS = [
    {
      label: 'Rename',
      value: 'rename',
      icon: <Edit width={16} />,
    },
    {
      label: 'Duplicate',
      value: 'duplicate',
      icon: <Copy width={16} />,
    },
    {
      label: 'View dependencies',
      value: 'view-dependencies',
      icon: <Waypoints size={16} color="var(--icon-strong)" />,
    },
    {
      label: 'Query permission',
      value: 'permission',
      icon: (
        <img
          alt="permission-icon"
          src="assets/images/icons/editor/left-sidebar/authorization.svg"
          width="16"
          height="16"
        />
      ),
      trailingIcon: <SolidIcon width={16} name="enterprisecrown" className="mx-1" />,
    },
    {
      label: 'Delete',
      value: 'delete',
      icon: <Trash width={16} fill={'#E54D2E'} />,
    },
  ];

  const debouncedDuplicateQuery = useCallback(
    debounce((queryId, appId) => {
      duplicateQuery(queryId, appId);
      setPreviewData(null);
    }, 500),
    [duplicateQuery]
  );

  const handleQueryMenuActions = (value) => {
    if (value === 'rename') {
      setRenamingQuery(selectedQuery?.id);
    }
    if (value === 'duplicate') {
      debouncedDuplicateQuery(selectedQuery?.id, appId);
    }
    if (value === 'view-dependencies') {
      setEntityToViewDependencies?.({ kind: 'query', id: selectedQuery?.id });
    }
    if (value === 'permission') {
      if (!hasAppPermissionQuery) return;
      toggleQueryPermissionModal(true);
    }
    if (value === 'delete') {
      deleteDataQuery(selectedQuery?.id);
    }
    toggleQueryHandlerMenu(false);
  };

  usePopoverObserver(
    document.getElementsByClassName('query-list')[0],
    targetElement,
    document.getElementById('query-list-menu'),
    showQueryHandlerMenu,
    () => (document.getElementById('query-list-menu').style.display = 'block'),
    () => (document.getElementById('query-list-menu').style.display = 'none')
  );

  return (
    <>
      <Overlay
        placement="bottom-start"
        target={targetElement}
        show={showQueryHandlerMenu}
        rootClose
        transition={false}
        onHide={() => toggleQueryHandlerMenu(false)}
        popperConfig={{
          strategy: 'absolute',
          modifiers: [
            {
              name: 'flip',
              enabled: true,
              options: {
                fallbackPlacements: ['top-start', 'top-end', 'bottom-start', 'bottom-end', 'left-start', 'right-start'],
                boundary: 'viewport',
              },
            },
            {
              name: 'preventOverflow',
              enabled: true,
              options: { boundary: 'viewport', rootBoundary: 'viewport', padding: 8, altAxis: true, altBoundary: true },
            },
            { name: 'shift', enabled: true, options: { boundary: 'viewport', padding: 8 } },
            { name: 'offset', options: { offset: [0, 3] } },
          ],
        }}
      >
        {(props) => (
          <Popover {...props} id="query-list-menu" className={darkMode && 'dark-theme'}>
            <Popover.Body bsPrefix="list-item-popover-body">
              {QUERY_MENU_OPTIONS.map((option) => {
                const optionBody = (
                  <div
                    data-cy={`query-card-${String(option?.value).toLowerCase()}-button`}
                    className="list-item-popover-option"
                    key={option?.value}
                    onClick={(e) => {
                      e.stopPropagation();
                      handleQueryMenuActions(option.value);
                    }}
                  >
                    <div className="list-item-popover-menu-option-icon">{option.icon}</div>
                    <div
                      className={classNames('list-item-option-menu-label', {
                        'color-tomato9': option.value === 'delete',
                        'color-disabled': option.value === 'permission' && !hasAppPermissionQuery,
                      })}
                    >
                      {option?.label}
                    </div>
                    {option.value === 'permission' && !hasAppPermissionQuery && option.trailingIcon}
                  </div>
                );

                return option.value === 'permission' ? (
                  <ToolTip
                    key={option.value}
                    message={"You don't have access to query permissions. Upgrade your plan to access this feature."}
                    placement="right"
                    show={!hasAppPermissionQuery}
                  >
                    {optionBody}
                  </ToolTip>
                ) : (
                  optionBody
                );
              })}
            </Popover.Body>
          </Popover>
        )}
      </Overlay>
    </>
  );
};

export default QueryCardMenu;
