        <div className="d-flex justify-content-between mb-1">
          <label className="form-label"> {t('widget.commonProperties.timeFormat', 'Time Format')}</label>
          <div className={cx({ 'hide-fx': !isTimeFormatFxOn })}>
            <FxButton
              active={isTimeFormatFxOn}
              onPress={() => {
                paramUpdated({ name: 'timeFormat' }, 'fxActive', !isTimeFormatFxOn, 'properties');
              }}
            />
          </div>
        </div>
        {isTimeFormatFxOn ? (
          <CodeHinter
            initialValue={timeFormat}
            theme={darkMode ? 'monokai' : 'default'}
            mode="javascript"
            lineNumbers={false}
            onChange={(value) => paramUpdated({ name: 'timeFormat' }, 'value', value, 'properties')}
            validationFn={timeFormatValidationFn}
          />
        ) : (
          <Select
            options={TIME_FORMAT_OPTIONS}
            value={timeFormat ?? 'HH:mm'}
            search={true}
            closeOnSelect={true}
            onChange={(value) => {
              paramUpdated({ name: 'timeFormat' }, 'value', value, 'properties');
            }}
            fuzzySearch
            placeholder="Select.."
            useCustomStyles={true}
            styles={styles(darkMode, '100%', 32, { fontSize: '12px' })}
            customClassPrefix="inspector-select"
          />
        )}
      </div>
    );
  };

  if (['TimePicker'].includes(componentName)) {
    // I want my timeFormat section to be the 2nd property in the properties array and then the rest of the properties
    const transformedProperties = [...properties.slice(0, 1), 'timeFormat', ...properties.slice(1)];

    items.push({
      title: t('widget.common.data', 'Data'),
      isOpen: true,
      children: (
        <>
          {transformedProperties?.map((property) => {
            if (property === 'timeFormat') {
              return timeFormatSection();
            }
            return renderElement(
              component,
              componentMeta,
              paramUpdated,
              dataQueries,
              property,
              'properties',
              currentState,
              allComponents,
              darkMode
            );
          })}
        </>
      ),
    });
  } else {
    items.push({
      title: t('widget.common.data', 'Data'),
      isOpen: true,
      children: (
        <>
          {properties?.map((property) => {
            // DaterangePicker's Format is a generic code property — a tokenless
            // value is flagged inside its CodeHinter preview popover.
            if (property === 'format') {
              return renderElement(
                component,
                componentMeta,
                paramUpdated,
                dataQueries,
                property,
                'properties',
                currentState,
                allComponents,
                darkMode,
                '',
                dateFormatValidationFn
              );
            }
            if (['isTimezoneEnabled', 'customDateFormat'].includes(property)) {
              return (
                <>
                  <div
                    data-cy={`input-date-display-format`}
                    className="field mb-2 w-100 input-date-display-format"
                    onClick={(e) => e.stopPropagation()}
                    style={{
                      height: 'auto',
                    }}
                  >
                    <div className="field mb-2" onClick={(e) => e.stopPropagation()}>
                      <div className="d-flex justify-content-between mb-1">
                        <label className="form-label"> {t('widget.commonProperties.dateFormat', 'Date Format')}</label>
                        <div
                          className={cx({
                            'hide-fx': !isDateFormatFxOn,
                          })}
                        >
                          <FxButton
                            active={isDateFormatFxOn}
                            onPress={() => {
                              paramUpdated({ name: 'dateFormat' }, 'fxActive', !isDateFormatFxOn, 'properties');
                            }}
                          />
                        </div>
                      </div>
                      {isDateFormatFxOn ? (
                        <CodeHinter
                          initialValue={dateFormat}
                          theme={darkMode ? 'monokai' : 'default'}
                          mode="javascript"
                          lineNumbers={false}
                          onChange={(value) => paramUpdated({ name: 'dateFormat' }, 'value', value, 'properties')}
                          validationFn={dateFormatValidationFn}
                        />
                      ) : (
                        <Select
                          options={DATE_FORMAT_OPTIONS}
                          value={dateFormat ?? 'DD/MM/YYYY'}
                          search={true}
                          closeOnSelect={true}
                          onChange={(value) => {
                            paramUpdated({ name: 'dateFormat' }, 'value', value, 'properties');
                          }}
                          fuzzySearch
                          placeholder="Select.."
                          useCustomStyles={true}
                          styles={styles(darkMode, '100%', 32, { fontSize: '12px' })}
                          customClassPrefix="inspector-select"
                        />
                      )}
                    </div>
                  </div>
                  {!['DatePickerV2'].includes(componentName) && (
                    <>
                      {timeFormatSection()}

                      {renderElement(
                        component,
                        componentMeta,
                        paramUpdated,
                        dataQueries,
                        'isTimezoneEnabled',
                        'properties',
                        currentState,
                        allComponents,
                        darkMode
                      )}

                      {isTimezoneEnabled && (
                        <div style={{ paddingLeft: '16px', borderLeft: '1px solid #E4E7EB' }}>
                          <div
                            data-cy={`input-display-time-zone`}
                            className="field mb-2"
                            onClick={(e) => e.stopPropagation()}
                          >
                            <label data-cy={`label-display-time-zone`} className="form-label">
                              {t('widget.commonProperties.displayIn', 'Display in')}
                            </label>
                            <Select
                              options={TIMEZONE_REGION_OPTIONS}
                              value={displayTimezone || 'UTC'}
                              search={true}
                              closeOnSelect={true}
                              onChange={(value) => {
                                paramUpdated({ name: 'displayTimezone' }, 'value', value, 'properties');
                              }}
                              fuzzySearch
                              placeholder="Select.."
                              useCustomStyles={true}
                              styles={styles(darkMode, '100%', 32, { fontSize: '12px' })}
                            />
                          </div>
                          <div
                            data-cy={`input-display-time-zone`}
                            className="field mb-2"
                            onClick={(e) => e.stopPropagation()}
                          >
                            <label data-cy={`label-display-time-zone`} className="form-label">
                              {t('widget.commonProperties.storeIn', 'Store in')}
                            </label>
                            <Select
                              options={TIMEZONE_REGION_OPTIONS}
                              value={storeTimezone || 'UTC'}
                              search={true}
                              closeOnSelect={true}
                              onChange={(value) => {
                                paramUpdated({ name: 'storeTimezone' }, 'value', value, 'properties');
                              }}
                              fuzzySearch
                              placeholder="Select.."
                              useCustomStyles={true}
                              styles={styles(darkMode, '100%', 32, { fontSize: '12px' })}
                            />
                          </div>
                        </div>
                      )}
                    </>
                  )}
                </>
              );
            }

            return renderElement(
              component,
              componentMeta,
              paramUpdated,
              dataQueries,
              property,
              'properties',
              currentState,
              allComponents,
              darkMode
            );
          })}
        </>
      ),
    });
  }

  // if (componentName !== 'DaterangePicker') {
  //   items.push({
  //     title: 'Formatting',
  //     isOpen: true,
  //     children: (

  //     ),
  //   });
  // }

  items.push({
    title: t('widget.common.events', 'Events'),
    isOpen: true,
    children: (
      <EventManager
        sourceId={component?.id}
        eventSourceType="component"
        eventMetaDefinition={componentMeta}
        darkMode={darkMode}
      />
    ),
  });

  items.push({
    title: t('widget.common.validation', 'Validation'),
    isOpen: true,
    children: (
      <>
        {validations.map((property, index) =>
          renderElement(
            component,
            componentMeta,
            paramUpdated,
            dataQueries,
            property,
            'validation',
            currentState,
            allComponents,
            darkMode,
            getDynamicPlaceholder(property),
            getDynamicDateValidator(property)
          )
        )}
      </>
    ),
  });

  items.push({
    id: ADDITIONAL_ACTIONS_ACCORDION_ID,
    title: t('widget.common.additionalActions', 'Additional Actions'),
    isOpen: true,
    children: additionalActions.map((property) => {
      return renderElement(
        component,
        componentMeta,
        paramUpdated,
        dataQueries,
        property,
        'properties',
        currentState,
        allComponents,
        darkMode,
        componentMeta.properties?.[property]?.placeholder
      );
    }),
  });

  items.push({
    title: t('widget.common.devices', 'Devices'),
    isOpen: true,
    children: (
      <>
        {Object.keys(componentMeta.others).map((key) =>
          renderElement(
            component,
            componentMeta,
            layoutPropertyChanged,
            dataQueries,
            key,
            'others',
            currentState,
            allComponents
          )
        )}
      </>
    ),
  });

  return <Accordion items={items} />;
