const FxSelect = ({
  label,
  paramName,
  initialValue,
  darkMode,
  paramUpdated,
  options,
  onValueChange,
  paramType = 'properties',
  isFxActive: _isFxActive,
}) => {
  const [isFxActive, setIsFxActive] = useState(_isFxActive || false);
  // From paramName, not label: the label "File type" collides with the
  // properties-panel parseFileType field of the same name.
  const cyLabel = String(paramName).toLowerCase().trim().replace(/\s+/g, '-');

  const handleFxButtonClick = () => {
    paramUpdated({ name: paramName }, 'fxActive', !isFxActive, paramType);
    setIsFxActive(!isFxActive);
