export const FlexChildLayoutPanel = ({ selectedComponentId, allComponents }) => {
  const currentLayout = useStore((state) => state.currentLayout, shallow);
  const setComponentLayout = useStore((state) => state.setComponentLayout, shallow);
  const { subContainerWidths } = useGridStore((state) => ({ subContainerWidths: state.subContainerWidths }), shallow);
  const [widthPxEdit, setWidthPxEdit] = useState(null);

  const parentId = allComponents?.[selectedComponentId]?.component?.parent;
  const parentType = parentId ? allComponents?.[parentId]?.component?.component : null;
  const isFlexChild = parentType === 'FlexContainer';

  const layoutData = isFlexChild ? (allComponents?.[selectedComponentId]?.layouts?.[currentLayout] ?? {}) : {};

  const containerWidthPx = (parentId && subContainerWidths?.[parentId]) || subContainerWidths?.canvas;
  const gridCellWidthPx = containerWidthPx / NO_OF_GRIDS;
  const fallbackWidthPx = gridCellWidthPx;
  const fillWidth = layoutData.fillWidth ?? true;
  const widthPx = layoutData.widthPx ?? fallbackWidthPx;

  const widthMode = fillWidth ? 'fill-parent' : 'fixed';
  const widthValue = widthPx ?? fallbackWidthPx;

  useEffect(() => {
    setWidthPxEdit(null);
  }, [selectedComponentId, fillWidth]);

  if (!isFlexChild) return null;

  const update = (patch) => {
    setComponentLayout({ [selectedComponentId]: patch });
  };

  const handleWidthModeChange = (value) => {
    if (value === 'fill-parent') {
      update({ fillWidth: true });
    } else {
      update({ fillWidth: false, widthPx: widthValue });
    }
  };

  const handleWidthPxChange = (e) => {
    // Local edit only — commit on blur so partial values (e.g. "5" while clearing "50") are not saved.
    setWidthPxEdit(e.target.value);
  };

  const handleWidthPxBlur = () => {
    if (widthPxEdit === null) return;

    if (widthPxEdit === '') {
      setWidthPxEdit(null);
      return;
    }

    const parsed = parseInt(widthPxEdit, 10);
    if (isNaN(parsed)) {
      setWidthPxEdit(null);
      return;
    }

    update({ fillWidth: false, widthPx: parsed });
    setWidthPxEdit(null);
  };

  return (
    <div
      className="flex-child-layout-panel"
      data-cy="flex-child-layout-panel"
      style={{ display: 'flex', flexDirection: 'column', gap: 8 }}
    >
      <div style={{ display: 'flex', alignItems: 'center', justifyContent: 'space-between' }}>
        <label style={labelStyle}>Width</label>
        <div data-cy="flex-child-width-mode" style={{ width: '168px' }}>
          <Dropdown
            options={SIZE_OPTIONS}
            value={widthMode}
            size="small"
            width="168px"
            onChange={handleWidthModeChange}
          />
        </div>
      </div>

      {!fillWidth && (
        <div style={{ display: 'flex', alignItems: 'center', justifyContent: 'space-between' }}>
          <label style={labelStyle}>Width (px)</label>
          <input
            data-cy="flex-child-width-px"
            type="number"
            value={widthPxEdit !== null ? widthPxEdit : String(widthValue)}
            onChange={handleWidthPxChange}
            onBlur={handleWidthPxBlur}
            style={inputStyle}
          />
        </div>
      )}
    </div>
  );
};
import React from 'react';
import { FlexChildLayoutPanel } from './FlexChildLayoutPanel';
import { ADDITIONAL_ACTIONS_ACCORDION_ID } from '../../inspectorConstants';
import { resolveReferences } from '@/_helpers/utils';

const FLEX_AXIS_ICONS = {
  row: {
    justifyContent: [
      'align-horizontal-justify-start',
      'align-horizontal-justify-center',
      'align-horizontal-justify-end',
    ],
    alignItems: ['align-vertical-justify-start', 'align-vertical-justify-center', 'align-vertical-justify-end'],
  },
  column: {
    justifyContent: ['align-vertical-justify-start', 'align-vertical-justify-center', 'align-vertical-justify-end'],
    alignItems: ['align-horizontal-justify-start', 'align-horizontal-justify-center', 'align-horizontal-justify-end'],
  },
};

export function getFlexAxisAwareMeta(paramMeta, component, paramName) {
  if (paramName !== 'justifyContent' && paramName !== 'alignItems') return paramMeta;
  if (!Array.isArray(paramMeta?.options)) return paramMeta;

  const rawDirection = component?.component?.definition?.properties?.direction?.value;
  const resolved = resolveReferences(rawDirection);
  const direction = resolved === 'column' ? 'column' : 'row';
  const iconNames = FLEX_AXIS_ICONS[direction][paramName];

  const nextOptions = paramMeta.options.map((option, index) => ({
    ...option,
    lucideIconName: iconNames[index] ?? option.lucideIconName,
  }));
  return { ...paramMeta, options: nextOptions };
}

export const buildFlexChildWidthAccordionItem = ({ selectedComponentId, allComponents, title = 'Width' }) => ({
  title,
  children: <FlexChildLayoutPanel selectedComponentId={selectedComponentId} allComponents={allComponents} />,
});

export const injectFlexChildWidthBeforeAdditionalActions = (items, flexChildItem) => {
  if (!flexChildItem || !Array.isArray(items)) return items;

  const additionalActionsIndex = items.findIndex((item) => item?.id === ADDITIONAL_ACTIONS_ACCORDION_ID);
  if (additionalActionsIndex === -1) return items;

  const next = [...items];
  next.splice(additionalActionsIndex, 0, flexChildItem);
  return next;
};
import React from 'react';
import Accordion from '@/AppBuilder/RightSideBar/Inspector/InspectorAccordion';
import useStore from '@/AppBuilder/_stores/store';
import { shallow } from 'zustand/shallow';
import { useFormLogic } from './_hooks';
import { processComponentMeta } from './utils/componentMetaUtils';
import { createAccordionItems } from './config/accordionConfig';
