import useStore from '@/AppBuilder/_stores/store';

// Helper function to get display text for field type
const getFieldTypeDisplayText = (fieldType) => {
  const displayMap = {
    undefined: '',
    string: 'String',
    number: 'Number',
    text: 'Text',
    datepicker: 'Date time',
    select: 'Select',
    newMultiSelect: 'Multiselect',
    boolean: 'Boolean',
    image: 'Image',
    link: 'Link',
    json: 'JSON',
    markdown: 'Markdown',
    html: 'HTML',
  };
  return displayMap[fieldType] ?? capitalize(fieldType ?? '');
};

// Draggable item style
const getDraggableStyle = (isDragging, draggableStyle) => ({
  userSelect: 'none',
  ...draggableStyle,
});

export const FieldItem = ({
  item,
  index,
  activeFieldPopoverIndex,
  isRootCloseEnabled,
  darkMode,
  onRemove,
  onDuplicate,
  onTogglePopover,
  renderFieldPopover,
}) => {
  const getResolvedValue = useStore((state) => state.getResolvedValue);
  const resolvedItemName = getResolvedValue(item.name);
  const isEditable = getResolvedValue(item.isEditable);
  const fieldVisibility = getResolvedValue(item?.visibility) ?? true;
  const handleMenuOptionClick = useCallback(
    (listItem, menuOptionLabel) => {
      if (menuOptionLabel === 'Delete') {
        onRemove(index);
      } else if (menuOptionLabel === 'copyColumn') {
        onDuplicate(index);
      }
    },
    [index, onRemove, onDuplicate]
  );

  return (
    <Draggable draggableId={item.id} index={index}>
      {(provided, snapshot) => (
        <div
          ref={provided.innerRef}
          {...provided.draggableProps}
          {...provided.dragHandleProps}
          style={getDraggableStyle(snapshot.isDragging, provided.draggableProps.style)}
        >
          <OverlayTrigger
            trigger="click"
            placement="left"
            rootClose={isRootCloseEnabled}
            overlay={renderFieldPopover(item, index)}
            onToggle={(show) => onTogglePopover(index, show)}
          >
            <div className="table-column-lists" data-list-item-id={String(item.id ?? '')}>
              <List.Item
                isDraggable
                primaryText={resolvedItemName}
                secondaryText={getFieldTypeDisplayText(item?.fieldType)}
                data-cy={`field-${resolvedItemName}`}
                enableActionsMenu={false}
                isEditable={isEditable}
                onMenuOptionClick={handleMenuOptionClick}
                darkMode={darkMode}
                showIconOnHover
                deleteIconOutsideMenu
                showCopyColumnOption
                showVisibilityIcon
                isColumnVisible={fieldVisibility}
                className={activeFieldPopoverIndex === index ? 'active-column-list' : ''}
                columnType={item?.fieldType}
                Icon={getFieldIcon(item?.fieldType)}
              />
            </div>
          </OverlayTrigger>
        </div>
      )}
    </Draggable>
  );
};
import React, { useState, useEffect, useRef } from 'react';
import Popover from 'react-bootstrap/Popover';
import { PropertiesTabElements } from './PropertiesTabElements';

//TO-DO --> Update it to use resuable table component
export const FieldPopoverContent = ({
  field,
  index,
  darkMode,
  currentState,
  onFieldItemChange,
  getPopoverFieldSource,
  setFieldPopoverRootCloseBlocker,
  component,
  props,
  fieldEventChanged,
}) => {
  const [isGoingBelowScreen, setIsGoingBelowScreen] = useState(false);
  const popoverRef = useRef(null);

  // Check popover position to handle scrollbar visibility
  useEffect(() => {
    const checkPopoverPosition = () => {
      if (popoverRef.current) {
        const popoverRect = popoverRef.current.getBoundingClientRect();
        const viewportHeight = window.innerHeight;
        const isBelowScreen = popoverRect.bottom > viewportHeight;
        setIsGoingBelowScreen(isBelowScreen);
      }
    };

    const timeoutId = setTimeout(checkPopoverPosition, 100);
    window.addEventListener('resize', checkPopoverPosition);

    return () => {
      clearTimeout(timeoutId);
      window.removeEventListener('resize', checkPopoverPosition);
    };
  }, [index]);

  return (
    <>
      <Popover.Body
        ref={popoverRef}
        className={`table-column-popover ${darkMode && 'theme-dark'} ${isGoingBelowScreen ? 'show-scrollbar' : ''}`}
      >
        <PropertiesTabElements
          field={field}
          index={index}
          darkMode={darkMode}
          currentState={currentState}
          onFieldItemChange={onFieldItemChange}
          getPopoverFieldSource={getPopoverFieldSource}
          setFieldPopoverRootCloseBlocker={setFieldPopoverRootCloseBlocker}
          component={component}
          props={props}
          fieldEventChanged={fieldEventChanged}
        />
      </Popover.Body>
    </>
  );
};
