export const Navigation = ({ componentMeta, darkMode, ...restProps }) => {
  const {
    layoutPropertyChanged,
    component,
    dataQueries,
    paramUpdated,
    currentState,
    eventsChanged,
    apps,
    allComponents,
    pages,
  } = restProps;

  // Use the custom hook for menu items management
  const {
    menuItems,
    hoveredItemIndex,
    setHoveredItemIndex,
    expandedGroups,
    toggleGroupExpanded,
    handleItemChange,
    handleDeleteItem,
    handleAddItem,
    handleAddGroup,
    handleAddItemToGroup,
    handleReorder,
    getResolvedValue,
    validateItemId,
  } = useMenuItemsManager(component, paramUpdated);

  // Property organization
  let properties = [];
  let additionalActions = [];

  for (const [key] of Object.entries(componentMeta?.properties || {})) {
    if (componentMeta?.properties[key]?.section === 'additionalActions') {
      additionalActions.push(key);
    } else {
      properties.push(key);
    }
  }

  // Render menu items list
  const _renderMenuItems = () => {
    return (
      <NavItemsList
        componentId={component?.id}
        menuItems={menuItems}
        darkMode={darkMode}
        hoveredItemIndex={hoveredItemIndex}
        onMouseEnter={setHoveredItemIndex}
        onMouseLeave={() => setHoveredItemIndex(null)}
        onDeleteItem={handleDeleteItem}
        onItemChange={handleItemChange}
        validateItemId={validateItemId}
        onAddItem={handleAddItem}
        onAddGroup={handleAddGroup}
        onAddItemToGroup={handleAddItemToGroup}
        onReorder={handleReorder}
        getResolvedValue={getResolvedValue}
        expandedGroups={expandedGroups}
        onToggleExpand={toggleGroupExpanded}
        {...restProps}
      />
    );
  };

  // Helper function to create renderElement with common parameters
  const createRenderElement = (property, type = 'properties', extraProps = {}) => {
    return renderElement(
      component,
      componentMeta,
      extraProps.paramUpdated || paramUpdated,
      dataQueries,
      property,
      type,
      currentState,
      allComponents,
      extraProps.darkMode || darkMode,
      extraProps.placeholder || ''
    );
  };

  // Helper function to create accordion items
  const createAccordionItem = (title, children, isOpen = true, id) => ({
    id,
    title,
    isOpen,
    children,
  });

  // Section configurations
  const sections = [
    {
      title: 'Content',
      custom: () => <>{_renderMenuItems()}</>,
    },
    {
      title: 'Events',
      custom: () => (
        <EventManager
          sourceId={component?.id}
          eventSourceType="component"
          eventMetaDefinition={componentMeta}
          excludeRefEvents
          dataQueries={dataQueries}
          components={allComponents}
          eventsChanged={eventsChanged}
          apps={apps}
          darkMode={darkMode}
          pages={pages}
        />
      ),
    },
    {
      id: ADDITIONAL_ACTIONS_ACCORDION_ID,
      title: 'Additional Actions',
      type: 'properties',
      properties: additionalActions,
      extraProps: (property) => ({
        placeholder: componentMeta.properties?.[property]?.placeholder,
      }),
    },
    {
      title: 'Devices',
      type: 'others',
      properties: ['showOnDesktop', 'showOnMobile'],
      extraProps: () => ({ paramUpdated: layoutPropertyChanged }),
    },
  ];

  // Build accordion items
  const items = sections.map((section) => {
    if (section.custom) {
      return createAccordionItem(section.title, section.custom(), section.isOpen, section.id);
    }

    const children = section.properties.map((property) => {
      const extraProps = section.extraProps ? section.extraProps(property) : {};
      return createRenderElement(property, section.type, extraProps);
    });

    return createAccordionItem(section.title, children, section.isOpen, section.id);
  });

  return <Accordion items={items} />;
};
