import React, { useMemo, useState } from 'react';
import Accordion from '@/AppBuilder/RightSideBar/Inspector/InspectorAccordion';
import { baseComponentProperties } from '../DefaultComponent';
import Select from '@/_ui/Select';
// eslint-disable-next-line import/no-unresolved
import { getCountries } from 'react-phone-number-input/input';
// eslint-disable-next-line import/no-unresolved
import en from 'react-phone-number-input/locale/en';
// eslint-disable-next-line import/no-unresolved
import flags from 'react-phone-number-input/flags';
import FxButton from '@/AppBuilder/CodeBuilder/Elements/FxButton';
import CodeHinter from '@/AppBuilder/CodeEditor';
import cx from 'classnames';

export const PhoneInput = ({ componentMeta, darkMode, ...restProps }) => {
  const {
    layoutPropertyChanged,
    component,
    paramUpdated,
    dataQueries,
    currentState,
    eventsChanged,
    apps,
    allComponents,
  } = restProps;

  const properties = Object.keys(componentMeta.properties);
  const events = Object.keys(componentMeta.events);
  const validations = Object.keys(componentMeta.validation || {});
  const defaultCountry = componentMeta?.definition?.properties?.defaultCountry?.value || 'US';
  // This was `properties.dateFormat.fxActive`, a Datepicker key copied in here. The read and the
  // write used the same wrong key, so the toggle worked, but it stored a phantom `dateFormat`
  // property on every app that used it and never wrote the real one. Apps saved under the old
  // key are moved across by the MigrateDefaultCountryFxKey data migration, which is why no
  // fallback read is carried here.
  const isDefaultCountryFxOn = componentMeta?.definition?.properties?.defaultCountry?.fxActive || false;

  const options = useMemo(
    () =>
      getCountries().map((country) => ({
        label: `${en[country]}`,
        value: country,
      })),
    []
  );

  const renderCustomOption = ({ label, value: optionValue }) => {
    const optionStyle = {
      display: 'flex',
      alignItems: 'center',
      justifyContent: 'start',
      height: '18px',
      gap: '6px',
      cursor: 'pointer',
      fontFamily: 'IBM Plex Sans',
      fontSize: '12px',
      lineHeight: '18px',
      fontWeight: '400',
      color: darkMode ? '#fff' : '#1B1F24',
    };
    const FlagIcon = flags[optionValue];

    return (
      <div style={optionStyle} className={`selectedOption  ${optionValue !== 'none' && 'custom-phone-input-options'}`}>
        <div>{FlagIcon ? <FlagIcon style={{ width: '22px', height: '16px' }} /> : null}</div>
        {label}
      </div>
    );
  };

  const getCountryDropdown = () => {
    return (
      <div className="mb-2">
        <div className="d-flex justify-content-between mb-1">
          <label className="form-label"> Default Country</label>
          <div
            className={cx({
              'hide-fx': !isDefaultCountryFxOn,
            })}
          >
            <FxButton
              active={isDefaultCountryFxOn}
              onPress={() => {
                paramUpdated({ name: 'defaultCountry' }, 'fxActive', !isDefaultCountryFxOn, 'properties');
              }}
            />
          </div>
        </div>
        {isDefaultCountryFxOn ? (
          <CodeHinter
            initialValue={defaultCountry}
            theme={darkMode ? 'monokai' : 'default'}
            mode="javascript"
            lineNumbers={false}
            onChange={(value) => paramUpdated({ name: 'defaultCountry' }, 'value', value, 'properties')}
          />
        ) : (
          <Select
            width="100%"
            options={options}
            value={defaultCountry}
            customOption={renderCustomOption}
            onChange={(value) => {
              paramUpdated({ name: 'defaultCountry' }, 'value', value, 'properties');
            }}
          />
        )}
      </div>
    );
  };

  const filteredProperties = properties.filter(
    (property) => !['additionalActions', 'deprecatedStyles'].includes(componentMeta.properties[property].section)
  );

  const additionalActions = properties.filter(
    (property) => componentMeta.properties[property].section === 'additionalActions'
  );

  const accordionItems = baseComponentProperties(
    filteredProperties,
    events,
    component,
    componentMeta,
    layoutPropertyChanged,
    paramUpdated,
    dataQueries,
    currentState,
    eventsChanged,
    apps,
    allComponents,
    validations,
    darkMode,
    null,
    additionalActions
  );

  accordionItems[0].children.splice(3, 0, getCountryDropdown());

  return <Accordion items={accordionItems} />;
};
import React from 'react';
import { renderElement } from '../../Utils';
import Accordion from '@/AppBuilder/RightSideBar/Inspector/InspectorAccordion';
import { ADDITIONAL_ACTIONS_ACCORDION_ID } from '../../inspectorConstants';
import { EventManager } from '../../EventManager';
import { OptionsList } from './components';
import { useOptionsManager } from './hooks/useOptionsManager';
import { COMPONENT_INSPECTOR_CONFIG, DEFAULT_CONFIG } from './constants';
import './styles.scss';

export const PopoverMenu = ({ componentMeta, darkMode, ...restProps }) => {
  const {
    layoutPropertyChanged,
    component,
    dataQueries,
    paramUpdated,
    currentState,
    eventsChanged,
    apps,
    allComponents,
    pages,
  } = restProps;

  const componentType = component?.component?.component;
  const config = { ...DEFAULT_CONFIG, ...COMPONENT_INSPECTOR_CONFIG[componentType] };

  // Use the custom hook for options management
  const {
    options,
    hoveredOptionIndex,
    setHoveredOptionIndex,
    handleOptionChange,
    handleDeleteOption,
    handleAddOption,
    onDragEnd,
    getItemStyle,
    getResolvedValue,
    isDynamicOptionsEnabled,
    handleDefaultChange,
  } = useOptionsManager(component, paramUpdated, config.optionLabelPrefix);

  // ===== PROPERTY ORGANIZATION =====
  const validations = Object.keys(componentMeta.validation || {});
  let properties = [];
  let additionalActions = [];
  let optionsProperties = [];

  for (const [key] of Object.entries(componentMeta?.properties)) {
    if (componentMeta?.properties[key]?.section === 'additionalActions') {
      additionalActions.push(key);
    } else if (componentMeta?.properties[key]?.accordian === 'Options') {
      optionsProperties.push(key);
    } else {
      properties.push(key);
    }
  }

  // ===== RENDER FUNCTIONS =====
  const _renderOptions = () => {
    return (
      <OptionsList
        options={options}
        darkMode={darkMode}
        hoveredOptionIndex={hoveredOptionIndex}
        onMouseEnter={setHoveredOptionIndex}
        onMouseLeave={() => setHoveredOptionIndex(null)}
        onDeleteOption={handleDeleteOption}
        onOptionChange={handleOptionChange}
        onAddOption={handleAddOption}
        onDragEnd={onDragEnd}
        onDefaultChange={handleDefaultChange}
        getResolvedValue={getResolvedValue}
        getItemStyle={getItemStyle}
        componentType={componentType}
        config={config}
        {...restProps}
      />
    );
  };

  // ===== MAIN RENDER =====
  // Helper function to create renderElement with common parameters
  const createRenderElement = (property, type = 'properties', extraProps = {}) => {
    return renderElement(
      component,
      componentMeta,
      extraProps.paramUpdated || paramUpdated,
      dataQueries,
      property,
      type,
      currentState,
      allComponents,
      extraProps.darkMode || darkMode,
      extraProps.placeholder || ''
    );
  };

  // Helper function to create accordion items
  const createAccordionItem = (title, children, isOpen = true, id) => ({
    id,
    title,
    isOpen,
    children,
  });

  // Section configurations
  const mainProperties = properties.filter((property) => !optionsProperties.includes(property));

  const sections = [
    ...(!config.singleDataSection && mainProperties.length > 0
      ? [
          {
            title: config.propertiesAccordionTitle,
            type: 'properties',
            properties: mainProperties,
          },
        ]
      : []),
    {
      title: !config.singleDataSection ? config.optionsAccordionTitle || 'Options' : config.propertiesAccordionTitle,
      custom: () => (
        <>
          {createRenderElement('advanced')}
          {isDynamicOptionsEnabled ? (
            <>
              {createRenderElement('schema')}{' '}
              {optionsProperties.includes('optionsLoadingState') && createRenderElement('optionsLoadingState')}
            </>
          ) : (
            _renderOptions()
          )}
          {optionsProperties.includes('multiSelection') && createRenderElement('multiSelection')}
          {optionsProperties.includes('layout') && createRenderElement('layout')}
        </>
      ),
    },
    {
      title: 'Events',
      custom: () => (
        <EventManager
          sourceId={component?.id}
          eventSourceType="component"
          eventMetaDefinition={componentMeta}
          dataQueries={dataQueries}
          components={allComponents}
          eventsChanged={eventsChanged}
          apps={apps}
          darkMode={darkMode}
          pages={pages}
        />
      ),
    },
    ...(validations.length > 0
      ? [
          {
            title: 'Validation',
            type: 'validation',
            properties: validations,
            extraProps: (property) => ({
              placeholder: componentMeta.validation?.[property]?.placeholder,
            }),
          },
        ]
      : []),
    ...(additionalActions.length > 0
      ? [
          {
            id: ADDITIONAL_ACTIONS_ACCORDION_ID,
            title: 'Additional Actions',
            type: 'properties',
            properties: additionalActions,
            extraProps: (property) => ({
              placeholder: componentMeta.properties?.[property]?.placeholder,
            }),
          },
        ]
      : []),
    {
      title: 'Devices',
      type: 'others',
      properties: ['showOnDesktop', 'showOnMobile'],
      extraProps: () => ({ paramUpdated: layoutPropertyChanged }),
    },
  ];

  // Build accordion items
  const items = sections.map((section) => {
    if (section.custom) {
      return createAccordionItem(section.title, section.custom(), section.isOpen, section.id);
    }

    const children = section.properties.map((property) => {
      const extraProps = section.extraProps ? section.extraProps(property) : {};
      return createRenderElement(property, section.type, extraProps);
    });

    return createAccordionItem(section.title, children, section.isOpen, section.id);
  });

  return <Accordion items={items} />;
};
