import React from 'react';
import { Draggable } from 'react-beautiful-dnd';
import OverlayTrigger from 'react-bootstrap/OverlayTrigger';
import ListGroup from 'react-bootstrap/ListGroup';
import SortableList from '@/_components/SortableList';
import { ButtonSolid } from '@/_ui/AppButton/AppButton';
import Trash from '@/_ui/Icon/solidIcons/Trash';
import { getSafeRenderableValue } from '@/AppBuilder/Widgets/utils';
import OptionDetailsPopover from './OptionDetailsPopover';

const OptionItem = ({
  item,
  index,
  darkMode,
  hoveredOptionIndex,
  onMouseEnter,
  onMouseLeave,
  onDeleteOption,
  onOptionChange,
  getResolvedValue,
  getItemStyle,
  config, // Configurable props for reuse
  ...restProps
}) => {
  const { dataCy: dataCyPrefix } = config;
  const { onDefaultChange, componentType } = restProps;

  return (
    <Draggable key={item?.value} draggableId={item?.value} index={index}>
      {(provided, snapshot) => {
        return (
          <div
            key={index}
            data-cy={`${dataCyPrefix}-option-${index}`}
            data-list-item-id={String(item?.value ?? '')}
            ref={provided.innerRef}
            {...provided.draggableProps}
            {...provided.dragHandleProps}
            style={getItemStyle(snapshot.isDragging, provided.draggableProps.style)}
          >
            <OverlayTrigger
              trigger="click"
              placement="left"
              rootClose
              overlay={
                <OptionDetailsPopover
                  item={item}
                  index={index}
                  darkMode={darkMode}
                  onOptionChange={onOptionChange}
                  onDeleteOption={onDeleteOption}
                  onDefaultChange={onDefaultChange}
                  getResolvedValue={getResolvedValue}
                  config={config}
                  componentType={componentType}
                />
              }
              onToggle={(isOpen) => {
                if (!isOpen) {
                  document.activeElement?.blur(); // Manually trigger blur when popover closes
