                            e.stopPropagation();
                            onDeleteOption(index);
                          }}
                        >
                          <span className="d-flex">
                            <Trash fill={'var(--tomato9)'} width={12} />
                          </span>
                        </ButtonSolid>
                      )}
                    </div>
                  </div>
                </ListGroup.Item>
              </div>
            </OverlayTrigger>
          </div>
        );
      }}
    </Draggable>
  );
