  const onChangeIcon = (item, value, property, index) => {
    const updatedTabItems = tabItems.map((tabItem) => {
      if (tabItem.id === item.id) {
        return {
          ...tabItem,
          [property]: value,
          iconVisibility: { value: true },
        };
      }
      return tabItem;
    });

    setTabItems(updatedTabItems);
    updateAllTabItemsParams(updatedTabItems);
  };

  const validateTabId = (value, currentItemId) =>
    validateStaticId(
      value,
      tabItems.map((tab) => tab.id),
      currentItemId,
      {
        emptyMessage: 'Tab ID cannot be empty',
        bindingMessage: 'Tab ID cannot contain a dynamic binding ({{ }}). Use a plain, static value.',
        duplicateMessage: 'Tab ID must be unique. This ID is already used by another tab.',
      }
    );

  const areAllTabIdsValid = () => {
    const ids = tabItems.map((tab) => tab.id);
    const uniqueIds = new Set(ids);
    return ids.length === uniqueIds.size;
  };

  const updateAllTabItemsParams = (tabItems) => {
    if (areAllTabIdsValid()) {
      // `_key` is render-only identity; strip before persisting.
      const itemsToPersist = tabItems.map(({ _key, ...tabItem }) => tabItem);
      paramUpdated({ name: 'tabItems' }, 'value', itemsToPersist, 'properties', false);
    }
  };

  const _renderOverlay = (item, index) => {
    const iconVisibility =
      item?.iconVisibility?.value !== undefined ? getResolvedValue(item?.iconVisibility?.value) : item?.iconVisibility;

    return (
      <Popover className={`${darkMode && 'dark-theme theme-dark'}`} style={{ minWidth: '248px' }}>
        <Popover.Body onClick={(e) => e.stopPropagation()}>
          <div className="field mb-3" data-cy={`input-and-label-tab-title`}>
            <label data-cy={`label-tab-title`} className="font-weight-500 mb-1 font-size-12">
              {'Tab Title'}
            </label>
            <CodeHinter
              currentState={currentState}
              type={'basic'}
              initialValue={item?.title}
              theme={darkMode ? 'monokai' : 'default'}
              mode="javascript"
              lineNumbers={false}
              placeholder={'Tab Title'}
              onChange={(value) => handleValueChange(item, value, 'title', index)}
            />
          </div>

          <div className="field mb-3" data-cy={`input-and-label-tab-id`}>
            <label data-cy={`label-tab-id`} className="font-weight-500 mb-1 font-size-12">
              {'Id'}
            </label>
            <CodeHinter
              key={idFieldResetKeys[item._key] || 0}
              currentState={currentState}
              type={'basic'}
              initialValue={item?.id}
              theme={darkMode ? 'monokai' : 'default'}
              mode="javascript"
              lineNumbers={false}
              placeholder={'Tab ID'}
              onChange={(value) => handleValueChange(item, value, 'id', index)}
              validationFn={(value) => validateTabId(value, item?.id)}
            />
          </div>

          <div className="field mb-3" data-cy={`input-and-label-tab-id`}>
            <CodeHinter
              currentState={currentState}
              initialValue={item?.icon?.value || ''}
              theme={darkMode ? 'monokai' : 'default'}
              mode="javascript"
              lineNumbers={false}
              component={component}
              type={'fxEditor'}
              paramLabel={'Icon'}
              paramName={'icon'}
              onChange={(value) => {
                onChangeIcon(item, { value }, 'icon', index);
              }}
              onVisibilityChange={(value) => onChangeVisibility(item, { value: true }, 'iconVisibility', index)}
              fieldMeta={{ type: 'icon', displayName: 'Icon' }}
              paramType={'icon'}
              iconVisibility={iconVisibility}
            />
          </div>

          <div className="field mb-2">
            <CodeHinter
              currentState={currentState}
              initialValue={item?.fieldBackgroundColor?.value}
              theme={darkMode ? 'monokai' : 'default'}
              mode="javascript"
              lineNumbers={false}
              component={component}
              type={'fxEditor'}
              paramLabel={'Background'}
              paramName={'fieldBackgroundColor'}
              onChange={(value) => {
                handleValueChange(item, { value }, 'fieldBackgroundColor', index);
              }}
              fieldMeta={{ type: 'colorSwatches', displayName: 'Background' }}
              paramType={'colorSwatches'}
            />
          </div>

          <div className="field mb-2">
            <CodeHinter
              currentState={currentState}
              initialValue={item?.loading?.value}
              theme={darkMode ? 'monokai' : 'default'}
              mode="javascript"
              lineNumbers={false}
              component={component}
              type={'fxEditor'}
              paramLabel={'Loading'}
              paramName={'loading'}
              onChange={(value) => {
                handleValueChange(item, { value }, 'loading', index);
              }}
              onFxPress={(active) => handleOnFxPress(item, 'loading', active)}
              fxActive={item?.loading?.fxActive}
              fieldMeta={{ type: 'toggle', displayName: 'Loading' }}
              paramType={'toggle'}
            />
          </div>

          <div className="field mb-2" data-cy={`input-and-label-tab-visible`}>
            <CodeHinter
              currentState={currentState}
              initialValue={item?.visible?.value}
              theme={darkMode ? 'monokai' : 'default'}
              mode="javascript"
              lineNumbers={false}
              component={component}
              type={'fxEditor'}
              paramLabel={'Visibility'}
              onChange={(value) => handleValueChange(item, { value }, 'visible', index)}
              paramName={'visible'}
              onFxPress={(active) => handleOnFxPress(item, 'visible', active)}
              fxActive={item?.visible?.fxActive}
              fieldMeta={{
                type: 'toggle',
                displayName: 'Visible',
              }}
              paramType={'toggle'}
            />
          </div>
          <div className="field" data-cy={`input-and-label-tab-disable`}>
            <CodeHinter
              currentState={currentState}
              initialValue={item?.disable?.value}
              theme={darkMode ? 'monokai' : 'default'}
              mode="javascript"
              lineNumbers={false}
              component={component}
              type={'fxEditor'}
              paramLabel={'Disable'}
              paramName={'disable'}
              onChange={(value) => handleValueChange(item, { value }, 'disable', index)}
              onFxPress={(active) => handleOnFxPress(item, 'disable', active)}
              fxActive={item?.disable?.fxActive}
              fieldMeta={{
                type: 'toggle',
                displayName: 'Disable',
              }}
              paramType={'toggle'}
            />
          </div>
        </Popover.Body>
      </Popover>
    );
  };

  useEffect(() => {
    setTabItems(constructTabItems());
  }, [isDynamicEnabled, component?.id]);

  const handleToggleColumnPopover = (index) => {
    setActiveColumnPopoverIndex(index);
  };

  const _renderTabOptions = () => {
    return (
      <List style={{ marginBottom: '20px' }}>
        <DragDropContext
          onDragEnd={(result) => {
            onDragEnd(result);
          }}
        >
          <Droppable droppableId="droppable">
            {({ innerRef, droppableProps, placeholder }) => (
              <div className="w-100" {...droppableProps} ref={innerRef}>
                {tabItems?.map((item, index) => {
                  const dragId = item._key || item.title + item.id;
                  return (
                    <Draggable key={dragId} draggableId={dragId} index={index}>
                      {(provided, snapshot) => (
                        <div
                          key={index}
                          data-list-item-id={String(item.id ?? '')}
                          ref={provided.innerRef}
                          {...provided.draggableProps}
                          {...provided.dragHandleProps}
                          style={getItemStyle(snapshot.isDragging, provided.draggableProps.style)}
                          className="tabs-list"
                        >
                          <OverlayTrigger
                            trigger="click"
                            placement="left"
                            rootClose
                            show={activeColumnPopoverIndex === index}
                            overlay={_renderOverlay(item, index)}
                            onToggle={(show) => {
                              if (show) {
                                handleToggleColumnPopover(index);
                              } else {
                                handleToggleColumnPopover(null);
                              }
                            }}
                          >
                            <div
                              key={item.title}
                              style={{
                                marginBottom: '8px',
                              }}
                            >
                              <ListGroup.Item
                                isDraggable={true}
                                onMouseEnter={() => setHoveredTabItemIndex(index)}
                                onMouseLeave={() => setHoveredTabItemIndex(null)}
                                className={activeColumnPopoverIndex === index && 'active-column-list'}
                                {...restProps}
                              >
                                <div className="row">
                                  <div className="col-auto d-flex align-items-center">
                                    <SortableList.DragHandle show />
                                  </div>
                                  <div className="col text-truncate cursor-pointer" style={{ padding: '0px' }}>
                                    {getSafeRenderableValue(resolveReferences(item.title, currentState))}
                                  </div>
                                  <div className="col-auto">
                                    {index === hoveredTabItemIndex && (
                                      <ButtonSolid
                                        variant="danger"
                                        size="xs"
                                        className={'delete-icon-btn'}
                                        onClick={(e) => {
                                          e.stopPropagation();
                                          handleDeleteTabItem(index);
                                        }}
                                      >
                                        <span className="d-flex">
                                          <Trash fill={'var(--tomato9)'} width={12} />
                                        </span>
                                      </ButtonSolid>
                                    )}
                                  </div>
                                </div>
                              </ListGroup.Item>
                            </div>
                          </OverlayTrigger>
                        </div>
                      )}
                    </Draggable>
                  );
                })}
                {placeholder}
              </div>
            )}
          </Droppable>
        </DragDropContext>
        <AddNewButton onClick={handleAddTabItem} className="mt-0">
          Add new tab
        </AddNewButton>
      </List>
    );
  };

  let items = [];

  if (properties.length > 0) {
    items.push({
      title: 'Options',
      isOpen: true,
      children: isDynamicEnabled ? (
        properties?.map((property) =>
          renderElement(
            component,
            componentMeta,
            paramUpdated,
            dataQueries,
            property,
            'properties',
            currentState,
            allComponents,
            darkMode
          )
        )
      ) : (
        <>
          {renderElement(
            component,
            componentMeta,
            paramUpdated,
            dataQueries,
            'useDynamicOptions',
            'properties',
            currentState,
            allComponents
          )}
          {_renderTabOptions()}
        </>
      ),
    });
  }

  items.push({
    title: 'Events',
    isOpen: true,
    children: (
      <EventManager
        sourceId={component?.id}
        eventSourceType="component"
        eventMetaDefinition={componentMeta}
        currentState={currentState}
        dataQueries={dataQueries}
        components={allComponents}
        eventsChanged={eventsChanged}
        apps={apps}
        darkMode={darkMode}
        pages={pages}
      />
    ),
  });

  items.push({
    id: ADDITIONAL_ACTIONS_ACCORDION_ID,
    title: `Additional Actions`,
    isOpen: true,
    children: additionalActions.map((property) => {
      return renderElement(
        component,
        componentMeta,
        paramUpdated,
        dataQueries,
        property,
        'properties',
        currentState,
        allComponents,
        darkMode,
        componentMeta.properties?.[property]?.placeholder
      );
    }),
  });

  items.push({
    title: 'Devices',
    isOpen: true,
    children: (
      <>
        {renderElement(
          component,
          componentMeta,
          layoutPropertyChanged,
          dataQueries,
          'showOnDesktop',
          'others',
          currentState,
          allComponents
        )}
        {renderElement(
          component,
          componentMeta,
          layoutPropertyChanged,
          dataQueries,
          'showOnMobile',
          'others',
          currentState,
          allComponents
        )}
      </>
    ),
  });

  return <Accordion items={items} />;
}
import React, { useMemo } from 'react';
import { SortableTree } from '@/_ui/SortableTree';
import SolidIcon from '@/_ui/Icon/SolidIcons';
