const PROPERTY_NAMES = {
  isGroup: 'isGroup',
  parentId: 'parentId',
};

const ButtonListItem = ({ item, onSelect }) => (
  <div
    className="page-menu-item"
    onClick={(e) => {
      e.preventDefault();
      onSelect(item.id);
    }}
  >
    <div className="left">
