    if (isButtonDetailView) {
      removeButton(selectedButtonId);
      setSelectedButtonId(null);
    } else {
      onDeleteColumn?.();
    }
  };

  const handleDuplicate = () => {
    if (isButtonDetailView) {
      duplicateButton(selectedButtonId);
    } else {
      onDuplicateColumn?.();
    }
  };

