import { resolveReferences } from '@/_helpers/utils';
import React from 'react';
import CodeHinter from '@/AppBuilder/CodeEditor';

export const ProgramaticallyHandleProperties = ({
  index,
  callbackFunction,
  property,
  props = {},
  component,
  paramMeta,
}) => {
  const getValueBasedOnProperty = (property, props) => {
    if (property === 'makeDefaultOption') {
      return props?.[index]?.makeDefaultOption;
    }
    return props?.[property];
  };

  const getInitialValue = (property, definitionObj) => {
    if (property === 'columnVisibility') {
      return definitionObj?.value ?? `{{true}}`;
    }
    if (property === 'fieldVisibility') {
      return definitionObj?.value ?? `{{true}}`;
    }
    if (property === 'linkTarget') {
      const value = definitionObj?.value;
      if (value === '_self' || value === '{{false}}' || value === '') {
        return '{{false}}';
      }
      return value || '{{true}}';
    }
    if (property === 'cellBackgroundColor') {
      return definitionObj?.value || 'var(--cc-surface1-surface)';
    }
    if (property === 'textColor') {
      return definitionObj?.value ?? '#11181C';
    }
    if (property === 'labelColor') {
      // return definitionObj?.value ?? 'var(--cc-primary-text)';
      return definitionObj?.value ?? '#1B1F24';
    }
    if (property === 'optionColor') {
      // return definitionObj?.value ?? 'var(--cc-surface2-surface)';
      return definitionObj?.value ?? '#E4E7EB';
    }
    if (property === 'underlineColor') {
      return definitionObj?.value ?? '#4368E3';
    }
    if (property === 'underline') {
      return definitionObj?.value ?? 'hover';
    }
    if (property === 'linkColor') {
      return definitionObj?.value ?? '#1B1F24';
    }
    if (property === 'jsonIndentation') {
      return definitionObj?.value ?? `{{true}}`;
    }
    if (property === 'buttonVisibility') {
      return definitionObj?.value ?? '{{true}}';
    }
    if (property === 'disableButton') {
      return definitionObj?.value ?? '{{false}}';
    }
    if (property === 'loadingState') {
      return definitionObj?.value ?? '{{false}}';
    }
    if (property === 'buttonBackgroundColor') {
      return definitionObj?.value ?? 'var(--cc-primary-brand)';
    }
    if (property === 'buttonLabelColor') {
      return definitionObj?.value ?? 'var(--cc-surface1-surface)';
    }
    if (property === 'buttonIconColor') {
      return definitionObj?.value ?? 'var(--cc-surface1-surface)';
    }
    if (property === 'buttonLoaderColor') {
      return definitionObj?.value ?? 'var(--cc-surface1-surface)';
    }
    if (property === 'buttonBorderColor') {
      return definitionObj?.value ?? 'var(--cc-weak-border)';
    }
    if (property === 'buttonBorderRadius') {
      return definitionObj?.value ?? '6';
    }
    return definitionObj?.value ?? `{{false}}`;
  };

  const value = getValueBasedOnProperty(property, props);

  const param = { name: property === 'makeDefaultOption' ? `options::${property}` : property };
  let definition;
  let initialValue;
  if (Array.isArray(props)) {
    definition = { value, fxActive: props?.[index]?.fxActive };
    initialValue = getInitialValue(property, definition);
  } else {
    definition = { value, fxActive: props.fxActive };
    initialValue = getInitialValue(property, definition);
  }
  const options = {};

  const calcFxActiveState = (props, property) => {
    const fxActiveFieldsPresent = props?.hasOwnProperty('fxActiveFields');
    if (!fxActiveFieldsPresent) {
      return props?.fxActive ?? false;
    }
    const fxActiveFields = props.fxActiveFields;
    const propertyPresentInFxActiveFields = fxActiveFields.length >= 1 && fxActiveFields.includes(property);
    return propertyPresentInFxActiveFields;
  };

  const calculateFxActiveFields = (active, props, property) => {
    const fxActiveFieldsPropExists = props?.hasOwnProperty('fxActiveFields') ?? false;
    //to support backward compatibility, when fxActive is true for a particular column, we are passing all possible combinations which should render codehinter
    const fxActive =
      props?.fxActive && resolveReferences(props.fxActive)
        ? ['isEditable', 'columnVisibility', 'fieldVisibility', 'jsonIndentation', 'linkTarget']
        : [];

    const checkFxActiveFieldIsArrray = (fxActiveFieldsProperty) => {
      // adding error handling mechanism for fxActiveFieldsProperty , if props.fxActiveFields is array , then return props.fxActiveFields or else return [], this will make sure, fxActiveFields wil always be array
      return Array.isArray(fxActiveFieldsProperty) ? fxActiveFieldsProperty : [];
    };

    const fxActiveFields = fxActiveFieldsPropExists ? checkFxActiveFieldIsArrray(props.fxActiveFields) : fxActive;

    const findIndexOfPropertyInFxActiveFields = (property, fxActiveFields) => {
      // checking if particular property is already present in the fxActiveFields or not
      const index = fxActiveFields.findIndex((prop) => prop === property);
      return index;
    };

    const indexOfProp = findIndexOfPropertyInFxActiveFields(property, fxActiveFields);

    // removing or addding property for which we want to render codehinter
    if (active && indexOfProp === -1) {
      //if active is true and property does not present in the fxActiveField before hand, if both conditions are satisfied, we add it to the array of fxActiveField.
      fxActiveFields.push(property);
    } else if (!active && indexOfProp !== -1) {
      // if active is falsy and particular property is present in the fxActiveField , we remove that particular property from the array
      fxActiveFields.splice(indexOfProp, 1);
    }

    return fxActiveFields;
  };

  return (
    <div className={`field ${options.className}`} onClick={(e) => e.stopPropagation()}>
      <CodeHinter
        type="fxEditor"
        initialValue={initialValue}
        onChange={(value) => callbackFunction(index, property, value)}
        componentName={`component/${component?.component?.name}::${param.name}`}
        paramType={paramMeta.type}
        paramName={param.name}
        paramLabel={paramMeta.displayName}
        fieldMeta={paramMeta}
        onFxPress={(active) => {
          const resultFxActiveFields = calculateFxActiveFields(active, props, property);
          callbackFunction(index, 'fxActiveFields', resultFxActiveFields);
        }}
        fxActive={calcFxActiveState(props, property)}
        component={component.component}
        className={options.className}
      />
    </div>
  );
};
import React from 'react';
import Accordion from '@/AppBuilder/RightSideBar/Inspector/InspectorAccordion';
import List from '@/ToolJetUI/List/List';
import { DragDropContext, Droppable, Draggable } from 'react-beautiful-dnd';
import NoListItem from '../NoListItem';
import OverlayTrigger from 'react-bootstrap/OverlayTrigger';
import Popover from 'react-bootstrap/Popover';
import CodeHinter from '@/AppBuilder/CodeEditor';
import { ProgramaticallyHandleProperties } from '../ProgramaticallyHandleProperties';
import { resolveReferences } from '@/_helpers/utils';
import { Button as ButtonComponent } from '@/components/ui/Button/Button';
import { unset } from 'lodash';
import ToggleGroup from '@/ToolJetUI/SwitchGroup/ToggleGroup';
import ToggleGroupItem from '@/ToolJetUI/SwitchGroup/ToggleGroupItem';
import { DEFAULT_SELECT_COLUMN_OPTIONS } from '../utils';

export const OptionsList = ({
  column,
  props,
  index,
  darkMode,
  currentState,
  getPopoverFieldSource,
  setColumnPopoverRootCloseBlocker,
  onColumnItemChange,
  component,
  paramToUpdate,
}) => {
  const items = [];

  const recordOptions = (startIndex, endIndex) => {
    const columns =
      props.component.component.definition.properties.columns || props.component.component.definition.properties.fields;
    const column = columns.value[index];
    const options = column.options;
    const [removed] = options.splice(startIndex, 1);
    options.splice(endIndex, 0, removed);
    column.options = options;
    const newColumns = columns.value;
    newColumns[index] = column;
    props.paramUpdated({ name: paramToUpdate }, 'value', newColumns, 'properties', true);
  };

  const onDragEnd = async ({ source, destination }) => {
    if (!destination || source?.index === destination?.index) {
      return;
    }
    await recordOptions(source.index, destination.index);
  };

  const getItemStyle = (draggableStyle) => {
    return {
      ...draggableStyle,
      userSelect: 'none',
      position: 'static',
    };
  };

  const createNewOption = () => {
    const columns =
      props.component.component.definition.properties.columns || props.component.component.definition.properties.fields;
    const column = columns.value[index];
    const options = column.options || [];
    const labelPrefix = 'Option';
    let n = 1;
    let label = `${labelPrefix} ${n}`;
    while (options.some((o) => o.label === label || String(o.value) === String(label))) {
      n += 1;
      label = `${labelPrefix} ${n}`;
    }
    options.push({ label, value: label });
    column.options = options;
    const newColumns = columns.value;
    newColumns[index] = column;
    props.paramUpdated({ name: paramToUpdate }, 'value', newColumns, 'properties', true);
  };

  const deleteOption = (option, optionIndex) => {
    const columns =
      props.component.component.definition.properties.columns || props.component.component.definition.properties.fields;
    const column = columns.value[index];
    const options = column.options;
    const deletedOption = options.splice(optionIndex, 1);
    column.options = options;
    const defaultOptionsList = column.defaultOptionsList || [];
    const deletedOptionIndexInDefaultOptionsList = defaultOptionsList?.findIndex((defaultOption, index) => {
      if (
        defaultOption.value === deletedOption.value &&
        defaultOption.label === deletedOption.label &&
        defaultOption.makeDefaultOption === deletedOption.makeDefaultOption
      ) {
        return index;
      } else {
        return -1;
      }
    });
    if (deletedOptionIndexInDefaultOptionsList !== -1) {
      defaultOptionsList.splice(deletedOptionIndexInDefaultOptionsList, 1);
      column.defaultOptionsList = defaultOptionsList;
    }
    const newColumns = columns.value;
    newColumns[index] = column;
    props.paramUpdated({ name: paramToUpdate }, 'value', newColumns, 'properties', true);
  };

  const selectPopover = (option, optionIndex) => {
    const handleSelectOption = (option, optionIndex, value, index, optionItemChanged) => {
      const columns =
        props.component.component.definition.properties.columns ||
        props.component.component.definition.properties.fields;
      const column = columns.value[index];
      const options = column.options;
      options[optionIndex][optionItemChanged] = value;
      column.options = options;
      const newColumns = columns.value;
      newColumns[index] = column;
      props.paramUpdated({ name: paramToUpdate }, 'value', newColumns, 'properties', true);
    };

    const handleDefaultOptionSelection = (optionIndex, property, value) => {
      const columns =
        props.component.component.definition.properties.columns ||
        props.component.component.definition.properties.fields;
      const column = columns.value[index];
      const options = column.options;
      options[optionIndex][property] = value;
      column.options = options;
      const isValueTruthy = !!resolveReferences(value);

      // This block is responsible for updating list of defaultOptions when makeDefaultOption prop is updated
      if (property === 'makeDefaultOption') {
        if (column.columnType === 'select') {
          // Disable all other default options except the one selected
          column.options.forEach((option) => unset(option, 'makeDefaultOption'));
          column.options[optionIndex][property] = value;
          if (isValueTruthy) {
            column.defaultOptionsList = [column.options[optionIndex]];
          } else {
            column.defaultOptionsList = [];
          }
        } else {
          const defaultOptionsList = column?.defaultOptionsList ?? [];
          const indexOfOptionInList = defaultOptionsList.findIndex((option) => {
            if (option.value === options[optionIndex].value && option.label === options[optionIndex].label) {
              return option;
            }
          });
          if (indexOfOptionInList === -1 && isValueTruthy) {
            defaultOptionsList.push(options[optionIndex]);
          }
          if (indexOfOptionInList !== -1 && !isValueTruthy) {
            defaultOptionsList.splice(indexOfOptionInList, 1);
          }
          column.defaultOptionsList = defaultOptionsList;
        }
      }

      const newColumns = columns.value;
      newColumns[index] = column;

      props.paramUpdated({ name: paramToUpdate }, 'value', newColumns, 'properties', true);
    };

    const handleOptionColorChange = (index, property, value) => {
      handleSelectOption(option, optionIndex, value, index, property);
    };

    return (
      <Popover
        id="popover-basic"
        className={`${darkMode && 'dark-theme'}`}
        onClick={(e) => e.stopPropagation()}
        style={{
          zIndex: 99999,
          minWidth: 200,
          boxShadow: '0px 12px 16px -4px rgba(16, 24, 40, 0.08), 0px 4px 6px -2px rgba(16, 24, 40, 0.03)',
          borderRadius: '6px',
          border: '1px solid var(--border-default)',
        }}
      >
        <Popover.Body>
          <div className="field mb-2 tj-app-input" onClick={(e) => e.stopPropagation()}>
            <label data-cy={`label-action-button-text`} className="form-label">
              Option label
            </label>
            <CodeHinter
              currentState={currentState}
              initialValue={option?.label}
              theme={darkMode ? 'monokai' : 'default'}
              mode="javascript"
              lineNumbers={false}
              placeholder={option?.label}
              onChange={(value) => handleSelectOption(option, optionIndex, value, index, 'label')}
              componentName={getPopoverFieldSource(column.columnType, 'options::label')}
              popOverCallback={(showing) => {
                setColumnPopoverRootCloseBlocker('options::label', showing);
              }}
            />
          </div>
          <div className="field tj-app-input" onClick={(e) => e.stopPropagation()}>
            <label data-cy={`label-action-button-text`} className="form-label">
              Option value
            </label>
            <CodeHinter
              currentState={currentState}
              initialValue={option.value}
              theme={darkMode ? 'monokai' : 'default'}
              mode="javascript"
              lineNumbers={false}
