const getColumnTypeDisplayText = (columnType) => {
  const displayMap = {
    undefined: '',
    string: 'String',
    default: 'Default',
    number: 'Number',
    text: 'Text',
    badge: 'Badge',
    badges: 'Badges',
    tags: 'Tags',
    dropdown: 'Dropdown',
    link: 'Link',
    radio: 'Radio',
    multiselect: 'Multiselect deprecated',
    toggle: 'Toggle',
    datepicker: 'Datepicker',
    image: 'Image',
    boolean: 'Boolean',
    select: 'Select',
    newMultiSelect: 'Multiselect',
    tagsV2: 'Tags',
    json: 'JSON',
    markdown: 'Markdown',
    html: 'HTML',
    button: 'Button',
  };
  return displayMap[columnType] ?? capitalize(columnType ?? '');
};

