                                        className={activeColumnPopoverIndex === index ? 'active-column-list' : ''}
                                        columnType={item?.columnType}
                                        isDeprecated={checkIfTableColumnDeprecated(item?.columnType)}
                                        Icon={getColumnIcon(item?.columnType)}
                                      />
                                    </div>
                                  </OverlayTrigger>
                                </div>
                              )}
                            </Draggable>
                          );
                        })}
                        {placeholder}
                      </div>
                    )}
                  </Droppable>
                </DragDropContext>
                <div style={{ marginTop: '8px' }}>
                  {columns?.length === 0 && <NoListItem text="There are no columns" dataCy="-columns" />}
                  <div className="mb-2">
                    <AddNewButton dataCy="button-add-column" onClick={addColumn}>
                      {t('widget.Table.addNewColumn', ' Add new column')}
                    </AddNewButton>
                  </div>
                  {!useDynamicColumn && (
                    <div className="py-2">
                      <ProgramaticallyHandleProperties
                        label="Lock column schema"
                        currentState={currentState}
                        darkMode={darkMode}
                        callbackFunction={(_index, _property, lockOn) =>
                          paramUpdated(
                            { name: 'autogenerateColumns' },
                            'value',
                            !resolveReferences(lockOn),
                            'properties'
                          )
                        }
                        property="lockColumnSchema"
                        props={{
                          lockColumnSchema: `{{${isColumnSchemaLocked}}}`,
                        }}
                        component={component}
                        paramMeta={{
                          type: 'toggle',
                          displayName: 'Lock column schema',
                          isFxNotRequired: true,
                        }}
                        paramType="properties"
                      />
                    </div>
                  )}
                  <ProgramaticallyHandleProperties
                    label="Make all columns editable"
                    currentState={currentState}
                    darkMode={darkMode}
                    callbackFunction={(index, property, value) => setAllColumnsEditable(value)}
                    property="isAllColumnsEditable"
                    props={{
                      isAllColumnsEditable: `{{${isAllColumnsEditable}}}`,
                    }}
                    component={component}
                    paramMeta={{
                      type: 'toggle',
                      displayName: 'Make all columns editable',
                      isFxNotRequired: true,
                    }}
                    paramType="properties"
                  />
                </div>
              </List>
            )}
          </div>
        ),
      },
      // Action buttons section (deprecated — replaced by button column type)
      {
        title: (
          <div className="d-flex flex-row align-items-center" style={{ gap: '6px' }}>
            <span>Action buttons</span>
            <ToolTip
              message={
                <div
                  style={{
                    padding: '8px 4px',
                    textAlign: 'left',
                    width: '185px',
                  }}
                >
                  These Action buttons are deprecated and will be removed in a future update. Use the new Button column
                  instead by adding a new column and selecting type as a button.
                </div>
              }
              show={true}
              placement="bottom"
            >
              <span>
                <Icon name={'warning'} height={14} width={14} fill="#DB4324" />
              </span>
            </ToolTip>
          </div>
        ),
        children: (
          <div className="field">
            <div className="row g-2">
              <div>{actions.map((action, index) => renderActionButton(action, index))}</div>
              {actions.length === 0 && (
                <div className="mb-3">
                  <NoListItem text="No action buttons" dataCy="-action-button" />
                </div>
              )}
              <AddNewButton dataCy="button-add-new-action-button" onClick={addAction} className="mt-0">
                New action button
              </AddNewButton>
            </div>
          </div>
        ),
      },
      // Events section
      {
        title: 'Events',
        isOpen: true,
        children: (
          <EventManager
            component={component}
            sourceId={component?.id}
            eventSourceType="component"
            eventMetaDefinition={componentMeta}
            currentState={currentState}
            dataQueries={dataQueries}
            components={components}
            eventsChanged={eventsChanged}
            apps={apps}
            pages={pages}
          />
        ),
      },
      // Row Selection section
      {
        title: 'Row Selection',
        children: rowSelectionsOptions.map((option) => renderCustomElement(option)),
      },
      // Search, sort and filter section
      {
        title: 'Search, sort and filter',
        children: searchSortFilterOptions.map((option) => renderCustomElement(option)),
      },
      // Pagination section
      {
        title: 'Pagination',
        children: paginationOptions.map((option) => renderCustomElement(option)),
      },
      // Additional actions section
      {
        id: ADDITIONAL_ACTIONS_ACCORDION_ID,
        title: 'Additional actions',
        children: additionalActions.map((option) => renderCustomElement(option)),
      },
      // Devices section
      {
        title: 'Devices',
        isOpen: true,
        children: (
          <>
            {renderElement(
              component,
              componentMeta,
              layoutPropertyChanged,
              dataQueries,
              'showOnDesktop',
              'others',
              currentState,
              components
            )}
            {renderElement(
              component,
              componentMeta,
              layoutPropertyChanged,
              dataQueries,
              'showOnMobile',
              'others',
              currentState,
              components
            )}
          </>
        ),
      },
    ],
    [
      component,
      componentMeta,
      paramUpdated,
      dataQueries,
      currentState,
      components,
      darkMode,
      renderCustomElement,
      useDynamicColumn,
      isColumnSchemaLocked,
      handleDragEnd,
      filteredColumns,
      isRootCloseEnabled,
      renderColumnPopover,
      handleToggleColumnPopover,
      removeColumn,
      duplicateColumn,
      activeColumnPopoverIndex,
      columns,
      addColumn,
      t,
      setAllColumnsEditable,
      isAllColumnsEditable,
      actions,
      renderActionButton,
      addAction,
      eventsChanged,
      apps,
      pages,
      rowSelectionsOptions,
      searchSortFilterOptions,
      paginationOptions,
      layoutPropertyChanged,
      additionalActions,
    ]
  );

  return <Accordion items={accordionItems} />;
};
