import { useCallback } from 'react';
import { computeActionName } from '@/_helpers/utils';
import { useAppDataStore } from '@/_stores/appDataStore';

export const useActionButtonManager = ({ component, paramUpdated }) => {
  const actions = component?.component?.definition?.properties?.actions;
  const actionValues = actions?.value || [];

  // Delete events helper
  const deleteEvents = useCallback(async (ref, eventTarget) => {
    const events = useAppDataStore.getState().events.filter((event) => event.target === eventTarget);
    const toDelete = events?.filter((e) => e.event?.ref === ref.ref);

    return Promise.all(
      toDelete?.map((e) => useAppDataStore.getState().actions.deleteAppVersionEventHandler(e.id)) || []
    );
  }, []);

  // Add new action
  const addAction = useCallback(() => {
    const newAction = {
      name: computeActionName(actions),
      buttonText: 'Button',
      backgroundColor: 'var(--cc-surface2-surface)',
      textColor: 'var(--cc-primary-text)',
      events: [],
    };
    paramUpdated({ name: 'actions' }, 'value', [...actionValues, newAction], 'properties', true);
  }, [actions, actionValues, paramUpdated]);

  // Remove action by index
  const removeAction = useCallback(
    (index, ref) => {
      const newValue = [...actionValues];
      newValue.splice(index, 1);
      paramUpdated({ name: 'actions' }, 'value', newValue, 'properties', true);
      deleteEvents(ref, 'table_action');
    },
    [actionValues, paramUpdated, deleteEvents]
  );

  // Update action property
  const updateActionProperty = useCallback(
    (index, property, value) => {
      const newActions = [...actionValues];
      newActions[index] = { ...newActions[index], [property]: value };
      paramUpdated({ name: 'actions' }, 'value', newActions, 'properties', true);
    },
    [actionValues, paramUpdated]
  );

  // Update action events
  const updateActionEvents = useCallback(
    (index, events) => {
      const newActions = [...actionValues];
      newActions[index] = { ...newActions[index], events };
      paramUpdated({ name: 'actions' }, 'value', newActions, 'properties', true);
    },
    [actionValues, paramUpdated]
  );

  // Update action event (legacy format)
  const updateActionEvent = useCallback(
    (event, value, extraData) => {
      const index = extraData.index;
      const newActions = [...actionValues];
      newActions[index] = {
        ...newActions[index],
        [event.name]: { actionId: value },
      };
      paramUpdated({ name: 'actions' }, 'value', newActions, 'properties', true);
    },
    [actionValues, paramUpdated]
  );

  // Update action event option
  const updateActionEventOption = useCallback(
    (event, option, value, extraData) => {
      const index = extraData.index;
      const newActions = [...actionValues];
      const options = newActions[index][event.name]?.options || {};
      newActions[index] = {
        ...newActions[index],
        [event.name]: {
          ...newActions[index][event.name],
          options: { ...options, [option]: value },
        },
      };
      paramUpdated({ name: 'actions' }, 'value', newActions, 'properties', true);
    },
    [actionValues, paramUpdated]
  );

  return {
    actions: actionValues,
    addAction,
    removeAction,
    updateActionProperty,
    updateActionEvents,
    updateActionEvent,
    updateActionEventOption,
  };
};
import { v4 as uuidv4 } from 'uuid';
import useStore from '@/AppBuilder/_stores/store';

export const DEFAULT_BUTTON = {
  buttonLabel: 'Button',
  buttonTooltip: '',
  disableButton: false,
  loadingState: false,
  buttonVisibility: true,
  buttonType: 'solid',
  buttonBackgroundColor: 'var(--cc-primary-brand)',
  buttonLabelColor: '#FFFFFF',
  buttonBorderColor: 'var(--cc-primary-brand)',
  buttonBorderRadius: '6',
  buttonLoaderColor: 'var(--cc-surface1-surface)',
  buttonIconName: 'IconHome2',
  buttonIconVisibility: false,
  buttonIconColor: 'var(--cc-default-icon)',
  buttonIconAlignment: 'left',
};

export const useButtonManager = ({ column, index, onColumnItemChange }) => {
  const addButton = () => {
    const newButton = { ...DEFAULT_BUTTON, id: uuidv4() };
    const updatedButtons = [...(column.buttons || []), newButton];
    onColumnItemChange(index, 'buttons', updatedButtons);
    return newButton.id;
  };

  const removeButton = (buttonId) => {
    const updatedButtons = (column.buttons || []).filter((b) => b.id !== buttonId);
    onColumnItemChange(index, 'buttons', updatedButtons);

    // Clean up events for this button
    const columnKey = column.key || column.name;
    const ref = `${columnKey}::${buttonId}`;
    const { getModuleEvents, deleteAppVersionEventHandler } = useStore.getState().eventsSlice;
    const events = getModuleEvents('canvas').filter((e) => e.target === 'table_column' && e.event?.ref === ref);
    Promise.all(events.map((e) => deleteAppVersionEventHandler(e.id))).catch((err) => {
      console.error('[useButtonManager] Failed to delete event handlers for button', buttonId, err);
    });
  };

  const updateButtonProperty = (buttonId, property, value) => {
    const updatedButtons = (column.buttons || []).map((b) => (b.id === buttonId ? { ...b, [property]: value } : b));
    onColumnItemChange(index, 'buttons', updatedButtons);
  };

  const updateButtonProperties = (buttonId, updates) => {
    const updatedButtons = (column.buttons || []).map((b) => (b.id === buttonId ? { ...b, ...updates } : b));
    onColumnItemChange(index, 'buttons', updatedButtons);
  };

  const reorderButtons = (reorderedButtons) => {
    onColumnItemChange(index, 'buttons', reorderedButtons);
  };

  const duplicateButton = (buttonId) => {
    const button = (column.buttons || []).find((b) => b.id === buttonId);
    if (!button) return null;
    const newButton = { ...button, id: uuidv4() };
    const updatedButtons = [...(column.buttons || []), newButton];
    onColumnItemChange(index, 'buttons', updatedButtons);
    return newButton.id;
  };

  const getButton = (buttonId) => {
    return (column.buttons || []).find((b) => b.id === buttonId);
  };

  return {
    addButton,
    removeButton,
    duplicateButton,
    updateButtonProperty,
    updateButtonProperties,
    reorderButtons,
    getButton,
  };
};
import { useCallback } from 'react';
import { useListItemManager } from '../../shared/hooks';
import { useAppDataStore } from '@/_stores/appDataStore';
import { DEFAULT_SELECT_COLUMN_OPTIONS } from '../utils';

/**
 * Hook for managing Table columns
 * Wraps the generic useListItemManager with column-specific configuration
 */
export const useColumnManager = ({ component, paramUpdated, currentState }) => {
  // Delete events helper
  const deleteEvents = useCallback(async (ref, eventTarget) => {
    const events = useAppDataStore.getState().events.filter((event) => event.target === eventTarget);
    const toDelete = events?.filter((e) => e.event?.ref === ref.ref);

    return Promise.all(
      toDelete?.map((e) => useAppDataStore.getState().actions.deleteAppVersionEventHandler(e.id)) || []
    );
  }, []);

  // Handle column-specific property changes
  const handlePropertyChange = (column, property, value) => {
    let modifiedColumn = { ...column };
    // Handle select/multiselect/tags — seed defaults like datepicker init
    if (property === 'columnType' && (value === 'select' || value === 'newMultiSelect' || value === 'tagsV2')) {
      if (modifiedColumn.options?.length > 0) {
        modifiedColumn.options = modifiedColumn.options.map((opt) => {
          const { makeDefaultOption, ...rest } = opt;
          return rest;
        });
      } else {
        modifiedColumn.options = DEFAULT_SELECT_COLUMN_OPTIONS.map((opt) => ({ ...opt }));
      }
      modifiedColumn.defaultOptionsList = [];
    }

    if (property === 'columnType' && value === 'tagsV2') {
      modifiedColumn = {
        ...modifiedColumn,
        sortTags: 'none',
        allowMultipleSelection: true,
        autoAssignColors: true,
      };
    }

    // Handle datepicker initialization
    if (property === 'columnType' && value === 'datepicker') {
      modifiedColumn = {
        ...modifiedColumn,
        isTimeChecked: false,
        dateFormat: 'DD/MM/YYYY',
        parseDateFormat: 'DD/MM/YYYY',
        isDateSelectionEnabled: true,
      };
    }

    // Handle button column initialization — starts with empty buttons array
    if (property === 'columnType' && value === 'button') {
      modifiedColumn = {
        ...modifiedColumn,
        columnVisibility: true,
        horizontalAlignment: 'left',
        pinPosition: modifiedColumn.pinPosition ?? 'unpinned',
        buttons: [],
      };
    }

    return modifiedColumn;
  };

  // Handle column removal (deletion history + event cleanup)
  const handleRemove = useCallback(
    async (removedColumns, index, ref) => {
      // Update column deletion history
      const existingColumnDeletionHistory =
        component.component.definition.properties.columnDeletionHistory?.value ?? [];
      const newColumnDeletionHistory = [
        ...existingColumnDeletionHistory,
        ...removedColumns.map((column) => column.key || column.name),
      ];
      await paramUpdated({ name: 'columnDeletionHistory' }, 'value', newColumnDeletionHistory, 'properties', true);

      // Delete associated events
      if (ref) {
        await deleteEvents({ ref }, 'table_column');
      }

      // Clean up events for all buttons in removed button columns
      for (const col of removedColumns) {
        if (col.columnType === 'button' && col.buttons) {
          const columnKey = col.key || col.name;
          for (const btn of col.buttons) {
            await deleteEvents({ ref: `${columnKey}::${btn.id}` }, 'table_column');
          }
        }
      }
    },
    [component, paramUpdated, deleteEvents]
  );

  const listManager = useListItemManager({
    component,
    paramUpdated,
    currentState,
    config: {
      propertyName: 'columns',
      typeProp: 'columnType',
      nonEditableTypes: ['link', 'image'],
      namePrefix: 'new_column',
      defaultItemProps: {
        includeKey: true,
        pinPosition: 'unpinned',
      },
      onPropertyChange: handlePropertyChange,
      onRemove: handleRemove,
    },
  });

  // Return with renamed properties to maintain API compatibility
  return {
    columns: listManager.items,
    filteredColumns: listManager.filteredItems,
    isAllColumnsEditable: listManager.isAllEditable,
    addColumn: listManager.addItem,
    removeColumn: listManager.removeItem,
    duplicateColumn: listManager.duplicateItem,
    reorderColumns: listManager.reorderItems,
    updateColumnProperty: listManager.updateProperty,
    updateColumnEvents: listManager.updateEvents,
    setAllColumnsEditable: listManager.setAllEditable,
    getPopoverFieldSource: listManager.getPopoverFieldSource,
    deleteEvents,
  };
};
