    layoutPropertyChanged,
    component,
    dataQueries,
    paramUpdated,
    currentState,
    eventsChanged,
    apps,
    allComponents,
    pages,
  } = restProps;

  // Use the custom hook for tree items management
  const {
    treeItems,
    hoveredItemIndex,
    setHoveredItemIndex,
    expandedItems,
    toggleItemExpanded,
    handleItemChange,
    handleDeleteItem,
    handleAddItem,
    handleAddNestedItem,
    handleReorder,
    getResolvedValue,
  } = useTreeSelectItemsManager(component, paramUpdated);

  // Property organization
  let properties = [];
  let additionalActions = [];
  let optionsProperties = [];
  let dataProperties = [];

  for (const [key] of Object.entries(componentMeta?.properties || {})) {
    const prop = componentMeta?.properties[key];
    if (prop?.section === 'additionalActions') {
      additionalActions.push(key);
    } else if (prop?.accordian === 'Options') {
      optionsProperties.push(key);
    } else if (prop?.accordian === 'Data') {
      dataProperties.push(key);
    } else {
      properties.push(key);
    }
