      custom: () => (
        <>
          {createRenderElement('advanced')}
          {isAdvanced && createRenderElement('data')}
          {!isAdvanced && _renderTreeItems()}
          {createRenderElement('allowIndependentSelection')}
          {isAdvanced && createRenderElement('checkedData')}
