import { useState, useEffect } from 'react';
import { shallow } from 'zustand/shallow';
import useStore from '@/AppBuilder/_stores/store';

export const useTreeSelectItemsManager = (component, paramUpdated) => {
  const [treeItems, setTreeItems] = useState([]);
  const [hoveredItemIndex, setHoveredItemIndex] = useState(null);
  const [expandedItems, setExpandedItems] = useState({});

  const getResolvedValue = useStore((state) => state.getResolvedValue, shallow);

  // Helper function to update tree items
  const updateTreeItems = (newItems) => {
    setTreeItems(newItems);
    paramUpdated({ name: 'options' }, 'value', newItems, 'properties', false);
  };

  // Helper function to construct tree items from component definition
  const constructTreeItems = () => {
    let itemsValue = component?.component?.definition?.properties?.options?.value;
    if (!Array.isArray(itemsValue)) {
      itemsValue = itemsValue ? Object.values(itemsValue) : [];
    }
    return itemsValue;
  };

  // Generate unique ID
  const generateUniqueId = (prefix = 'option') => {
    const existingIds = new Set();
    const collectIds = (items) => {
      items.forEach((item) => {
        if (item.value) existingIds.add(item.value);
        if (item.children) collectIds(item.children);
      });
    };
    collectIds(treeItems);

    let counter = 1;
    let newId = `${prefix}${counter}`;
    while (existingIds.has(newId)) {
      counter++;
      newId = `${prefix}${counter}`;
    }
    return newId;
  };

  // Generate new tree option item
  const generateNewItem = () => {
    const id = generateUniqueId('option');
    return {
      label: `Option ${id.replace('option', '')}`,
      value: id,
      visible: { value: true },
      disable: { value: false },
    };
  };

  // Helper to update a property that may be dot-notated (e.g. 'visible.value')
  const updateItemProperty = (item, propertyPath, value) => {
    if (propertyPath.includes('.')) {
      const [parentKey, childKey] = propertyPath.split('.');
      return {
        ...item,
        [parentKey]: {
          ...item[parentKey],
          [childKey]: value,
        },
      };
    }
    return {
      ...item,
      [propertyPath]: value,
    };
  };

  // Event handlers
  const handleItemChange = (propertyPath, value, itemValue, parentValue = null) => {
    const updateItems = (items) => {
      return items.map((item) => {
        if (parentValue && item.value === parentValue && item.children) {
          return {
            ...item,
            children: item.children.map((child) => {
              if (child.value === itemValue) {
                return updateItemProperty(child, propertyPath, value);
              }
              return child;
            }),
          };
        }
        if (item.value === itemValue) {
          return updateItemProperty(item, propertyPath, value);
        }
        if (item.children) {
          return { ...item, children: updateItems(item.children) };
        }
        return item;
      });
    };
    updateTreeItems(updateItems(treeItems));
  };

  const handleDeleteItem = (itemValue, parentValue = null) => {
    const deleteFromItems = (items) => {
      return items
        .filter((item) => {
          if (parentValue) return true;
          return item.value !== itemValue;
        })
        .map((item) => {
          if (parentValue && item.value === parentValue && item.children) {
            return {
              ...item,
              children: item.children.filter((child) => child.value !== itemValue),
            };
          }
          if (item.children) {
            return { ...item, children: deleteFromItems(item.children) };
          }
          return item;
        });
    };
    updateTreeItems(deleteFromItems(treeItems));
  };

  const handleAddItem = () => {
    const newItem = generateNewItem();
    updateTreeItems([...treeItems, newItem]);
  };

  const handleAddNestedItem = (parentValue) => {
    const newItem = generateNewItem();
    const addToParent = (items) => {
      return items.map((item) => {
        if (item.value === parentValue) {
          return {
            ...item,
            children: [...(item.children || []), newItem],
          };
        }
        if (item.children) {
          return { ...item, children: addToParent(item.children) };
        }
        return item;
      });
    };
    updateTreeItems(addToParent(treeItems));
  };

  // Handler for @dnd-kit reorder - receives the new tree structure
  const handleReorder = (newItems) => {
    const cleanItems = cleanupDndProperties(newItems);
    updateTreeItems(cleanItems);
  };

  // Remove temporary properties added by @dnd-kit
  const cleanupDndProperties = (items) => {
    return items.map((item) => {
      const { parentId, depth, index, ...cleanItem } = item;

      if (cleanItem.children && cleanItem.children.length > 0) {
        cleanItem.children = cleanupDndProperties(cleanItem.children);
      } else if (cleanItem.children && cleanItem.children.length === 0) {
        delete cleanItem.children;
      }

      return cleanItem;
    });
  };

  const toggleItemExpanded = (itemValue) => {
    setExpandedItems((prev) => ({
      ...prev,
      [itemValue]: prev[itemValue] === false ? true : false,
    }));
  };

  // Side effects
  useEffect(() => {
    const items = constructTreeItems();
    setTreeItems(items);
    // Initialize expanded state for items with children
    const initialExpanded = {};
    const initExpand = (itemList) => {
      itemList.forEach((item) => {
        if (item.children && item.children.length > 0) {
          initialExpanded[item.value] = true;
          initExpand(item.children);
        }
      });
    };
    initExpand(items);
    setExpandedItems(initialExpanded);
  }, [component?.id]);

  return {
    treeItems,
    hoveredItemIndex,
    setHoveredItemIndex,
    expandedItems,
    toggleItemExpanded,
    handleItemChange,
    handleDeleteItem,
    handleAddItem,
    handleAddNestedItem,
    handleReorder,
    getResolvedValue,
  };
};
import { useState, useEffect, useCallback, useMemo } from 'react';
import { resolveReferences } from '@/_helpers/utils';
import { v4 as uuidv4 } from 'uuid';
import { generateUniqueName, reorderArray, duplicateWithNewId, checkAllEditable, getPopoverSource } from '../utils';
import useStore from '@/AppBuilder/_stores/store';

/**
 * Generic hook for managing list items (columns, fields, etc.)
 * @param {Object} params
 * @param {Object} params.component - Component definition
 * @param {Function} params.paramUpdated - Callback to update component params
 * @param {Object} params.currentState - Current app state
 * @param {Object} params.config - Configuration for the hook
 * @param {string} params.config.propertyName - Property name in component definition ('columns' | 'fields')
 * @param {string} params.config.typeProp - Property name for item type ('columnType' | 'fieldType')
 * @param {Array} params.config.nonEditableTypes - Types that cannot be editable (default: ['link', 'image'])
 * @param {string} params.config.namePrefix - Prefix for new item names (default: 'new_item')
 * @param {Object} params.config.defaultItemProps - Additional default properties for new items
 * @param {Function} params.config.onPropertyChange - Callback before property change (item, property, value) => modifiedItem
 * @param {Function} params.config.onRemove - Callback after item removal (removedItems, index) => Promise
 * @param {Function} params.config.onRemoveUpdates - Properties saved with the removal (removedItems, index) => [{ name, value }]
 */
export const useListItemManager = ({ component, paramUpdated, currentState, config }) => {
  const {
    propertyName,
    typeProp,
    nonEditableTypes = ['link', 'image'],
    namePrefix = 'new_item',
    defaultItemProps = {},
    onPropertyChange,
    onRemove,
    onRemoveUpdates,
  } = config;

  const setComponentProperty = useStore((state) => state.setComponentProperty);
  const saveComponentPropertyChangesBatch = useStore((state) => state.saveComponentPropertyChangesBatch);
  const [isAllEditable, setIsAllEditable] = useState(false);

  // Get items from component definition - wrapped in useMemo to avoid dependency issues
  const itemsProperty = component?.component?.definition?.properties?.[propertyName];
  const items = useMemo(() => itemsProperty?.value || [], [itemsProperty?.value]);

  // Check if all items are editable
  const checkIfAllEditable = useCallback(
    (comp) => {
      const itemList = comp?.component?.definition?.properties?.[propertyName]?.value || [];
      return checkAllEditable(itemList, typeProp, nonEditableTypes, currentState);
    },
    [propertyName, typeProp, nonEditableTypes, currentState]
  );

  // Sync isAllEditable state with items changes.
  // Skip when list is empty so the user's manual toggle choice persists
  // (every() returns true on [], which would otherwise force the toggle on
  // and block toggling it off).
  useEffect(() => {
    if (items.length === 0) return;
    setIsAllEditable(checkIfAllEditable(component));
  }, [component, checkIfAllEditable, items.length]);

  // Add new item
  const addItem = useCallback(() => {
    const newName = generateUniqueName(items, namePrefix);
    const newItem = {
      name: newName,
      id: uuidv4(),
      isEditable: isAllEditable,
      fxActiveFields: [],
      [typeProp]: 'string',
      ...defaultItemProps,
      ...(defaultItemProps.includeKey ? { key: newName } : {}),
    };
    // Remove the helper flag
    delete newItem.includeKey;

    paramUpdated({ name: propertyName }, 'value', [...items, newItem], 'properties', true);
  }, [items, namePrefix, isAllEditable, typeProp, defaultItemProps, paramUpdated, propertyName]);

  // Remove item by index
  const removeItem = useCallback(
    async (index, ...args) => {
      try {
        const newValue = [...items];
        const removedItems = newValue.splice(index, 1);
        const bookkeepingUpdates = onRemoveUpdates?.(removedItems, index) ?? [];

        if (bookkeepingUpdates.length > 0) {
          // Saved and broadcast as one unit - separate ones can be applied out of order
          const batch = [{ name: propertyName, value: newValue }, ...bookkeepingUpdates].map(({ name, value }) => ({
            property: name,
            value,
            paramType: 'properties',
            attr: 'value',
          }));

          for (const { property, value, paramType, attr } of batch) {
            setComponentProperty(component.id, property, value, paramType, attr, false, 'canvas', {
              saveAfterAction: false,
            });
          }

          saveComponentPropertyChangesBatch(component.id, batch);
        } else {
          await paramUpdated({ name: propertyName }, 'value', newValue, 'properties', true);
        }

        // Call custom onRemove callback if provided
        if (onRemove) {
          await onRemove(removedItems, index, ...args);
        }
      } catch (error) {
        console.error(`Error removing ${propertyName}:`, error);
      }
    },
    [
      items,
      paramUpdated,
      propertyName,
      onRemove,
      onRemoveUpdates,
      setComponentProperty,
      saveComponentPropertyChangesBatch,
      component.id,
    ]
  );

  // Duplicate item by index
  const duplicateItem = useCallback(
    (index) => {
      const duplicated = duplicateWithNewId(items[index]);
      paramUpdated({ name: propertyName }, 'value', [...items, duplicated], 'properties', true);
    },
    [items, paramUpdated, propertyName]
  );

  // Reorder items (for drag & drop)
  const reorderItems = useCallback(
    (startIndex, endIndex) => {
      const reordered = reorderArray(items, startIndex, endIndex);
      paramUpdated({ name: propertyName }, 'value', reordered, 'properties', true);
    },
    [items, paramUpdated, propertyName]
  );

  // Update a single item property
  const updateProperty = useCallback(
    (index, property, value) => {
      let newItems = [...items];
      let item = { ...newItems[index] };

      // Apply custom property change logic if provided
      if (onPropertyChange) {
        item = onPropertyChange(item, property, value) || item;
      }

      item[property] = value;
      newItems[index] = item;

      // Handle non-editable types
      if (nonEditableTypes.includes(newItems[index][typeProp])) {
        newItems[index].isEditable = '{{false}}';
      }

      // Sync isEditable when type changes
      if (property === typeProp && !nonEditableTypes.includes(value) && isAllEditable) {
        newItems[index].isEditable = '{{true}}';
      }
      paramUpdated({ name: propertyName }, 'value', newItems, 'properties', true);

      // Update isAllEditable state based on individual changes
      if (property === 'isEditable') {
        const resolvedValue = resolveReferences(value);
        if (!resolvedValue && isAllEditable) {
          setIsAllEditable(false);
        } else if (resolvedValue && !isAllEditable) {
          const allEditable = newItems
            .filter((i) => !nonEditableTypes.includes(i[typeProp]))
            .every((i) => resolveReferences(i.isEditable));
          if (allEditable) {
            setIsAllEditable(true);
          }
        }
      }
    },
    [items, paramUpdated, propertyName, typeProp, nonEditableTypes, isAllEditable, onPropertyChange]
  );

  // Update item events
  const updateEvents = useCallback(
    (itemId, events) => {
      const newItems = items.map((item) => (item.id === itemId ? { ...item, events } : item));
      paramUpdated({ name: propertyName }, 'value', newItems, 'properties');
    },
    [items, paramUpdated, propertyName]
  );

  // Toggle all items editable
  const setAllEditable = useCallback(
    (value) => {
      const newItems = items
        .filter((item) => item)
        .map((item) => ({
          ...item,
          isEditable: !nonEditableTypes.includes(item[typeProp]) ? value : '{{false}}',
        }));

      paramUpdated({ name: propertyName }, 'value', newItems, 'properties', true);
      setIsAllEditable(resolveReferences(value));
    },
    [items, paramUpdated, propertyName, typeProp, nonEditableTypes]
  );

  // Get popover field source
  const getPopoverFieldSource = useCallback(
    (itemName, fieldName) => getPopoverSource(component.component.name, itemName, fieldName),
    [component]
  );

  // Memoize filtered items
  const filteredItems = useMemo(() => items.filter((item) => item), [items]);

  return {
    items,
    filteredItems,
    isAllEditable,
    addItem,
    removeItem,
    duplicateItem,
    reorderItems,
    updateProperty,
    updateEvents,
    setAllEditable,
    getPopoverFieldSource,
  };
};
import { useState, useCallback } from 'react';

export const usePopoverState = () => {
  const [activeIndex, setActiveIndex] = useState(null);
  const [rootCloseBlockers, setRootCloseBlockers] = useState([]);

  const openPopover = useCallback((index) => {
    setActiveIndex(index);
  }, []);

  const closePopover = useCallback(() => {
    document.activeElement?.blur();
    setActiveIndex(null);
  }, []);

  const togglePopover = useCallback((index, isOpen) => {
    if (isOpen) {
      setActiveIndex(index);
    } else {
      document.activeElement?.blur();
      setActiveIndex(null);
    }
  }, []);

  const blockRootClose = useCallback((key) => {
    setRootCloseBlockers((prev) => [...prev, key]);
  }, []);

  const unblockRootClose = useCallback((key) => {
    setRootCloseBlockers((prev) => prev.filter((b) => b !== key));
  }, []);

  const setRootCloseBlocker = useCallback((key, isBlocking) => {
    if (isBlocking) {
      setRootCloseBlockers((prev) => [...prev, key]);
    } else {
      setRootCloseBlockers((prev) => prev.filter((b) => b !== key));
    }
  }, []);

  return {
    activeIndex,
    isRootCloseEnabled: rootCloseBlockers.length === 0,
    openPopover,
    closePopover,
    togglePopover,
    blockRootClose,
    unblockRootClose,
    setRootCloseBlocker,
  };
};
import { v4 as uuidv4 } from 'uuid';
import { resolveReferences } from '@/_helpers/utils';

/**
 * Generate a unique name for a new item
 * @param {Array} items - Existing items
 * @param {string} prefix - Name prefix (e.g., 'new_column', 'new_field')
 * @returns {string} Unique name
 */
export const generateUniqueName = (items, prefix) => {
  let found = false;
  let currentNumber = 1;
  let name = '';

  while (!found) {
    name = `${prefix}${currentNumber}`;
    if (!items.find((item) => item.name === name)) {
      found = true;
    }
    currentNumber += 1;
  }

  return name;
};

/**
 * Reorder array by moving item from startIndex to endIndex
 * @param {Array} array - Array to reorder
 * @param {number} startIndex - Source index
 * @param {number} endIndex - Destination index
 * @returns {Array} New reordered array
 */
export const reorderArray = (array, startIndex, endIndex) => {
  const result = [...array];
  const [removed] = result.splice(startIndex, 1);
  result.splice(endIndex, 0, removed);
  return result;
};

/**
 * Duplicate an item with a new UUID
 * @param {Object} item - Item to duplicate
 * @returns {Object} Duplicated item with new id
 */
export const duplicateWithNewId = (item) => ({
  ...item,
  id: uuidv4(),
});

/**
 * Check if all items are editable
 * @param {Array} items - Items to check
 * @param {string} typeProp - Property name for item type (e.g., 'columnType', 'fieldType')
 * @param {Array} nonEditableTypes - Types that cannot be editable
 * @param {Object} currentState - Current app state for resolving references
 * @returns {boolean}
 */
export const checkAllEditable = (items, typeProp, nonEditableTypes, currentState) => {
  const editableItems = items.filter((item) => item && !nonEditableTypes.includes(item[typeProp]));
  return editableItems.every((item) => resolveReferences(item.isEditable, currentState));
};

/**
 * Get draggable item style
 * @param {boolean} isDragging - Whether item is being dragged
 * @param {Object} draggableStyle - Style from react-beautiful-dnd
 * @returns {Object} Combined style
 */
export const getDraggableStyle = (isDragging, draggableStyle) => ({
  userSelect: 'none',
  ...draggableStyle,
});

/**
 * Get popover field source string
 * @param {string} componentName - Component name
 * @param {string} itemName - Item name (column/field name)
 * @param {string} fieldName - Field name within the item
 * @returns {string} Source string
 */
export const getPopoverSource = (componentName, itemName, fieldName) =>
  `component/${componentName}/${itemName ?? 'default'}::${fieldName}`;
