  const styleOptions = [
    { label: 'Text and icon', value: 'texticon' },
    ...(position == 'side' || position == 'top' ? [{ label: 'Text only', value: 'text' }] : []),
    ...(position !== 'top' ? [{ label: 'Icon only', value: 'icon' }] : []),
