  const { wsCurrentBranch, wsActions, isGitSyncConfigured } = useWorkspaceBranchesStore((state) => ({
    wsCurrentBranch: state.currentBranch,
    wsActions: state.actions,
    isGitSyncConfigured: state.isGitSyncConfigured,
  }));
  const featureAccess = useLicenseStore((state) => state.featureAccess);
  // Git configured but license expired/invalid → the workspace is read-only, so hide the card's
  // options menu (rename, change icon, delete, …).
  const isGitLicenseLocked = isGitSyncConfigured && isGitSyncLicenseInvalid(featureAccess);
  const cardRef = useRef();
  const [popoverVisible, setPopoverVisible] = useState(false);
  const [isNameOverflowing, setIsNameOverflowing] = useState(false);
  const [syncIconHovered, setSyncIconHovered] = useState(false);
  const [pushModalOpen, setPushModalOpen] = useState(false);
  const [pushValidationError, setPushValidationError] = useState(null);
  const tooltipRef = useRef(null);

  const handlePushClick = async () => {
    try {
      const rt = appType === 'workflow' ? 'workflow' : appType === 'module' ? 'module' : 'app';
      const result = await gitSyncService.validatePush(app.id, rt);
      if (!result.valid) {
        setPushValidationError({
          errorType: result.errorType,
          resourceType: result.resourceType || rt,
          affectedResources: result.affectedResources || [],
        });
        return;
      }
    } catch {
      // validation endpoint unavailable — fall through to push modal
    }
    setPushModalOpen(true);
  };

  const handleEditClick = async (e) => {
    // When workspace branching is active, verify current branch still exists on remote
    if (wsCurrentBranch) {
      e.preventDefault();
      try {
        const existsOnRemote = await wsActions.checkBranchExistsOnRemote(wsCurrentBranch.name);
        if (!existsOnRemote) {
          toast.error(
            'Branch does not exist in git. Delete this branch and create a new one to continue to make changes.'
          );
          return;
        }
      } catch (_err) {
        // check failed (network error, etc.) — allow navigation
      }
      // Carry the dashboard's active branch into the editor so reload keeps the same branch.
      navigate(
        appendBranchName(
          getPrivateRoute('editor', { slug: isValidSlug(app.slug) ? app.slug : app.id }),
          wsCurrentBranch?.name
        )
      );
    }
    posthogHelper.captureEvent('click_edit_button_on_card', {
      workspace_id:
        authenticationService?.currentUserValue?.organization_id ||
        authenticationService?.currentSessionValue?.current_organization_id,
      app_id: app?.id,
      folder_id: currentFolder?.id,
    });
  };

  const onMenuToggle = useCallback(
    (status) => {
      setMenuOpen(!!status);
      !status && !isHovered && setFocused(false);
    },
    [isHovered]
  );

  const appActionModalCallBack = useCallback(
    (action) => {
      appActionModal(app, currentFolder, action);
      if (action === 'add-to-folder') {
        posthogHelper.captureEvent('click_add_to_folder_option', {
          workspace_id:
            authenticationService?.currentUserValue?.organization_id ||
            authenticationService?.currentSessionValue?.current_organization_id,
          app_id: app?.id,
        });
      }
    },
    [app, appActionModal, currentFolder]
  );

  const isValidSlug = (slug) => {
    const validate = validateName(slug, 'slug', true, false, false, false);
    return validate.status;
  };

  useEffect(() => {
    const checkOverflow = () => {
      if (tooltipRef.current) {
        setIsNameOverflowing(tooltipRef.current.scrollWidth > tooltipRef.current.clientWidth);
      }
    };

    checkOverflow();
    window.addEventListener('resize', checkOverflow);
    return () => window.removeEventListener('resize', checkOverflow);
  }, []);

  useEffect(() => {
    !isMenuOpen && setFocused(!!isHovered);
  }, [isHovered, isMenuOpen]);

  useEffect(() => {
    const callBackFunction = (entries) => {
      const [entry] = entries;
      setPopoverVisible(isMenuOpen && entry.isIntersecting);
    };

    const options = {
      root: null,
      rootMargin: '0px',
      threshold: 1.0,
    };

    const currentCardRef = cardRef.current;
    const observer = new IntersectionObserver(callBackFunction, options);
    if (currentCardRef) {
      observer.observe(currentCardRef);
    }

    return () => {
      if (currentCardRef) {
        observer.unobserve(currentCardRef);
      }
    };
  }, [isMenuOpen]);

  const updated_at = app?.editing_version?.updated_at || app?.updated_at;
  const updated = moment(updated_at).fromNow(true);
  const darkMode = localStorage.getItem('darkMode') === 'true';

  let AppIcon;
  try {
    AppIcon = <BulkIcon fill={'#3E63DD'} name={app?.icon || defaultIcon} />;
  } catch (e) {
    console.error('App icon not found', app.icon);
  }

  // Calculate released app access before LaunchButton definition
  const session = authenticationService.currentSessionValue;
  const appPerms = session?.app_group_permissions;

  // Backend resolves all folder-derived permissions into editable_apps_id, viewable_apps_id,
  // and appSpecificEnvironmentAccess at session time — no frontend folder checks needed.
  const environmentAccess = getEnvironmentAccessFromPermissions(appPerms, app.id);

  // Check if user is a builder based on role, not just editable apps
  const isBuilder = hasBuilderRole(session?.role ?? {});

  const hasNonReleasedPreviewAccess =
    environmentAccess.development || environmentAccess.staging || environmentAccess.production;

  // Builders need explicit released access. End users can launch if the app is released.
  const canAccessReleased = !isBuilder || environmentAccess.released;

  const LaunchButton =
    appType === 'workflow' ? (
      <div>
        <ToolTip
          message={t(
            'homePage.appCard.launchingWorkflowNotAvailable',
            'Launching workflows is not currently available'
          )}
        >
          <button
            type="button"
            className={cx(`launch-button tj-text-xsm tj-disabled-btn`)}
            disabled
            data-cy="launch-button"
          >
            <SolidIcon name="rightarrrow" width="14" fill="#4C5155" />
            {t('homePage.appCard.launch', 'Launch')}
          </button>
        </ToolTip>
      </div>
    ) : (
      <div>
        <ToolTip
          message={
            app?.current_version_id === null
              ? t('homePage.appCard.noDeployedVersion', 'App does not have a deployed version')
              : !canAccessReleased
                ? t('homePage.appCard.noReleasedAccess', 'You do not have permission to access released apps')
                : t('homePage.appCard.openInAppViewer', 'Open in app viewer')
          }
        >
          <button
            type="button"
            className={cx(
              ` launch-button tj-text-xsm ${
                app?.current_version_id === null || app?.is_maintenance_on || !canAccessReleased
                  ? 'tj-disabled-btn '
                  : 'tj-tertiary-btn'
              }`
            )}
            disabled={app?.current_version_id === null || app?.is_maintenance_on || !canAccessReleased}
            onClick={() => {
              if (app?.current_version_id && canAccessReleased) {
                window.open(urlJoin(getHostURL(), `/applications/${app.slug}`));
              } else {
                navigate(app?.current_version_id ? `/applications/${app.slug}` : '');
              }
            }}
            data-cy="launch-button"
          >
            <SolidIcon
              name="rightarrrow"
              width="14"
              fill={
                app?.current_version_id === null || app?.is_maintenance_on || !canAccessReleased
                  ? '#4C5155'
                  : darkMode
                    ? '#FDFDFE'
                    : '#11181C'
              }
            />

            {app?.is_maintenance_on
              ? t('homePage.appCard.maintenance', 'Maintenance')
              : t('homePage.appCard.launch', 'Launch')}
          </button>
        </ToolTip>
      </div>
    );

  const ViewButton = (
    <div>
      <button
        type="button"
        className="tj-primary-btn tj-text-xsm edit-button"
        style={{ color: darkMode ? '#FFFFFF' : '#FDFDFE' }}
        onClick={() => {
          const pageHandle = app.home_page_handle || 'home';
          const slugOrId = isValidSlug(app.slug) ? app.slug : app.id;

          // For preview, use first available environment from user's actual permissions.
          const defaultEnv = getDefaultEnvironment(environmentAccess, isBuilder, true);
          // Don't add env param if license is invalid or multi-environment feature is not available
          const queryParams = props.basicPlan ? {} : { env: defaultEnv };
          const previewQuery = queryString.stringify(queryParams);

          const previewUrl = `/applications/${slugOrId}/${pageHandle}${previewQuery ? `?${previewQuery}` : ''}`;

          window.open(previewUrl, '_blank');
        }}
        data-cy="preview-button"
      >
        {t('globals.preview', 'Preview')}
      </button>
    </div>
  );

  function AppNameDisplay({ tooltipRef }) {
    const AppName = (
      <h3
        ref={tooltipRef}
        className="app-card-name font-weight-500 tj-text-md"
        data-cy={`${app?.name?.toLowerCase().replace(/\s+/g, '-')}-title`}
      >
        {decodeEntities(app?.name)}
      </h3>
    );

    return isNameOverflowing ? (
      <ToolTip trigger={['hover']} message={app.name} maxWidth="210px" tooltipClassName="long-name-tooltip">
        {AppName}
      </ToolTip>
    ) : (
      AppName
    );
  }
  const isStub = app?.app_versions?.[0]?.is_stub;
  const isOnDefaultBranch = !!(wsCurrentBranch?.is_default || wsCurrentBranch?.isDefault);
  const isUnsynced = isGitSyncConfigured && wsCurrentBranch && isOnDefaultBranch && !app?.is_app_synced;

  // Draft version id an unsynced app would push — same rule used for `app` below, applied to
  // every sibling so the "Select app" picker in PushAppsModal can push whichever one is chosen.
  const getPushableVersionId = (a) =>
    a.app_versions?.find(
      (v) =>
        (v.status === 'DRAFT' || v.status === 'draft') && (v.versionType === 'version' || v.version_type === 'version')
    )?.id ?? a.editing_version?.id;

  const unsyncedAppsList = useMemo(
    () =>
      (props.siblingUnsyncedApps || []).map((a) => ({
        id: a.id,
        name: a.name,
        versionId: getPushableVersionId(a),
      })),
    // eslint-disable-next-line react-hooks/exhaustive-deps
    [props.siblingUnsyncedApps]
  );

  return (
    <>
      <ToolTip
        message="Modules are not available on your current plan."
        placement="bottom"
        show={appType === 'module' && !props.moduleEnabled}
      >
        <div className="card homepage-app-card card--clickable" ref={cardRef}>
          <div
            className={appType === 'module' && !props.moduleEnabled ? 'disabled-module' : ''}
            key={app?.id}
            ref={hoverRef}
            data-cy={`${app?.name?.toLowerCase().replace(/\s+/g, '-')}-card`}
          >
            <div className="row home-app-card-header">
              <div className="col-12 d-flex justify-content-between">
                <div>
                  <div className="app-icon-main">
                    <div className="app-icon d-flex" data-cy={`app-card-${app?.icon}-icon`}>
                      {AppIcon && AppIcon}
                    </div>
                  </div>
                </div>
                <div style={{ display: 'flex', alignItems: 'flex-start', gap: '2px' }}>
                  {/* On hover: refresh icon appears to the left of the 3-dots */}
                  {isUnsynced && focused && (
                    <ToolTip message="Click to push app to git" placement="top">
                      <div
                        onMouseEnter={() => setSyncIconHovered(true)}
                        onMouseLeave={() => setSyncIconHovered(false)}
                        onClick={handlePushClick}
                        style={{
                          width: '28px',
                          height: '28px',
                          display: 'flex',
                          alignItems: 'center',
                          justifyContent: 'center',
                          borderRadius: '6px',
                          backgroundColor: syncIconHovered ? '#FFEEF0' : 'transparent',
                          transition: 'background-color 0.15s',
                          cursor: 'pointer',
                        }}
                        data-cy="unsynced-badge"
                      >
                        <SolidIcon name="refresh" width="16" fill="#E54D2E" />
                      </div>
                    </ToolTip>
                  )}
                  {/* Right slot: refresh icon when not hovering (unsynced), 3-dots when hovering */}
                  {isUnsynced && !focused ? (
                    <ToolTip message="App not synced in remote git" placement="top">
                      <div
                        onClick={handlePushClick}
                        style={{
                          width: '28px',
                          height: '28px',
                          display: 'flex',
                          alignItems: 'center',
                          justifyContent: 'center',
                          borderRadius: '6px',
                          cursor: 'pointer',
                        }}
                        data-cy="unsynced-badge-idle"
                      >
                        <SolidIcon name="refresh" width="16" fill="#E54D2E" />
                      </div>
                    </ToolTip>
                  ) : (
                    <div visible={focused ? true : undefined}>
                      {(canDeleteApp(app) || canUpdateApp(app)) && !isGitLicenseLocked && (
                        <AppMenu
                          appId={app?.id}
                          appUserId={app?.user_id}
                          onMenuOpen={onMenuToggle}
                          openAppActionModal={appActionModalCallBack}
                          canCreateApp={canCreateApp()}
                          canDeleteApp={canDeleteApp(app)}
                          canUpdateApp={canUpdateApp(app)}
                          deleteApp={() => deleteApp(app)}
                          exportApp={() => {
                            if (isStub) {
                              toast.error(
                                appType === 'workflow'
                                  ? 'Workflow contents are still syncing from Git. Open the app to finish loading, then try again.'
                                  : 'App contents are still syncing from Git. Open the app to finish loading, then try again.',
                                { position: 'top-center' }
                              );
                              return;
                            }
                            exportApp(app);
                          }}
                          isMenuOpen={setMenuOpen}
                          popoverVisible={popoverVisible}
                          setMenuOpen={setMenuOpen}
                          darkMode={darkMode}
                          currentFolder={currentFolder}
                          appType={appType}
                          appCreationMode={app?.creation_mode || app?.creationMode}
                          ownedFolders={ownedFolders}
                          isUnsynced={isUnsynced}
                        />
                      )}
                    </div>
                  )}
                </div>
              </div>
            </div>
            <div>
              <AppNameDisplay tooltipRef={tooltipRef} />
            </div>
            <div className="app-creation-time-container" style={{ marginBottom: '12px' }}>
              {canUpdate && (
                <div className="app-creation-time tj-text-xsm" data-cy="app-creation-details">
                  <ToolTip message={app.created_at && moment(app.created_at).format('dddd, MMMM Do YYYY, h:mm:ss a')}>
                    <span>{updated === 'just now' ? `Edited ${updated}` : `Edited ${updated} ago`}</span>
                  </ToolTip>
                </div>
              )}
            </div>
            <div className="appcard-buttons-wrap">
              {canUpdate && (
                <div>
                  <ToolTip message={`Open in ${appType !== 'workflow' ? 'app builder' : 'workflow editor'}`}>
                    <Link
                      to={getPrivateRoute('editor', {
                        slug: isValidSlug(app.slug) ? app.slug : app.id,
                      })}
                      onClick={handleEditClick}
                    >
                      <button
                        type="button"
                        className="tj-primary-btn tj-text-xsm edit-button"
                        style={{ color: darkMode ? '#FFFFFF' : '#FDFDFE' }}
                        data-cy="edit-button"
                      >
                        <SolidIcon name="editrectangle" width="14" fill={darkMode ? '#FFFFFF' : '#FDFDFE'} />
                        &nbsp;{t('globals.edit', 'Edit')}
                      </button>
                    </Link>
                  </ToolTip>
                </div>
              )}
              {!canUpdate && canView && appType === 'module' && (
                <div>
                  <ToolTip message="Open in app builder">
                    <Link
                      // reloadDocument forces a hard navigation, discarding the in-memory active-branch
                      // cache — carry the branch in the URL itself (same fix as handleEditClick) so the
                      // module resolves on the branch its current version actually lives on, not just
                      // the default branch.
                      to={appendBranchName(
                        getPrivateRoute('editor', {
                          slug: isValidSlug(app.slug) ? app.slug : app.id,
                        }),
                        wsCurrentBranch?.name
                      )}
                      reloadDocument
                    >
                      <button
                        type="button"
                        className="tj-primary-btn tj-text-xsm edit-button"
                        style={{ color: darkMode ? '#FFFFFF' : '#FDFDFE' }}
                        data-cy="view-button"
                      >
                        <SolidIcon name="eye" width="14" fill={darkMode ? '#FFFFFF' : '#FDFDFE'} />
                        &nbsp;{t('globals.view', 'View')}
                      </button>
                    </Link>
                  </ToolTip>
                </div>
              )}
              {!canUpdate && canView && appType !== 'module' && hasNonReleasedPreviewAccess && ViewButton}
              {!isStub && appType !== 'module' && LaunchButton}
            </div>
          </div>
        </div>
      </ToolTip>
      {PushAppsModal && isUnsynced && (
        <PushAppsModal
          show={pushModalOpen}
          onClose={() => setPushModalOpen(false)}
          resourceType={appType === 'workflow' ? 'workflow' : appType === 'module' ? 'module' : 'app'}
          resourceName={app.name}
          appName={app.name}
          appGitId={app.id}
          versionId={getPushableVersionId(app)}
          appsList={unsyncedAppsList}
          onSuccess={() => {
            setPushModalOpen(false);
            props.refreshApps?.();
          }}
        />
      )}
      {pushValidationError && (
        <PushValidationErrorModal
          show={!!pushValidationError}
          onClose={() => setPushValidationError(null)}
          errorType={pushValidationError.errorType}
          resourceType={pushValidationError.resourceType}
          affectedResources={pushValidationError.affectedResources}
        />
      )}
    </>
  );
}
import React from 'react';
import AppCard from './AppCard';
import { useTranslation } from 'react-i18next';
import EmptyFoldersIllustration from '@assets/images/icons/no-queries-added.svg';
import Skeleton from 'react-loading-skeleton';

const AppList = (props) => {
  const { t } = useTranslation();
  return (
    <div className="app-list">
      {props.isLoading && (
        <>
          {Array.from(Array(2)).map((_, rowIndex) => (
            <div className="row skeleton-container mb-3 mt-3" key={rowIndex}>
              {Array.from(Array(3)).map((_, index) => (
                <div className="col" key={rowIndex * 3 + index}>
                  {rowIndex === 1 && index == 2 ? (
                    <></>
                  ) : (
                    <Skeleton count={1} height={166} width={272} className="mb-1" />
                  )}
                </div>
              ))}
            </div>
          ))}
        </>
      )}
      {!props.isLoading && props.meta.total_count > 0 && (
        <div className="">
          <div className="homepage-app-card-list-item-wrap">
            {/* Apps on the current page/folder view that haven't been pushed to git yet —
                handed to each card's PushAppsModal so the "Select app" picker can offer
                any of them, not just the one whose card was clicked. */}
            {(() => {
              const unsyncedApps = props.apps.filter((a) => !a.is_app_synced);
              return props.apps.map((app) => {
                return (
                  <div className="homepage-app-card-list-item" key={app.id}>
                    <AppCard
                      app={app}
                      key={app.id}
                      currentFolder={props.currentFolder}
                      canCreateApp={props.canCreateApp}
                      canDeleteApp={props.canDeleteApp}
                      canUpdateApp={props.canUpdateApp}
                      canViewApp={props.canViewApp}
                      deleteApp={props.deleteApp}
                      exportApp={props.exportApp}
                      appActionModal={props.appActionModal}
                      refreshApps={props.refreshApps}
                      appType={props.appType}
                      basicPlan={props?.basicPlan || false}
                      moduleEnabled={props?.moduleEnabled || false}
                      ownedFolders={props.ownedFolders}
                      siblingUnsyncedApps={unsyncedApps}
                    />
                  </div>
                );
              });
            })()}
          </div>
        </div>
      )}
      {!props.isLoading && props.apps?.length === 0 && (
        <div className="text-center d-block">
          <EmptyFoldersIllustration className="mb-4" data-cy="empty-folder-image" />
          <span
            className={`d-block text-center text-body ${props.darkMode && 'text-white-50'}`}
            data-cy="empty-folder-text"
          >
            {props.currentFolder?.count == 0 &&
              props.apps?.length == 0 &&
              props.appSearchKey == '' &&
              t('homePage.thisFolderIsEmpty', 'This folder is empty')}
          </span>
        </div>
      )}
    </div>
  );
};

export default AppList;
import React from 'react';
import OverlayTrigger from 'react-bootstrap/OverlayTrigger';
import Popover from 'react-bootstrap/Popover';
import { useTranslation } from 'react-i18next';
import { authenticationService } from '@/_services';
import { useWorkspaceBranchesStore } from '@/_stores/workspaceBranchesStore';
import { getFolderGroupPermissions } from './helper';
import { canEditModule } from '@/modules/Modules/helpers/modulePermissions';

export const AppMenu = function AppMenu({
  appId,
  appUserId,
  deleteApp,
  exportApp,
  canCreateApp,
  canDeleteApp,
  canUpdateApp,
  onMenuOpen,
  openAppActionModal,
  darkMode,
  currentFolder,
  popoverVisible,
  setMenuOpen,
  appType,
  ownedFolders,
  isUnsynced,
}) {
  const { t } = useTranslation();

  const currentSession = authenticationService.currentSessionValue;
  const currentUserId = currentSession?.current_user?.id;

  const { orgGitConfig, currentBranch, isInitialized } = useWorkspaceBranchesStore();
  const isBranchingEnabled =
    isInitialized && orgGitConfig && (orgGitConfig?.is_branching_enabled || orgGitConfig?.isBranchingEnabled);
  const isDefaultBranch = currentBranch?.is_default || currentBranch?.isDefault;
  // Unsynced apps are always mutable, even on master
  const isWorkspaceBranchLocked = !!(isBranchingEnabled && isDefaultBranch) && !isUnsynced;

  // ─── Ownership ────────────────────────────────────────────────────────────────
  const isAppOwner = !!(appUserId && currentUserId && appUserId === currentUserId);

  // ─── App-level edit access ────────────────────────────────────────────────────
  // Backend resolves folder-derived permissions into editable_apps_id/editable_workflows_id,
  // so canEditApp already covers apps/workflows in folders owned by or explicitly shared
  // with the user. Workflows and modules each have their own permission surface, separate
  // from apps — modules delegate to canEditModule so this stays in sync with HomePage's
  // canUserPerform and the module editor's own read-only gate.
  const canEditApp =
    appType === 'workflow'
      ? currentSession?.workflow_group_permissions?.is_all_editable ||
        currentSession?.workflow_group_permissions?.editable_workflows_id?.includes(appId)
      : appType === 'module'
        ? canEditModule(currentSession, appId, appUserId)
        : currentSession?.app_group_permissions?.is_all_editable ||
          currentSession?.app_group_permissions?.editable_apps_id?.includes(appId);

  const canModifyApp = canEditApp || isAppOwner;

  const folderGroupPermissions = getFolderGroupPermissions(currentSession, appType);

  const canEditAnyFolderViaGroup =
    folderGroupPermissions?.is_all_editable || folderGroupPermissions?.editable_folders_id?.length > 0;

  // canAddAppToFolder: user can modify the app AND has at least one folder available in the dropdown.
  const hasOwnedFolders = isAppOwner && Array.isArray(ownedFolders) && ownedFolders.length > 0;

  const canAddAppToFolder =
    !isWorkspaceBranchLocked &&
    canModifyApp &&
    (currentSession?.admin || currentSession?.super_admin || canEditAnyFolderViaGroup || hasOwnedFolders);

  // canRemoveFromFolder: only when inside a specific folder AND user has folder-edit access.
  const canRemoveFromFolder =
    !isWorkspaceBranchLocked &&
    !!currentFolder?.id &&
    canModifyApp &&
    (currentSession?.admin ||
      currentSession?.super_admin ||
      folderGroupPermissions?.is_all_editable ||
      folderGroupPermissions?.editable_folders_id?.includes(currentFolder.id) ||
      currentFolder?.created_by === currentUserId);

  const Field = ({ text, onClick, customClass }) => {
    const closeMenu = () => {
      document.body.click();
      onClick();
    };
    return (
      <div className={`field mb-3${customClass ? ` ${customClass}` : ''}`}>
        <span
          role="button"
          onClick={() => {
            closeMenu();
          }}
          data-cy={`${text.toLowerCase().replace(/\s+/g, '-')}-card-option`}
        >
          {text}
        </span>
      </div>
    );
  };

  return (
    <OverlayTrigger
      trigger="click"
      placement="top-start"
      rootClose
      onToggle={onMenuOpen}
      onExit={() => setMenuOpen(false)}
      show={popoverVisible}
      container={document.getElementsByClassName('home-page-content')[0]}
      overlay={
        <div>
          <Popover id="popover-app-menu" className={darkMode && 'dark-theme'} placement="bottom">
            <Popover.Body bsPrefix="popover-body">
              <div data-cy="card-options">
                {canUpdateApp && (
                  <Field
                    text={t(
                      'homePage.appCard.renameApp',
                      appType === 'workflow' ? 'Rename workflow' : appType === 'module' ? 'Rename module' : 'Rename app'
                    )}
