              }
            >
              {showUpdateForm
                ? t('homePage.foldersSection.editFolder', 'Edit Folder')
                : t('homePage.foldersSection.createFolder', 'Create folder')}
            </ButtonSolid>
          </div>
        </div>
      </Modal>
    </div>
  );
};
import React, { useState, useMemo } from 'react';
import Pagination from '@/_ui/Pagination';
import Skeleton from 'react-loading-skeleton';

const Footer = ({ darkMode, count, pageChanged, dataLoading, itemsPerPage = 9, appType }) => {
  const [pageCount, setPageCount] = useState(1);
  const totalPages = useMemo(() => {
    return Math.floor((count - 1) / itemsPerPage) + 1;
  }, [count, itemsPerPage]);

  const pageRange = `${(pageCount - 1) * itemsPerPage + 1} - ${
    pageCount * itemsPerPage > count ? count : pageCount * itemsPerPage
  }`;

  const handlePageCountChange = (value) => {
    setPageCount(value);
    pageChanged(value);
  };

  const gotoNextPage = (fromInput = false, value = null) => {
    if (fromInput && value) {
      return handlePageCountChange(value);
    }

    setPageCount((previous) => {
      const next = previous + 1;
      pageChanged(next);
      return next;
    });
  };

  const gotoPreviousPage = () => {
    setPageCount((previous) => {
      if (previous - 1 < 1) {
        pageChanged(previous);
        return previous;
      }
      pageChanged(previous - 1);
      return previous - 1;
    });
  };

  return (
    <div className="home-page-footer card-footer d-flex align-items-center jet-table-footer justify-content-center">
      <div className="table-footer row gx-0">
        <div className="col-5"></div>
        <div className="col d-flex align-items-center justify-content-end">
          <div className="col">
            <Pagination
              darkMode={darkMode}
              gotoNextPage={gotoNextPage}
              gotoPreviousPage={gotoPreviousPage}
              currentPage={pageCount}
              totalPage={totalPages}
              isDisabled={dataLoading}
            />
          </div>
          <div className="col-4 mx-2">
            {dataLoading ? (
              <Skeleton count={1} height={2} />
            ) : (
              <span className="animation-fade">
                {pageRange} of {count} {appType === 'module' ? 'modules' : 'apps'}
              </span>
            )}
          </div>
        </div>
      </div>
    </div>
  );
};

export default Footer;
import React, { useState, useEffect, forwardRef } from 'react';
import PropTypes from 'prop-types';
import cx from 'classnames';
import useDebounce from '@/_hooks/useDebounce';
import { useMounted } from '@/_hooks/use-mount';
import SolidIcon from '@/_ui/Icon/SolidIcons';
import './_styles/page-search-box.scss';

export const SearchBox = forwardRef(
  (
    {
      width = '200px',
      onSubmit,
      className,
      debounceDelay = 300,
      darkMode = false,
      placeholder = 'Search',
      customClass = '',
      dataCy = '',
      callBack,
      onClearCallback,
      autoFocus = false,
      showClearButton,
      initialValue = '',
      clearTextOnBlur = true,
    },
    ref
  ) => {
    const [searchText, setSearchText] = useState('');
    const debouncedSearchTerm = useDebounce(searchText, debounceDelay);
    const [isFocused, setFocussed] = useState(false);

    const handleChange = (e) => {
      setSearchText(e.target.value);
      callBack?.(e);
    };

    const clearSearchText = () => {
      setSearchText('');
      onClearCallback?.();
    };

    const handleClickOutside = (event) => {
      if (ref?.current && !ref.current.contains(event.target) && clearTextOnBlur) {
        clearSearchText();
        // Your function to be triggered
      }
    };

    const mounted = useMounted();

    useEffect(() => {
      document.addEventListener('mousedown', handleClickOutside);
      if (mounted) {
        onSubmit?.(debouncedSearchTerm);
      }
      return () => {
        // Cleanup event listener on component unmount
        document.removeEventListener('mousedown', handleClickOutside);
      };
      // eslint-disable-next-line react-hooks/exhaustive-deps
    }, [debouncedSearchTerm, onSubmit]);

    useEffect(() => {
      initialValue !== undefined && setSearchText(initialValue);
    }, [initialValue]);

    return (
      <div className={`ghost-search-box-wrapper ${customClass}`}>
        <div className="input-icon">
          {!isFocused && (
            <span className="input-icon-addon">
              <SolidIcon name="search" width="14" />
            </span>
          )}
          <input
            style={{ width }}
            type="text"
            value={searchText}
            onChange={handleChange}
            className={cx('form-control ghost-search', {
              'dark-theme-placeholder': darkMode,
              [className]: !!className,
            })}
            placeholder={placeholder}
            onFocus={() => setFocussed(true)}
            onBlur={() => setFocussed(false)}
            data-cy={`${dataCy}-search-bar`}
            autoFocus={autoFocus}
            ref={ref}
          />
          {searchText.length >= 0 ? (
            <span className="input-icon-addon end" onMouseDown={clearSearchText}>
              <div className="d-flex tj-common-search-input-clear-icon" title="clear">
                <SolidIcon name="remove" />
              </div>
            </span>
          ) : (
            ''
          )}
        </div>
      </div>
    );
  }
);

SearchBox.propTypes = {
  onSubmit: PropTypes.func.isRequired,
  debounceDelay: PropTypes.number,
  width: PropTypes.string,
};
