const LOG_FETCH_FAILED = Symbol('log fetch failed');

/** One migration's own log lines. `run` is a new object on every poll, so a running or failed log refetches each poll. */
const StepLog = ({ run, step }) => {
  const [log, setLog] = useState(null);
  const runId = run.id;
  const refresh = step.status === 'running' || log === LOG_FETCH_FAILED ? run : null;

  useEffect(() => {
    let cancelled = false;
    migrationsService
      .getLog(runId, step.name)
      .then((text) => !cancelled && setLog(text))
      .catch(() => !cancelled && setLog(LOG_FETCH_FAILED));
    return () => {
      cancelled = true;
    };
  }, [runId, step.name, refresh]);

  if (log === null) return <Skeleton className="tw-h-16 tw-w-full" />;
  if (log === LOG_FETCH_FAILED) {
    return (
      <p className="tw-m-0 tw-text-text-danger">
        Could not load the log for this migration. It retries on the next refresh.
      </p>
    );
  }
  return (
    <pre
      tabIndex={0}
      aria-label={`${step.name} log`}
      className="tw-m-0 tw-max-h-64 tw-overflow-auto tw-rounded-md tw-bg-background-surface-layer-02 tw-p-3 tw-font-code-regular tw-text-text-default"
    >
      {log || 'This migration logged nothing.'}
    </pre>
  );
};

