export default function ErrorPage({ darkMode }) {
  const params = useParams();
  const errorType = params?.errorType;
  const errorMsg = ERROR_MESSAGES[errorType];
  if (!errorMsg) redirectToDashboard();

  const searchParams = new URLSearchParams(location.search);
  const appSlug = searchParams.get('appSlug');
  const workspaceName = searchParams.get('workspaceName');

  const resolvedErrorMsg = errorMsg
    ? {
        ...errorMsg,
        message: workspaceName ? errorMsg.message?.replace('{workspaceName}', workspaceName) : errorMsg.message,
      }
    : errorMsg;

  const [isLoading, setLoading] = React.useState(true);
  const [isValidSession, setValidSession] = React.useState(null);
  const [appDetails, setAppDetails] = React.useState(null);

  useEffect(() => {
    sessionService
      .validateSession()
      .then(({ current_organization_id, ...restSessionData }) => {
        // Populate the org context before calling any org-scoped endpoint below (e.g.
        // getRestrictedAccessInfo) — otherwise authHeader() has no tj-workspace-id to send yet
        // on a fresh page load, and the request 401s even for a fully valid session.
        authenticationService.updateCurrentSession({ current_organization_id, ...restSessionData });
        setValidSession(true);
        if (errorType === ERROR_TYPES.RESTRICTED && appSlug) {
          appService
            .getRestrictedAccessInfo(appSlug)
            .then((details) => setAppDetails(details))
            .catch(() => {});
        }
      })
      .catch(() => {
        setValidSession(false);
      })
      .finally(() => {
        setLoading(false);
      });
    // eslint-disable-next-line react-hooks/exhaustive-deps
  }, []);

  if (isLoading) {
    return <TJLoader />;
  }

  return (
    <div style={{ display: 'flex', justifyContent: 'center' }}>
      <ErrorModal
        errorMsg={
          isValidSession === true
            ? resolvedErrorMsg
            : {
                ...resolvedErrorMsg,
                cta: '',
              }
        }
        isValidSession={isValidSession === true}
        appSlug={appSlug}
        errorType={errorType}
        appDetails={appDetails}
        show={true}
        darkMode={darkMode}
      />
    </div>
  );
}

// Plain-text equivalent of the app-details list items (bullets there are CSS list markers, not literal characters).
const buildAppDetailsText = (details, appUrl) => {
  const lines = [`App: ${details.appName}`];
  if (details.folderName) {
    lines.push(`Folder: ${details.folderName}`);
  }
  lines.push(`URL: ${appUrl}`);
  return lines.join('\n');
};

