import React, { createContext, useContext, useMemo } from 'react';

import { useSortable } from '@dnd-kit/sortable';
import { CSS } from '@dnd-kit/utilities';

const SortableItemContext = createContext({
  attributes: {},
  listeners: undefined,
  ref() {},
});

export function SortableItem({ children, id, classNames }) {
  const { attributes, isDragging, listeners, setNodeRef, setActivatorNodeRef, transform, transition } = useSortable({
    id,
  });
  const context = useMemo(
    () => ({
      attributes,
      listeners,
      ref: setActivatorNodeRef,
    }),
    [attributes, listeners, setActivatorNodeRef]
  );
  const style = {
    opacity: isDragging ? 0.4 : undefined,
    transform: CSS.Translate.toString(transform),
    transition,
  };

  return (
    <SortableItemContext.Provider value={context}>
      <div {...attributes} {...listeners} ref={setNodeRef} className={classNames} style={style}>
        {children}
      </div>
    </SortableItemContext.Provider>
  );
}

export function DragHandle({ show = true }) {
  const { attributes, listeners, ref } = useContext(SortableItemContext);

  if (!show) {
    return <span className="DragHandle animation-fade"></span>;
  }

  return (
    <button className="DragHandle animation-fade" {...attributes} {...listeners} ref={ref}>
      <svg viewBox="0 0 20 20" width="12">
        <path d="M7 2a2 2 0 1 0 .001 4.001A2 2 0 0 0 7 2zm0 6a2 2 0 1 0 .001 4.001A2 2 0 0 0 7 8zm0 6a2 2 0 1 0 .001 4.001A2 2 0 0 0 7 14zm6-8a2 2 0 1 0-.001-4.001A2 2 0 0 0 13 6zm0 2a2 2 0 1 0 .001 4.001A2 2 0 0 0 13 8zm0 6a2 2 0 1 0 .001 4.001A2 2 0 0 0 13 14z"></path>
      </svg>
    </button>
  );
}

// hoc for wrapping components that need to be draggable
export function withDraggable(Component) {
  return function DraggableComponent(props) {
    const { attributes, listeners, ref } = useContext(SortableItemContext);

    return (
      <div {...attributes} {...listeners} ref={ref} className="draggable-container">
        <Component {...props} />
      </div>
    );
  };
}
