import React, { useEffect, useState } from 'react';
import { migrationsService } from '@/_services/migrations.service';
import { getSubpath } from '@/_helpers/routes';

const POLL_MS = 3000;

// A page that fails to load during an upgrade lands on the error route; while the upgrade runs, show its
// progress instead, and go back to the app once it ends. Plain on purpose: released apps reach it too.
export const UpgradeInProgress = ({ children }) => {
  const [status, setStatus] = useState(null);

  useEffect(() => {
    let cancelled = false;
    let timer;
    let sawRunning = false;
    const poll = async () => {
      const next = await migrationsService.getStatus();
      if (cancelled) return;
      if (next.state === 'running') {
        sawRunning = true;
        timer = setTimeout(poll, POLL_MS);
      } else if (sawRunning) {
        window.location.assign(`${getSubpath() ?? ''}/`);
        return;
      }
      setStatus(next);
    };
    poll();
    return () => {
      cancelled = true;
      clearTimeout(timer);
    };
  }, []);

  if (!status) return null;
  if (status.state !== 'running') return children;

  const { done, total } = status.progress ?? {};
  const percent = total ? Math.round((done / total) * 100) : 0;

  return (
    <main className="tw-fixed tw-inset-0 tw-z-[1100] tw-flex tw-items-center tw-justify-center tw-bg-background-surface-layer-01 tw-p-4">
      <div className="tw-flex tw-w-full tw-max-w-md tw-flex-col tw-gap-3" role="status" aria-live="polite">
        <h1 className="tw-m-0 tw-font-title-large tw-text-text-default">Scheduled maintenance in progress</h1>
        <p className="tw-m-0 tw-font-body-default tw-text-text-placeholder">This page will be available again soon.</p>
        <div
          role="progressbar"
          aria-label="Maintenance progress"
          aria-valuemin={0}
          aria-valuemax={100}
          aria-valuenow={percent}
          className="tw-h-2 tw-w-full tw-overflow-hidden tw-rounded-full tw-bg-background-surface-layer-02"
        >
          <div
            className="tw-h-full tw-bg-background-accent-strong tw-transition-[width] tw-duration-300"
            style={{ width: `${percent}%` }}
          />
        </div>
        <p className="tw-m-0 tw-font-body-small tw-text-text-placeholder">
          {total ? `${done} of ${total} done (${percent}%)` : `${percent}%`}
        </p>
      </div>
    </main>
  );
};
// Shared by the module viewer, both workflow popups and the workflow query editor so the same
// concept reads the same everywhere. BRANCH rows carry an opaque uuid in `name`, so nothing may
// render `v.name` without going through versionLabel.

// Persisted values, mirrored from server/src/modules/versions/ref-sentinels.ts. Changing either
// string orphans every query holding it.
export const DEFAULT_BRANCH_DRAFT_SENTINEL = '__default_branch_draft__';
export const WORKFLOW_CURRENT_BRANCH_SENTINEL = '__current_branch__';

export const badgeStyle = (bg, color) => ({
  backgroundColor: bg,
  color,
  padding: '0 6px',
  borderRadius: '4px',
  fontWeight: 500,
  lineHeight: '18px',
  flexShrink: 0,
});

export const VERSION_BADGES = {
  DRAFT: { text: 'Draft', bg: 'var(--background-warning-weak)', color: 'var(--text-warning)' },
  RELEASED: { text: 'Released', bg: 'var(--background-success-weak)', color: 'var(--text-success)' },
};

// The API returns both casings depending on the endpoint.
const versionType = (v) => v.version_type ?? v.versionType;

export const isCurrentBranchRow = (v, activeBranchId) => versionType(v) === 'branch' && v.branchId === activeBranchId;

export const isDefaultBranchDraft = (v) => versionType(v) === 'version' && v.status === 'DRAFT';

export function versionLabel(v, { activeBranchId, isOnMain, defaultBranchName, isGitSyncEnabled }) {
  if (isCurrentBranchRow(v, activeBranchId)) {
    return isOnMain ? defaultBranchName : 'Current branch';
  }
  if (isGitSyncEnabled && isDefaultBranchDraft(v)) return defaultBranchName;
  return v.displayName ?? v.name;
}

export function versionBadge(v) {
  return isDefaultBranchDraft(v) ? VERSION_BADGES.DRAFT : undefined;
}

// Mirrors getIsModuleSynced: all drafts in git means synced, any unsynced draft means not, and
// with no draft at all fall back to any version ever synced.
export const getIsWorkflowSynced = (versions = []) => {
  const drafts = versions.filter((v) => v.status === 'DRAFT');
  if (drafts.length === 0) return versions.some((v) => (v.is_synced ?? v.isSynced) === true);
  return drafts.every((v) => (v.is_synced ?? v.isSynced) === true);
};

