      },
      paddingLeft: '0px',
      ...(state.data.isFixed && { display: 'none' }),
    }),
    input: (base) => ({
      ...base,
      input: {
        height: '25px !important',
        color: 'var(--slate11) !important',
      },
    }),
    control: (base) => ({
      ...base,
      outline: 'none',
      border: '1px solid var(--slate7)',
      boxShadow: 'none',
      borderRadius: '6px',
      background: 'unset',
      '&:hover': {
        border: '1px solid var(--slate8)',
      },
    }),
    menuList: (base) => ({
      ...base,
      maxHeight: '200px',
    }),
    menu: (base) => ({
      ...base,
      background: darkMode ? '#1c1f26' : 'var(--slate1)',
      color: darkMode ? '#c1c8cd' : 'inherit',
      '.add-group-btn': {
        display: 'flex',
        justifyContent: 'flex-end',
        padding: '8px',
        borderTop: `1px solid ${darkMode ? '#2c3038' : 'var(--slate5)'}`,
        '.create-group': {
          background: 'none !important',
          '.rectangle-add-icon': {
            width: '20px',
            height: '20px',
          },
        },
      },
    }),
    menuPortal: (base) => ({
      ...base,
      zIndex: 1060,
    }),
    option: (base, state) => ({
      ...base,
      backgroundColor: state.isFocused ? (darkMode ? '#2c3038' : 'var(--slate3)') : 'transparent',
      color: darkMode ? '#c1c8cd' : 'inherit',
