};
// Per section: a component with matching events is listed in both Components and Events.
const entityKey = (group: ResultGroup, entity: ResultEntity) => `entity:${group.key}:${entity.entityId}`;

const TYPE_LABELS: Record<'all' | EntityType, string> = {
  all: 'All',
  component: 'Components',
  query: 'Queries',
  event: 'Events',
  page: 'Pages',
  app: 'App',
};

const plural = (count: number, word: string) => `${count.toLocaleString()} ${word}${count === 1 ? '' : 's'}`;

interface CodeSearchProps {
  darkMode: boolean;
  onClose: () => void;
  moduleId?: string;
}

const CodeSearch = ({ darkMode, onClose, moduleId = 'canvas' }: CodeSearchProps) => {
  const [term, options, setTerm, setOptions]: [
    string,
    CodeSearchOptions,
    (term: string) => void,
    (options: Partial<CodeSearchOptions>) => void,
  ] = useStore(
    (state: StoreState) => [
      state.codeSearch.term,
      state.codeSearch.options,
      state.setCodeSearchTerm,
      state.setCodeSearchOptions,
    ],
    shallow
  );
  const [pages, queries, events, globalSettings, pageSettings, currentPageId, queryIdNameMapping] = useStore(
    (state: StoreState) => [
      state.modules[moduleId]?.pages || EMPTY,
      state.dataQuery.queries.modules[moduleId] || EMPTY,
      state.eventsSlice.module[moduleId]?.events || EMPTY,
      state.globalSettings,
      state.pageSettings,
      state.modules[moduleId]?.currentPageId,
      state.modules[moduleId]?.queryIdNameMapping,
    ],
    shallow
  );

  const [debouncedTerm, setDebouncedTerm] = useState(term);
  const [activeIndex, setActiveIndex] = useState(-1);
  // Collapsed group (`group:<key>`) and entity (`entity:<id>`) keys; reset whenever the results change.
  const [collapsed, setCollapsed] = useState(() => new Set<string>());
  const rootRef = useRef<HTMLDivElement>(null);
  const activeRowRef = useRef<HTMLButtonElement>(null);

  useEffect(() => {
    rootRef.current?.querySelector('input')?.focus();
  }, []);

  useEffect(() => {
    const timer = setTimeout(() => setDebouncedTerm(term), SEARCH_DEBOUNCE_MS);
    return () => clearTimeout(timer);
  }, [term]);

  // Indexing and matching run in a worker (searchWorker.js); this thread only hands it the saved
  // definition, which it re-indexes when this object changes.
  const input = useMemo(
    () => ({ pages, queries, events, globalSettings, pageSettings, queryIdNameMapping, defs: getPlainDefs() }),
    [pages, queries, events, globalSettings, pageSettings, queryIdNameMapping]
  );
  // Re-index once edits settle, not on every save.
  const [indexedInput, setIndexedInput] = useState(input);
  useEffect(() => {
    const timer = setTimeout(() => setIndexedInput(input), INDEX_DEBOUNCE_MS);
    return () => clearTimeout(timer);
  }, [input]);

  const { caseSensitive, wholeWord, regex, type, currentPageOnly } = options;

  // The panel keeps showing the last result until the worker answers.
  const [result, setResult] = useState<SearchResult>(EMPTY_RESULT);
  useEffect(() => {
    if (debouncedTerm.length < MIN_TERM_LENGTH) return setResult(EMPTY_RESULT);
    let current = true;
    const filters = { caseSensitive, wholeWord, regex, type, currentPageOnly };
    runSearch({ input: indexedInput, term: debouncedTerm, filters, currentPageId }).then((outcome) => {
      if (!current || 'superseded' in outcome) return;
      setResult('timedOut' in outcome ? { ...EMPTY_RESULT, error: REGEX_TOO_SLOW } : outcome.result);
    });
    return () => {
      current = false;
    };
  }, [indexedInput, debouncedTerm, caseSensitive, wholeWord, regex, type, currentPageOnly, currentPageId]);

  useEffect(() => disposeSearchWorker, []);

  // A new search starts fully expanded; editing the app while searching keeps what you folded.
  useEffect(() => {
    setCollapsed(new Set());
    setActiveIndex(-1);
  }, [debouncedTerm, caseSensitive, wholeWord, regex, type, currentPageOnly]);

  // Rows the user can currently see, in display order — the keyboard moves through these.
  const visibleRows = useMemo(
    () =>
      result.groups.flatMap((group) =>
        collapsed.has(`group:${group.key}`)
          ? []
          : group.entities.flatMap((entity) => (collapsed.has(entityKey(group, entity)) ? [] : entity.rows))
      ),
    [result, collapsed]
  );

  useEffect(() => {
    activeRowRef.current?.scrollIntoView({ block: 'nearest' });
  }, [activeIndex]);

  const toggle = (key: string) =>
    setCollapsed((previous) => {
      const next = new Set(previous);
      next.has(key) ? next.delete(key) : next.add(key);
      return next;
    });

  const entityKeys = result.groups.flatMap((group) => group.entities.map((entity) => entityKey(group, entity)));
  const allCollapsed = entityKeys.length > 0 && entityKeys.every((key) => collapsed.has(key));
  // Like VS Code: collapse-all folds every entity and leaves sections open.
  const toggleAll = () => setCollapsed(allCollapsed ? new Set() : new Set(entityKeys));

  // Opening the same row again steps to its next occurrence; a clicked mark opens that one.
  const lastOpened = useRef<{ row: ResultRowData | null; occurrence: number }>({ row: null, occurrence: 0 });
  const open = (row: ResultRowData, occurrence?: number) => {
    const previous = lastOpened.current;
    const next = occurrence ?? (previous.row === row ? (previous.occurrence + 1) % row.matches.length : 0);
    lastOpened.current = { row, occurrence: next };
    setActiveIndex(visibleRows.indexOf(row));
    navigateToResult({ record: row.record, ...row.matches[next] }, moduleId);
  };

  const entityKeyOf = (row: ResultRowData) =>
    `entity:${SECTION_OF[row.record.entityType]}:${row.record.ownerId || row.record.entityId}`;

  const handleKeyDown = (e: KeyboardEvent<HTMLDivElement>) => {
    const activeRow = visibleRows[activeIndex];
    if (e.key === 'ArrowDown' || e.key === 'ArrowUp') {
      e.preventDefault();
      if (!visibleRows.length) return;
      const step = e.key === 'ArrowDown' ? 1 : -1;
      setActiveIndex((index) => (index + step + visibleRows.length) % visibleRows.length);
    } else if (e.key === 'Enter' && activeRow) {
      e.preventDefault();
      open(activeRow);
    } else if (
      activeRow &&
      (e.key === 'ArrowLeft' || e.key === 'ArrowRight') &&
      (e.target as HTMLElement).tagName !== 'INPUT'
    ) {
      e.preventDefault();
      const key = entityKeyOf(activeRow);
      if ((e.key === 'ArrowLeft') !== collapsed.has(key)) toggle(key);
      if (e.key === 'ArrowLeft') setActiveIndex(-1);
    } else if (e.key === 'Escape') {
      e.preventDefault();
      if (term) setTerm('');
      else onClose();
    }
  };

  const pageName = (pageId?: string | null) =>
    pages.find((page: { id: string; name: string }) => page.id === pageId)?.name || 'Page';
  // Sections don't split by page, so components and event owners carry their page — when there is
  // more than one to tell apart.
  const pageTagOf = (group: ResultGroup, entity: ResultEntity) =>
    pages.length > 1 && (group.key === 'components' || group.key === 'events') && entity.pageId
      ? pageName(entity.pageId)
      : null;
  const entityCount = result.groups.reduce((count, group) => count + group.entities.length, 0);
  const hasSearch = debouncedTerm.length >= MIN_TERM_LENGTH && !result.error;

  const renderRow = (row: ResultRowData) => {
    const index = visibleRows.indexOf(row);
    return (
      <ResultRow
        key={`${row.record.entityId}:${row.record.eventId || ''}:${row.record.fieldPath.join('.')}`}
        ref={index === activeIndex ? activeRowRef : undefined}
        row={row}
        active={index === activeIndex}
        onOpen={open}
      />
    );
  };

  const renderTree = () =>
    result.groups.map((group) => {
      const groupOpen = !collapsed.has(`group:${group.key}`);
      return (
        <div key={group.key} className="code-search-group">
          <button type="button" className="code-search-group-header" onClick={() => toggle(`group:${group.key}`)}>
            <Chevron open={groupOpen} />
            <span className="code-search-group-title">{SECTION_TITLES[group.key]}</span>
            <CountBadge count={group.count} />
          </button>
          {groupOpen &&
            group.entities.map((entity) => {
              const key = entityKey(group, entity);
              const entityOpen = !collapsed.has(key);
              const pageTag = pageTagOf(group, entity);
              return (
                <div key={entity.entityId} className="code-search-entity">
                  <button type="button" className="code-search-entity-header" onClick={() => toggle(key)}>
                    <Chevron open={entityOpen} />
                    <EntityIcon entity={entity} darkMode={darkMode} />
                    <span className="code-search-entity-name">{entity.entityName}</span>
                    {entity.entitySubtype && <span className="code-search-entity-type">{entity.entitySubtype}</span>}
                    {pageTag && (
                      <span className={cx('code-search-entity-page', { current: entity.pageId === currentPageId })}>
                        {pageTag}
                      </span>
                    )}
                    {entity.defined && <span className="code-search-tag">Defined</span>}
                    <CountBadge count={entity.count} />
                  </button>
                  {entityOpen && entity.rows.map(renderRow)}
                </div>
              );
            })}
        </div>
      );
    });

  const renderBody = () => {
    if (result.error) return <div className="code-search-empty code-search-error">{result.error}</div>;
    if (debouncedTerm.length < MIN_TERM_LENGTH)
      return (
        <div className="code-search-empty">Search names, bindings, queries, code and settings across all pages.</div>
      );
    if (result.total === 0)
      return (
        <div className="code-search-empty">
          No matches for “{debouncedTerm}”{currentPageOnly ? ' on this page' : ''}
          <div className="code-search-empty-actions">
            {currentPageOnly && (
              <ButtonComponent variant="ghost" size="small" onClick={() => setOptions({ currentPageOnly: false })}>
                Search all pages
              </ButtonComponent>
            )}
            <ButtonComponent variant="ghost" size="small" onClick={() => setTerm('')}>
              Clear search
            </ButtonComponent>
          </div>
        </div>
      );
    return renderTree();
  };

  const toolbarButton = ({
    key,
    title,
    pressed,
    onClick,
    icon: Icon,
  }: {
    key: string;
    title: string;
    pressed: boolean;
    onClick: () => void;
    icon: LucideIcon;
  }) => (
    <IconButton key={key} title={title} pressed={pressed} onClick={onClick}>
      <Icon width="14" height="14" />
    </IconButton>
  );

  return (
    <div ref={rootRef} className={cx('code-search', { 'dark-theme': darkMode })} onKeyDown={handleKeyDown}>
      <div className="inspector-header code-search-header">
        <div className="inspector-header-top">
          <span className="inspector-header-title">Code search</span>
          <ButtonComponent iconOnly leadingIcon="x" onClick={onClose} variant="ghost" size="medium" isLucid />
        </div>
        <div className="code-search-input-row">
          <div className="code-search-input">
            <InputComponent
              leadingIcon="search01"
              onChange={(e: React.ChangeEvent<HTMLInputElement>) => setTerm(e.target.value)}
              onClear={() => setTerm('')}
              size="medium"
              placeholder="Search in app"
              value={term}
              {...(term && { trailingAction: 'clear' })}
            />
          </div>
          {MATCH_TOGGLES.map(({ key, label, title, className }) => (
            <IconButton
              key={key}
              title={title}
              pressed={options[key]}
              className={cx('code-search-toggle--text', className)}
              onClick={() => setOptions({ [key]: !options[key] })}
            >
              {label}
            </IconButton>
          ))}
          <span className="code-search-divider" aria-hidden="true" />
          {toolbarButton({
            key: 'collapse',
            title: allCollapsed ? 'Expand all' : 'Collapse all',
            pressed: false,
            onClick: toggleAll,
            icon: allCollapsed ? ChevronsUpDown : ChevronsDownUp,
          })}
        </div>
        {/* Shown at zero results too, so "This page" can always be switched off. */}
        {hasSearch && (
          <div className="code-search-filters">
            <button
              type="button"
              aria-pressed={currentPageOnly}
              className={cx('code-search-chip', { active: currentPageOnly })}
              onClick={() => setOptions({ currentPageOnly: !currentPageOnly })}
            >
              <FileText width="11" height="11" aria-hidden="true" /> This page
            </button>
            {result.typeCounts.all > 0 && <span className="code-search-divider" aria-hidden="true" />}
            {result.typeCounts.all > 0 && (
              <div className="code-search-chips" role="radiogroup" aria-label="Filter by type">
                {(['all', ...RESULT_TYPES] as const)
                  .filter((key) => key === 'all' || result.typeCounts[key] > 0)
                  .map((key) => (
                    <button
                      type="button"
                      key={key}
                      role="radio"
                      aria-checked={type === key}
                      className={cx('code-search-chip', { active: type === key })}
                      onClick={() => setOptions({ type: key })}
                    >
                      {TYPE_LABELS[key]} <span className="code-search-chip-count">{result.typeCounts[key]}</span>
                    </button>
                  ))}
              </div>
            )}
          </div>
        )}
        {hasSearch && result.total > 0 && (
          <div className="code-search-summary">
            {result.truncated
              ? `Showing ${plural(result.rows.length, 'field')} of ${result.fieldCount.toLocaleString()}`
              : `${plural(result.total, 'result')} in ${plural(result.fieldCount, 'field')} · ${plural(
                  entityCount,
                  'item'
                )}`}
          </div>
        )}
      </div>
      <div className="code-search-results">{renderBody()}</div>
    </div>
  );
};

export default CodeSearch;
import React, { forwardRef } from 'react';
import cx from 'classnames';
import { ChevronDown, ChevronRight, FileText, Settings } from 'lucide-react';
import RawDataSourceIcon from '@/AppBuilder/QueryManager/Components/DataSourceIcon';
import WidgetIcon from '@/../assets/images/icons/widgets';
import type { PreviewSegment, ResultEntity, ResultRow as ResultRowData } from './searchRecords';

// Untyped JS component.
const DataSourceIcon = RawDataSourceIcon as React.ComponentType<any>;

export const EntityIcon = ({ entity, darkMode }: { entity: ResultEntity; darkMode: boolean }) => {
  const type = entity.entityType;
  if (type === 'query' && entity.query) return <DataSourceIcon source={entity.query} height={14} />;
  if (type === 'component' && entity.componentType)
    return (
      <WidgetIcon
        name={entity.componentType.toLowerCase()}
        fill={darkMode ? '#3A3F42' : '#D7DBDF'}
        width="14"
        height="14"
      />
    );
  if (type === 'page') return <FileText width="14" height="14" className="tw-text-icon-default" />;
  return <Settings width="14" height="14" className="tw-text-icon-default" />;
};

export const CountBadge = ({ count }: { count: number }) => (
  <span className="code-search-count">{count.toLocaleString()}</span>
);

export const Chevron = ({ open }: { open: boolean }) =>
  open ? (
    <ChevronDown width="12" height="12" className="code-search-chevron" />
  ) : (
    <ChevronRight width="12" height="12" className="code-search-chevron" />
  );

// Clicking a marked copy opens that copy; anywhere else on the row opens the first.
const Preview = ({
  segments,
  onOpenOccurrence,
  title = false,
}: {
  segments: PreviewSegment[];
  onOpenOccurrence: (occurrence?: number) => void;
  title?: boolean;
}) => (
  <span className={cx('code-search-row-preview', { 'code-search-row-title': title })}>
    {segments.map((segment, index) =>
      segment.match ? (
        <mark
          key={index}
          onClick={(e) => {
            e.stopPropagation();
            onOpenOccurrence(segment.occurrence);
          }}
        >
          {segment.text}
        </mark>
      ) : (
        segment.text
      )
    )}
  </span>
);

// The field's own name stands out from the path to it (`Fields › Email ›` muted, `Name` not), so
// it reads as where the snippet starts rather than one more crumb. A long path is cut, never the
// field name: `On page load → Show Al… › Alert type`.
const FieldLabel = ({ label }: { label: string }) => {
  const at = label.lastIndexOf(' › ');
  return (
    <span className="code-search-row-label">
      {at >= 0 && <span className="code-search-row-path">{label.slice(0, at)}</span>}
      {at >= 0 && <span className="code-search-row-sep">›</span>}
      <span className="code-search-row-field">{at >= 0 ? label.slice(at + 3) : label}</span>
    </span>
  );
};

// One field: short label, then the snippet with every occurrence marked; a badge when > 1.
interface ResultRowProps {
  row: ResultRowData;
  active: boolean;
  onOpen: (row: ResultRowData, occurrence?: number) => void;
}

export const ResultRow = forwardRef<HTMLButtonElement, ResultRowProps>(({ row, active, onOpen }, ref) => (
  <button
    ref={ref}
    type="button"
    className={cx('code-search-row', { active })}
    onClick={() => onOpen(row)}
    title={`${row.record.entityName} › ${row.record.fieldLabel}`}
  >
    {/* A row without a short label is its own title (an event handler: `Row clicked → Show Alert`). */}
    {row.record.shortLabel && <FieldLabel label={row.record.shortLabel} />}
    <Preview
      segments={row.preview}
      title={!row.record.shortLabel}
      onOpenOccurrence={(occurrence) => onOpen(row, occurrence)}
    />
    {row.matches.length > 1 && <CountBadge count={row.matches.length} />}
  </button>
));
ResultRow.displayName = 'ResultRow';
import toast from 'react-hot-toast';
import useStore from '@/AppBuilder/_stores/store';
import { RIGHT_SIDE_BAR_TAB } from '@/AppBuilder/RightSideBar/rightSidebarConstants';
import {
  flashPopover,
  focusTargetFor,
  landAnywhere,
  landOnTaggedField,
  popoverStepOf,
  tabKeyFor,
} from './highlightMatch';
import type { RevealStep } from './buildSearchRecords';
import type { SearchMatch } from './searchRecords';

// The App Builder store is untyped JS.
type StoreState = any;

const WAIT_TIMEOUT_MS = 5000;
// How long a reveal step may wait for the editor to open it (its list may still be mounting).
const REVEAL_STEP_TIMEOUT_MS = 1500;
// How long a field's code editor may take to mount and take the focus request.
const FOCUS_TIMEOUT_MS = 1000;
// Edited in the left sidebar's Libraries panel, not Global settings.
const LIBRARY_FIELDS = new Set(['preloadedScript', 'libraries']);

// Resolves true once `isReady(state)` holds, or false after the timeout.
const waitForStore = (isReady: (state: StoreState) => boolean, timeoutMs = WAIT_TIMEOUT_MS) =>
  new Promise<boolean>((resolve) => {
    if (isReady(useStore.getState())) return resolve(true);
    const timer = setTimeout(() => {
      unsubscribe();
      resolve(false);
    }, timeoutMs);
    const unsubscribe = useStore.subscribe((state: StoreState) => {
      if (!isReady(state)) return;
      clearTimeout(timer);
      unsubscribe();
      resolve(true);
    });
  });

// switchPage starts an async switch and returns nothing. Wait for the page id to change, not for
// `pageSwitchInProgress`: that flag clears only after the new page's exposed-value batch flushes,
// which on-load queries can push past any sensible wait, and selection does not need it.
const waitForPage = (pageId: string, moduleId: string) =>
  waitForStore((state) => state.modules[moduleId]?.currentPageId === pageId);

const openRightSidebar = (tab: string) => {
  const { setRightSidebarOpen, setActiveRightSideBarTab } = useStore.getState();
  setRightSidebarOpen(true);
  setActiveRightSideBarTab(tab);
};

const MODAL_TYPES = new Set(['Modal', 'ModalV2']);
const nextFrame = () =>
  new Promise<void>((resolve) => requestAnimationFrame(() => requestAnimationFrame(() => resolve())));
// Resolves after the event that started navigation has finished dispatching.
const afterCurrentEvent = () => new Promise<void>((resolve) => setTimeout(resolve));

// Makes a component visible on the canvas: opens every modal it sits in and switches every Tabs
// ancestor to the tab holding it, outermost first. A child's `parent` is the container id, or
// `<tabsId>-<tabId>` inside Tabs.
const revealOnCanvas = async (componentId: string, moduleId: string) => {
  const { getCurrentPageComponents, getAllExposedValues } = useStore.getState();
  const components = getCurrentPageComponents(moduleId);
  const steps: { containerId: string; action: 'open' | 'setTab'; tabId?: string }[] = [];
  const visited = new Set<string>();
  let parent = components?.[componentId]?.component?.parent;
  while (parent && !visited.has(parent)) {
    visited.add(parent);
    const containerId = parent.substring(0, 36);
    const type = components?.[containerId]?.component?.component;
    if (MODAL_TYPES.has(type)) steps.push({ containerId, action: 'open' });
    if (type === 'Tabs') steps.push({ containerId, action: 'setTab', tabId: parent.substring(37) });
    parent = components?.[containerId]?.component?.parent;
  }
  for (const { containerId, action, tabId } of steps.reverse()) {
    // Containers register open() / setTab() when they mount, which on a fresh page is a beat later.
    await waitForStore(() => typeof getAllExposedValues(moduleId)?.components?.[containerId]?.[action] === 'function');
    const exposed = getAllExposedValues(moduleId)?.components?.[containerId];
    if (action === 'open' && !exposed?.show) await exposed?.open?.();
    if (action === 'setTab' && exposed?.currentTab !== tabId) await exposed?.setTab?.(tabId);
    await nextFrame();
  }
};

// Asks the editor to open each step of the record's reveal chain (a list item's popover, a tab, an
// event handler), outermost first, waiting for each to be opened by its useCodeSearchReveal. A step
// nobody opens (its list isn't mounted, or isn't openable) ends the chain and is withdrawn so it
// can't fire later. Returns the opened steps, or `superseded` when a newer search took over.
const runReveal = async (steps: RevealStep[] = []): Promise<{ opened?: RevealStep[]; superseded?: boolean }> => {
  // A result click is an outside click for any popover already open, and its close handler runs on
  // the document after this one: opening the next popover before it would have it closed (and its
  // shared state, such as the page being edited, cleared) right away.
  await afterCurrentEvent();
  const opened: RevealStep[] = [];
  for (const step of steps) {
    const nonce = useStore.getState().requestCodeSearchReveal(step);
    await waitForStore((state) => state.codeSearch.revealRequest?.nonce !== nonce, REVEAL_STEP_TIMEOUT_MS);
    const current = useStore.getState().codeSearch.revealRequest;
    if (current?.nonce === nonce) {
      useStore.getState().consumeCodeSearchReveal(nonce);
      break;
    }
    if (current) return { superseded: true };
    opened.push(step);
  }
  return { opened };
};

// Asks the code editor showing the field to select the match (it takes the request itself, see
// codeSearchHighlight). Editors already on screen take it at once; one still mounting takes it when
// it mounts. A field without a code editor lands on its own tagged row instead.
const focusField = async (match: SearchMatch, opened: RevealStep[]) => {
  const target = focusTargetFor(match, opened);
  const { requestCodeSearchFocus, consumeCodeSearchFocus } = useStore.getState();
  const nonce = requestCodeSearchFocus(target);
  // Taken by an editor, or replaced by a newer result's request.
  const settled = (state: StoreState) => state.codeSearch.focusRequest?.nonce !== nonce;
  await nextFrame();
  if (settled(useStore.getState())) return;
  if (landOnTaggedField(target)) return consumeCodeSearchFocus(nonce);
  if (await waitForStore(settled, FOCUS_TIMEOUT_MS)) return;
  consumeCodeSearchFocus(nonce);
  landAnywhere(target);
};

// Opens the place a search match came from, then selects the match inside it.
export const navigateToResult = async (match: SearchMatch, moduleId = 'canvas'): Promise<unknown> => {
  const { record } = match;
  const state = useStore.getState();

  if (record.pageId && record.pageId !== state.getCurrentPageId(moduleId)) {
    const page = state.modules[moduleId].pages.find((p: { id: string }) => p.id === record.pageId);
    if (!page) return toast.error('That page no longer exists');
    state.switchPage(page.id, page.handle, [], moduleId);
    if (!(await waitForPage(page.id, moduleId))) return toast.error(`Couldn't open page ${page.name}`);
  }

  const ownerType = record.ownerType || record.entityType;
  const ownerId = record.ownerId || record.entityId;
  const { setSelectedComponents, queryPanel, setSelectedSidebarItem, setCodeSearchReturnToSearch } =
    useStore.getState();

  if (ownerType === 'component') {
    // Opening a modal selects the modal itself, so select the component after revealing it.
    await revealOnCanvas(ownerId, moduleId);
    setSelectedComponents([ownerId]);
    openRightSidebar(RIGHT_SIDE_BAR_TAB.CONFIGURATION);
    document.getElementById(ownerId)?.scrollIntoView({ behavior: 'smooth', block: 'nearest' });
  } else if (ownerType === 'query') {
    queryPanel.setSelectedQuery(ownerId, moduleId);
    queryPanel.expandQueryPaneIfNeeded();
  } else if (ownerId === 'pageSettings') {
    // App-wide navigation settings are edited in the right sidebar's Pages panel.
    openRightSidebar(RIGHT_SIDE_BAR_TAB.PAGES);
  } else if (ownerType === 'page') {
    // A page's own fields (hidden, disabled, icon, …) are edited in its details popover, which the
    // reveal chain opens.
    openRightSidebar(RIGHT_SIDE_BAR_TAB.PAGES);
  } else if (
    ownerType === 'app' &&
    LIBRARY_FIELDS.has(record.fieldPath[0]) &&
    useStore.getState().license?.featureAccess?.appJsLibraries
  ) {
    // The preloaded script's editor is a modal the reveal chain opens. Unlicensed, the Libraries
    // panel isn't offered, so these fall through to Global settings below.
    setSelectedSidebarItem('libraries');
  } else if (ownerType === 'app') {
    // Global settings replace this panel in the left sidebar; its header offers the way back, and
    // the search term survives in the store.
    setCodeSearchReturnToSearch(true);
    setSelectedSidebarItem('settings');
  }

  // Tabs (Properties / Styles, a query's tabs) put the field on screen. Popovers are flashed, not
  // opened: the result already names the path.
  const TAB_KINDS = new Set<RevealStep['kind']>(['queryTab', 'restTab']);
  const tabKey = tabKeyFor(record);
  const steps: RevealStep[] = [
    ...(tabKey ? [{ kind: 'inspectorTab' as const, ownerId, itemId: tabKey }] : []),
    ...(record.reveal || []).filter((step) => TAB_KINDS.has(step.kind)),
  ];
  const { opened = [], superseded } = steps.length ? await runReveal(steps) : { opened: [] };
  if (superseded) return;
  const popoverStep = popoverStepOf(record);
  if (popoverStep) return flashPopover(match, popoverStep);
  await focusField(match, opened);
};
// The only `import.meta` in code search: Jest can't parse it, so tests mock this module.
// Returns null when workers aren't available; the caller then searches on the main thread.
export const createCodeSearchWorker = (): Worker | null => {
  try {
    return new Worker(new URL('./codeSearch.worker.ts', import.meta.url));
  } catch {
    return null;
  }
};
// Runs code search in a Web Worker (codeSearch.worker.js): indexing a large app and matching every
// field would otherwise block the editor, and a user's regex with catastrophic backtracking
// (`(a+)+$`) would freeze it — a running RegExp can't be interrupted, only its worker terminated.

import { createCodeSearchWorker } from './createCodeSearchWorker';
import {
  createSearcher,
  searchRecords,
  type SearchInputDefinition,
  type SearchRequest,
  type SearchResult,
} from './searchRecords';

export type SearchOutcome = { result: SearchResult } | { timedOut: true } | { superseded: true };

interface PendingSearch {
  id: number;
  regex: boolean;
  timer: ReturnType<typeof setTimeout> | null;
  resolve: (outcome: SearchOutcome) => void;
  request: SearchRequest;
}

export const REGEX_TIMEOUT_MS = 2000;

let worker: Worker | null = null;
let postedInput: SearchInputDefinition | undefined; // the definition this worker instance has indexed
let pending: PendingSearch | null = null; // { id, regex, timer, resolve, request } of the search the worker is running
let nextId = 0;
// Main-thread fallback when workers can't start or the worker fails: same searcher, same results.
let workerFailed = false;
let mainThreadSearch: ReturnType<typeof createSearcher> | null = null;
let mainThreadInput: SearchInputDefinition | undefined;

const stop = () => {
  worker?.terminate();
  worker = null;
  postedInput = undefined;
};

const settle = (outcome: SearchOutcome) => {
  if (!pending) return;
  if (pending.timer) clearTimeout(pending.timer);
  const { resolve } = pending;
  pending = null;
  resolve(outcome);
};

const REGEX_NEEDS_WORKER = "Regular expression search isn't available in this browser";

// A user's regex can backtrack for seconds and can't be interrupted, so it never runs here.
const searchOnMainThread = ({ input, ...request }: SearchRequest): SearchOutcome => {
  if (request.filters?.regex) return { result: { ...searchRecords([], ''), error: REGEX_NEEDS_WORKER } };
  mainThreadSearch ||= createSearcher();
  const changed = input !== mainThreadInput;
  mainThreadInput = input;
  return {
    result: mainThreadSearch({
      ...request,
      input: changed ? input : undefined,
    }),
  };
};

const giveUpOnWorker = () => {
  workerFailed = true;
  stop();
};

// `input` is the app definition (see CodeSearch.jsx); it is posted only when it changed since the
// worker last indexed it. Resolves `{ result }`, `{ timedOut: true }` when a regex ran past the
// timeout, or `{ superseded: true }` when a newer search replaced this one.
export const runSearch = (request: SearchRequest): Promise<SearchOutcome> =>
  new Promise((resolve) => {
    if (pending) {
      const mayBeStuck = pending.regex;
      settle({ superseded: true });
      // A literal search finishes, so its stale reply is just dropped; a regex may never finish.
      if (mayBeStuck) stop();
    }
    if (!workerFailed && !worker) worker = createCodeSearchWorker();
    if (!worker) return resolve(searchOnMainThread(request));

    const { input, ...search } = request;
    const id = ++nextId;
    try {
      worker.postMessage({
        id,
        ...search,
        ...(input !== postedInput && { input }),
      });
    } catch {
      // DataCloneError: something in the definition can't be posted.
      giveUpOnWorker();
      return resolve(searchOnMainThread(request));
    }
    postedInput = input;

    const regex = Boolean(search.filters?.regex);
    const timer = regex
      ? setTimeout(() => {
          settle({ timedOut: true });
          stop();
        }, REGEX_TIMEOUT_MS)
      : null;
    pending = { id, regex, timer, resolve, request };
    worker.onmessage = ({ data }) => {
      if (data.id === pending?.id) settle({ result: data.result });
    };
    // The worker failed to load or threw: finish this search here and stay on the main thread.
    worker.onerror = (event) => {
      event.preventDefault();
      giveUpOnWorker();
      if (pending) settle(searchOnMainThread(pending.request));
    };
  });

// Called when the panel closes: frees the worker and its copy of the app.
export const disposeSearchWorker = () => {
  settle({ superseded: true });
  stop();
  mainThreadSearch = null;
  mainThreadInput = undefined;
};
