import React, { useMemo } from 'react';
import useStore from '@/AppBuilder/_stores/store';
import { getDeleteBlockers } from '@/AppBuilder/_utils/entityUsage';
import EntityDeleteDialog from '@/AppBuilder/Shared/EntityDelete/EntityDeleteDialog';
import { useModuleContext } from '@/AppBuilder/_contexts/ModuleContext';
import type { DeleteSubject } from '@/AppBuilder/_utils/entityUsage';
import type { ComponentsById, QueriesById } from '@/AppBuilder/LeftSidebar/Dependencies/types';

export type QueryDeleteConfirmationProps = {
  darkMode?: boolean;
};

/** Resolved once per opening of the dialog. */
type QueryDeleteState = {
  query: any;
  subjects: Array<{ id: string; name: string }>;
  blockers: DeleteSubject[];
  componentsById: ComponentsById;
  queriesById: QueriesById;
};

/**
 * Delete confirmation for queries. Lives at the pane level rather than inside
 * QueryCard: the folder tree mounts cards through its own renderer, so a card can be
 * unmounted (collapsed folder, reorder) while its query is the one being deleted.
 */
export const QueryDeleteConfirmation = ({ darkMode }: QueryDeleteConfirmationProps) => {
  const { moduleId } = useModuleContext();
  const deletingQueryId = useStore((state: any) => state.queryPanel.deletingQueryId);
  const deleteDataQuery = useStore((state: any) => state.queryPanel.deleteDataQuery);
  const deleteDataQueries = useStore((state: any) => state.dataQuery.deleteDataQueries);
  const setPreviewData = useStore((state: any) => state.queryPanel.setPreviewData);

  // Query being deleted plus whatever still references it, resolved once per opening.
  const { query, subjects, blockers, componentsById, queriesById } = useMemo<QueryDeleteState>(() => {
    if (!deletingQueryId) return { query: null, subjects: [], blockers: [], componentsById: {}, queriesById: {} };
    const state = useStore.getState() as any;
    const queries = state.dataQuery?.queries?.modules?.[moduleId] ?? [];
    const target = queries.find((item: any) => item.id === deletingQueryId);

    return {
      query: target,
      subjects: target ? [{ id: target.id, name: target.name }] : [],
      blockers: getDeleteBlockers(state, { queryIds: [deletingQueryId] }, moduleId),
      componentsById: state.getCurrentPageComponents(moduleId) ?? {},
      queriesById: Object.fromEntries(queries.map((item: any) => [item.id, item])),
    };
  }, [deletingQueryId, moduleId]);

  if (!query) return null;

  const executeDataQueryDeletion = () => {
    deleteDataQuery(null);
    deleteDataQueries(deletingQueryId);
    setPreviewData(null);
  };

  return (
    <EntityDeleteDialog
      show
      entityLabel="query"
      subjects={subjects}
      blockers={blockers}
      componentsById={componentsById}
      queriesById={queriesById}
      darkMode={darkMode}
      onCancel={() => deleteDataQuery(null)}
      onConfirm={executeDataQueryDeletion}
    />
  );
};

export default QueryDeleteConfirmation;
import React from 'react';
import { renderElement } from '../../Utils';
import Accordion from '@/AppBuilder/RightSideBar/Inspector/InspectorAccordion';
import { ADDITIONAL_ACTIONS_ACCORDION_ID } from '../../inspectorConstants';
import { EventManager } from '../../EventManager';
import { TreeSelectOptionsList } from '../TreeSelect/components';
import { useTreeSelectItemsManager } from '../TreeSelect/hooks';
import { getCascaderAdvancedToggleUpdates } from './utils';
import '../TreeSelect/treeSelect.scss';

const EventManagerComponent = EventManager as React.ComponentType<any>;
const TreeSelectOptionsListComponent = TreeSelectOptionsList as React.ComponentType<any>;

interface CascaderInspectorProps {
  componentMeta: Record<string, any>;
  darkMode?: boolean;
  [key: string]: any;
}

interface CascaderInspectorSection {
  id?: string;
  title: string;
  type?: string;
  properties?: string[];
  custom?: () => React.ReactNode;
  isOpen?: boolean;
  extraProps?: (property: string) => Record<string, any>;
}

type ParamUpdate = (param: Record<string, any>, attr: string, value: unknown, paramType: string) => void;

export const Cascader = ({ componentMeta, darkMode, ...restProps }: CascaderInspectorProps) => {
  const {
    layoutPropertyChanged,
    component,
    dataQueries,
    paramUpdated,
    currentState,
    eventsChanged,
    paramsUpdated,
    apps,
    allComponents,
    pages,
  } = restProps;

  // Reuse the Tree Select nested-options editor (selection-state fields hidden).
  const {
    treeItems,
    hoveredItemIndex,
    setHoveredItemIndex,
    expandedItems,
    toggleItemExpanded,
    handleItemChange,
    handleDeleteItem,
    handleAddItem,
    handleAddNestedItem,
    handleReorder,
    getResolvedValue,
  } = useTreeSelectItemsManager(component, paramUpdated);

  // Property organization
  let additionalActions: string[] = [];
  let dataProperties: string[] = [];

  for (const [key] of Object.entries(componentMeta?.properties || {})) {
    const prop = componentMeta?.properties[key];
    if (prop?.section === 'additionalActions') {
      additionalActions.push(key);
    } else if (prop?.accordian === 'Data') {
      dataProperties.push(key);
    }
  }

  const _renderTreeItems = () => (
    <TreeSelectOptionsListComponent
      treeItems={treeItems}
      darkMode={darkMode}
      hoveredItemIndex={hoveredItemIndex}
      onMouseEnter={setHoveredItemIndex}
      onMouseLeave={() => setHoveredItemIndex(null)}
      onDeleteItem={handleDeleteItem}
      onItemChange={handleItemChange}
      onAddItem={handleAddItem}
      onAddNestedItem={handleAddNestedItem}
      onReorder={handleReorder}
      getResolvedValue={getResolvedValue}
      expandedItems={expandedItems}
      onToggleExpand={toggleItemExpanded}
      showSelectionFields={false}
      {...restProps}
    />
  );

  const createRenderElement = (property: string, type = 'properties', extraProps: Record<string, any> = {}) => {
    return renderElement(
      component,
      componentMeta,
      extraProps.paramUpdated || paramUpdated,
      dataQueries,
      property,
      type,
      currentState,
      allComponents,
      extraProps.darkMode || darkMode,
      extraProps.placeholder || ''
    );
  };

  const createAccordionItem = (title: string, children: React.ReactNode, isOpen = true, id?: string) => ({
    id,
    title,
    isOpen,
    children,
  });

  const isAdvanced = getResolvedValue(component?.component?.definition?.properties?.advanced?.value);
  const handleAdvancedParamUpdated: ParamUpdate = (param, attr, value, paramType) => {
    if (attr === 'value' && value === false && paramsUpdated) {
      paramsUpdated(getCascaderAdvancedToggleUpdates(value));
      return;
    }

    paramUpdated(param, attr, value, paramType);
  };

  const sections: CascaderInspectorSection[] = [
    {
      title: 'Data',
      type: 'properties',
      properties: dataProperties,
    },
    {
      title: 'Options',
      custom: () => (
        <>
          {createRenderElement('advanced', 'properties', { paramUpdated: handleAdvancedParamUpdated })}
          {isAdvanced ? createRenderElement('data') : _renderTreeItems()}
          {/* Default value (static only) renders after the option UI; hidden when dynamic. */}
          {!isAdvanced && createRenderElement('value')}
          {isAdvanced && createRenderElement('optionsLoadingState')}
        </>
      ),
    },
    {
      title: 'Events',
      custom: () => (
        <EventManagerComponent
          sourceId={component?.id}
          eventSourceType="component"
          eventMetaDefinition={componentMeta}
          dataQueries={dataQueries}
          components={allComponents}
          eventsChanged={eventsChanged}
          apps={apps}
          darkMode={darkMode}
          pages={pages}
        />
      ),
    },
    {
      title: 'Validation',
      custom: () => (
        <>
          {Object.keys(componentMeta?.validation || {}).map((property) => createRenderElement(property, 'validation'))}
        </>
      ),
    },
    {
      id: ADDITIONAL_ACTIONS_ACCORDION_ID,
      title: 'Additional Actions',
      type: 'properties',
      properties: additionalActions,
      extraProps: (property) => ({
        placeholder: componentMeta.properties?.[property]?.placeholder,
      }),
    },
    {
      title: 'Devices',
      type: 'others',
      properties: ['showOnDesktop', 'showOnMobile'],
      extraProps: () => ({ paramUpdated: layoutPropertyChanged }),
    },
  ];

  const items = sections.map((section) => {
    if (section.custom) {
      return createAccordionItem(section.title, section.custom(), section.isOpen, section.id);
    }
    const children = (section.properties || []).map((property) => {
      const extraProps = section.extraProps ? section.extraProps(property) : {};
      return createRenderElement(property, section.type, extraProps);
    });
    return createAccordionItem(section.title, children, section.isOpen, section.id);
  });

  return <Accordion items={items} />;
};
export const getCascaderAdvancedToggleUpdates = (value: unknown) => {
  const updates = [{ param: { name: 'advanced' }, attr: 'value', value, paramType: 'properties' }];

  if (value === false) {
    updates.push({
      param: { name: 'optionsLoadingState' },
      attr: 'value',
      value: '{{false}}',
      paramType: 'properties',
    });
  }

  return updates;
};
import React, { useMemo } from 'react';
import i18next from 'i18next';

import Accordion from '@/_ui/Accordion';
import { EventManager } from '@/AppBuilder/RightSideBar/Inspector/EventManager';
import { renderElement } from '@/AppBuilder/RightSideBar/Inspector/Utils';
import { ADDITIONAL_ACTIONS_ACCORDION_ID } from '@/AppBuilder/RightSideBar/Inspector/inspectorConstants';
import { getLibraryComponentIdentity } from '@/AppBuilder/Widgets/libraryComponentRevision';
import { useEffectiveLibraryRevision } from '@/AppBuilder/Widgets/hooks/useEffectiveLibraryRevision';
import { useLibraryManifest } from '@/AppBuilder/Widgets/hooks/useLibraryManifest';
import {
  additionalActionProps,
  buildEventMetaDefinition,
  fieldMeta,
  filterVisibleProps,
  formatRevisionLabel,
  groupPropsBySection,
} from './utils';

import type { LibraryComponentPropertiesProps } from './types';

const AccordionComponent = Accordion as React.ComponentType<any>;
const EventManagerComponent = EventManager as React.ComponentType<any>;

// F4b: manifest-driven Inspector panel for the LibraryComponent widget (LLD §5.6,
// ModuleViewerInspector pattern). Identity (libraryId/componentName) lives ONLY in
// definition.properties — never rendered as editable fields. Props and events come
// from the PINNED revision's manifest (public, immutable-cached endpoint), so the
// Inspector always matches what the instance actually runs — not the library's latest.
export const LibraryComponentProperties = ({
  componentMeta,
  darkMode,
  layoutPropertyChanged,
  component,
  paramUpdated,
  dataQueries,
  currentState,
  eventsChanged,
  apps,
  allComponents,
  pages,
}: LibraryComponentPropertiesProps) => {
  const { libraryId, correlationId, componentName } = getLibraryComponentIdentity(component);

  // F5: same resolution as the runner — the library-level pin only, no per-instance
  // fallback — so the Inspector always describes the revision that's actually rendering.
  const effectiveRevision: string | undefined = useEffectiveLibraryRevision(correlationId);

  const manifest = useLibraryManifest(libraryId, effectiveRevision);

  const componentManifest = componentName ? manifest?.components?.[componentName] : undefined;
  const props = componentManifest?.props ?? [];
  const visibleProps = filterVisibleProps(props);
  const events = componentManifest?.events ?? [];

  const eventMetaDefinition = useMemo(() => buildEventMetaDefinition(componentMeta, events), [componentMeta, events]);

  // Static widget-config properties (e.g. visibility) — never come from the manifest, so
  // they must be rendered on top of it here, not folded into visibleProps.
  const staticProps = additionalActionProps(componentMeta);

  const items: { id?: string; title: string; isOpen: boolean; children: React.ReactNode }[] = [];

  // Identity — read-only context (picker UX arrives with F5's revision picker).
  items.push({
    title: 'Component',
    isOpen: true,
    children: (
      <div style={{ display: 'flex', flexDirection: 'column', gap: 8, padding: '4px 0' }}>
        {[
          ['Component', componentManifest?.displayName ?? componentName],
          ['Revision', formatRevisionLabel(effectiveRevision)],
        ].map(([label, value]) => (
          <div key={label} style={{ display: 'flex', justifyContent: 'space-between', fontSize: 12 }}>
            <span style={{ color: 'var(--text-placeholder)' }}>{label}</span>
            <span style={{ color: 'var(--text-default)', fontWeight: 500 }}>{value}</span>
          </div>
        ))}
      </div>
    ),
  });

  groupPropsBySection(visibleProps).forEach(({ title, props: sectionProps }) => {
    items.push({
      title,
      isOpen: true,
      children: (
        <>
          {sectionProps.map((prop) =>
            renderElement(
              component,
              componentMeta,
              paramUpdated,
              dataQueries,
              prop.name,
              'properties',
              currentState,
              allComponents,
              darkMode,
              '',
              undefined,
              null,
              fieldMeta(prop) as any // renderElement (untyped JS) infers customMeta as `null` from its default param
            )
          )}
        </>
      ),
    });
  });

  if (events.length > 0) {
    items.push({
      title: `${i18next.t('widget.common.events', 'Events')}`,
      isOpen: true,
      children: (
        <EventManagerComponent
          sourceId={component?.id}
          eventSourceType="component"
          eventMetaDefinition={eventMetaDefinition}
          currentState={currentState}
          dataQueries={dataQueries}
          components={allComponents}
          eventsChanged={eventsChanged}
          apps={apps}
          darkMode={darkMode}
          pages={pages}
        />
      ),
    });
  }

  if (staticProps.length > 0) {
    items.push({
      id: ADDITIONAL_ACTIONS_ACCORDION_ID,
      title: `${i18next.t('widget.common.additionalActions', 'Additional Actions')}`,
      isOpen: true,
      children: (
        <>
          {staticProps.map((property) =>
            renderElement(
              component,
              componentMeta,
              paramUpdated,
              dataQueries,
              property,
              'properties',
              currentState,
              allComponents,
              darkMode,
              (componentMeta.properties as Record<string, { placeholder?: string }>)?.[property]?.placeholder
            )
          )}
        </>
      ),
    });
